def _link_device_identity(sleeper_user_id: str | None = None,
                          account_id: str | None = None) -> None:
    """Best-effort identity_links upsert on successful sign-in.

    Reads device_id from the request body or X-Device-Id header; no-op when
    the client didn't send one. Never raises — sign-in must not break on
    analytics stitching.
    """
    try:
        body = request.get_json(force=True, silent=True) or {}
        device_id = (str(body.get("device_id") or "").strip()
                     or (request.headers.get("X-Device-Id") or "").strip())
        if device_id:
            link_identity(device_id, sleeper_user_id=sleeper_user_id,
                          account_id=account_id)
    except Exception as e:
        log.debug("identity link skipped: %s", e)


def _record_trends_snapshot(service, user_id, league, fmt, changed_pids) -> None:
    """Best-effort elo_history append so ALL ranking flows feed the Trends
    tab (#164). Historically only the trio-swipe route (/api/rank3) wrote
    elo_history, so users who ranked exclusively via Quick Set / Quick Rank /
    manual reorder / Pick Anchor saw an empty Trends screen ("Keep ranking to
    see trends here") no matter how much they ranked. Mirrors the rank3
    snapshot block: write only the players this submission actually changed;
    failures never block the save."""
    try:
        pid_set = {str(p) for p in changed_pids if p}
        if not pid_set:
            return
        changed = {
            rp.player.id: rp.elo
            for rp in service.get_rankings(position=None).rankings
            if rp.player.id in pid_set
        }
        if changed:
            record_elo_snapshot(
                user_id         = user_id,
                league_id       = league.league_id if league else None,
                scoring_format  = fmt,
                changed_ratings = changed,
            )
    except Exception as db_err:
        log.warning("elo_history snapshot failed (continuing): %s", db_err)


@app.route("/api/tiers/save", methods=["POST"])
@_gate_unverified_write
def save_tiers_route():
    """POST /api/tiers/save {position: 'RB', tiers: {first_1: [...ids], ...}, cleared_pids: [...], demoted_pids: [...]}

    Converts tier assignments into ELO overrides and marks the position as saved.

    `cleared_pids` (optional): list of pids the user explicitly removed
    from all tiers (× button → back to pool). Their override is deleted
    so they don't snap back to a previous tier on the next refresh.

    `demoted_pids` (optional, #161): pids the user explicitly passed over
    in a Quick Set tier save (visible-but-unselected players previously in
    the saved tier or higher). Pinned below every band (unranked/pending)
    so they don't silently keep the old higher tier. Skip never demotes —
    the client only sends this on an explicit save with picks.
    """
    sess = _require_initialized_session()
    service   = sess["service"]
    g_user_id = sess["user_id"]
    g_league  = sess["league"]
    fmt       = _active_format(sess)
    body      = request.get_json(force=True) or {}
    position  = body.get("position")
    tiers     = body.get("tiers", {})
    cleared_pids = body.get("cleared_pids") or []
    if not isinstance(cleared_pids, list):
        cleared_pids = []
    cleared_pids = [str(x) for x in cleared_pids if x]
    demoted_pids = body.get("demoted_pids") or []
    if not isinstance(demoted_pids, list):
        demoted_pids = []
    demoted_pids = [str(x) for x in demoted_pids if x]

    if position not in ("QB", "RB", "WR", "TE"):
        return jsonify({"error": f"Invalid position: {position!r}"}), 400

    # Must have at least one player in some tier OR something to clear or
    # demote. (Pure "clear-only" saves are valid — e.g. user removes their
    # last tier-placed RB; we still need to apply the deletion server-side.)
    total_assigned = sum(len(ids) for ids in tiers.values() if isinstance(ids, list))
    if total_assigned == 0 and not cleared_pids and not demoted_pids:
        return jsonify({"error": "No players in any tier"}), 400

    # M2 — a SCOPED save writes only part of the board. Read behind the flag,
    # so an old-flag-off server ignores the key entirely.
    scope = body.get("scope") if is_enabled("ranks.rookie_subset") else None

    try:
        if scope == "rookie":
            # `tier_overrides` is a wholesale-overwritten blob with no
            # history, and this is the first feature that writes a PARTIAL
            # board. Snapshot BEFORE any mutation — idempotent, so this costs
            # one indexed read per scoped save after the first.
            try:
                take_tier_override_snapshot(g_user_id)
            except Exception as snap_err:
                log.warning("pre-scope snapshot failed: %s", snap_err)
            # The merged-band rule: merge the scoped pids into the band's
            # current full order, spread over the FULL merged list, persist
            # the scoped pids ONLY. See RankingService.apply_tiers_subset.
            service.apply_tiers_subset(
                position=position,
                tiers=tiers,
                scope_pids=_rookie_scope_ids(sess),
                scoring_format=fmt,
                cleared_pids=cleared_pids,
                demoted_pids=demoted_pids,
            )
        else:
            # apply_tiers assigns ELOs inside each tier's band (see
            # backend/tier_config.json) so on reload the frontend re-buckets
            # players into the same tier they were placed. Bands are
            # position+format-aware. cleared_pids lets the frontend tell us
            # "this player is back in the pool — drop their override";
            # demoted_pids pins passed-over players below every band (#161).
            service.apply_tiers(
                position=position,
                tiers=tiers,
                scoring_format=fmt,
                cleared_pids=cleared_pids,
                demoted_pids=demoted_pids,
            )

        # Persist the full tier override dict for THIS format so it survives
        # session rebuilds. The other format's overrides are untouched.
        try:
            save_tier_overrides(g_user_id, service._elo_overrides, scoring_format=fmt)
        except Exception as db_err:
            log.warning("save_tier_overrides failed: %s", db_err)

        # Persist updated ELO snapshot to member_rankings (per-format row) so
        # leaguemates see this rank set when generating trades in this format.
        try:
            if g_league and g_league.league_id not in ("league_demo",):
                all_rankings = service.get_rankings(position=None)
                ranking_payload = [
                    {"player_id": rp.player.id, "elo": rp.elo}
                    for rp in all_rankings.rankings
                ]
                upsert_member_rankings(
                    user_id        = g_user_id,
                    league_id      = g_league.league_id,
                    rankings       = ranking_payload,
                    scoring_format = fmt,
                )
        except Exception as db_err:
            log.warning("member_rankings publish after tiers save failed: %s", db_err)

        # F5 (deck.taste_vectors) — board saves refresh the board-derived
        # taste prior (flag-gated + never-throwing inside the helper).
        _refresh_taste_board_prior(g_user_id, service)

        # #164 — feed the Trends tab: tier placements (and clears, whose ELO
        # reverted) are ranking changes and must land in elo_history.
        assigned_pids = [
            str(pid) for ids in tiers.values() if isinstance(ids, list)
            for pid in ids
        ]
        _record_trends_snapshot(
            service, g_user_id, g_league, fmt, assigned_pids + cleared_pids)

        # Mark this position as saved for the active format.
        #
        # NOT under scope (M2, I-4). `tiers_saved` / `all_done` are
        # COMPLETENESS markers, and a rookies-only save does not complete a
        # position. One line, four downstream surfaces: LeagueScreen's ranked
        # count, quicksetProgress's cache, the web celebration, and #244
        # launch routing.
        if scope == "rookie":
            saved = get_tiers_saved(g_user_id, scoring_format=fmt)   # READ only
        else:
            saved = save_tiers_position(g_user_id, position, scoring_format=fmt)
        all_done = all(p in saved for p in ("QB", "RB", "WR", "TE"))

        # Tracking plan v2 §S3 — tier_save into user_events. This is the ONLY
        # tier_save writer since the analytics P0 cutover (the legacy
        # wrapped_events hook inside save_tiers_position is gone; LLD §6.4).
        # tier_save is now a rank-class streak event, so tz rides along for
        # local-day streak math. `via` lets QuickSet saves self-identify;
        # default 'tiers' keeps old clients honest.
        # M2 (KD-10): the `rookie_*` tags are the forensic trail the board-
        # restore procedure keys off ("confirm the damage window from the
        # user's via:'rookie_*' events"). The whitelist is EXTENDED, never
        # replaced — an unrecognised via still falls back to "tiers".
        via = (body.get("via")
               if body.get("via") in ("tiers", "quickset", "rookie_tiers",
                                      "rookie_quickset", "rookie_anchors")
               else "tiers")

        # P0-1: a COMPLETENESS-marking save is the one that should own the
        # unlock rule. A rookie-scope save deliberately does not complete a
        # position (see the tiers_saved comment above), and the rookie_* via
        # tags are subset boards — neither may pin the user to a rule they
        # never opted into. `allow_over=("anchor",)` is the single approved
        # upgrade (hld.md S-01): 'anchor' can never satisfy any unlock
        # branch, so letting it shadow a finished Quick Set board would be a
        # NEW failure created by this fix.
        if scope != "rookie" and via in ("tiers", "quickset"):
            _note_ranking_method(sess, via, allow_over=("anchor",))

        try:
            record_event(
                g_user_id, "tier_save",
                league_id=getattr(g_league, "league_id", None),
                source="api",
                props={"position": position, "changed_count": total_assigned,
                       "via": via, "scoring_format": fmt},
                tz=getattr(g, "user_tz", None),
                **(getattr(g, "device_info", {}) or {}),
            )
        except Exception as ev_err:
            log.warning("record_event(tier_save) failed: %s", ev_err)

        # FR-20 (analytics P0, LLD §6.4b): QuickSet completion is a
        # first-class funnel event — one per position committed through the
        # QuickSet walk. duration_ms/skipped are client-passed (absent from
        # old binaries → null).
        if via == "quickset":
            try:
                record_event(
                    g_user_id, "quickset_completed",
                    league_id=getattr(g_league, "league_id", None),
                    source="api",
                    props={"position": position,
                           "players_placed": total_assigned,
                           "duration_ms": body.get("duration_ms"),
                           "skipped": bool(body.get("skipped"))},
                    **(getattr(g, "device_info", {}) or {}),
                )
            except Exception as ev_err:
                log.warning("record_event(quickset_completed) failed: %s", ev_err)

        log.info("tiers/save [%s] %s for %s — saved: %s, all_done=%s",
                 fmt, position, g_user_id, saved, all_done)

        return jsonify({
            "ok":             True,
            "position":       position,
            "saved":          saved,
            "all_done":       all_done,
            "count":          total_assigned,
            "scoring_format": fmt,
        })
    except Exception as e:
        log.error("tiers/save error: %s", e)
        return jsonify({"error": "internal_error"}), 500


@app.route("/api/anchor/save", methods=["POST"])
@_gate_unverified_write
def save_anchor_route():
    """POST /api/anchor/save {player_id: '4046', anchor: '2_firsts'}

    Pick-anchor wizard: pin a player's Elo to a pick-denominated value
    statement ("worth 2 firsts", "worth a mid 2nd", "no trade value").
    Anchors are position-uniform by design — the pick ladder drives the
    same valuation across position groups, and tier assignment falls out
    of the pinned Elo via the normal band walk (tier_for_elo). Writes the
    same authoritative override apply_tiers uses, so the placement shows
    up on Tiers, in trade math, and for leaguemates immediately.
    """
    sess = _require_initialized_session()
    service   = sess["service"]
    g_user_id = sess["user_id"]
    g_league  = sess["league"]
    fmt       = _active_format(sess)
    body      = request.get_json(force=True) or {}
    player_id = str(body.get("player_id") or "").strip()
    anchor    = str(body.get("anchor") or "").strip()
    # draft-extensions W1 — optional surface attribution. Whitelisted with a
    # fallback (never a 400) and request-only; the response is unchanged.
    raw_via   = str(body.get("via") or body.get("surface") or "").strip()
    via       = raw_via if raw_via in _ANCHOR_VIA else "anchors"

    if not player_id:
        return jsonify({"error": "player_id required"}), 400
    if anchor not in VALID_ANCHORS:
        return jsonify({"error": f"Invalid anchor: {anchor!r}",
                        "valid_anchors": sorted(VALID_ANCHORS)}), 400

    # #111 — the user's pick-value scale re-spaces the multi-first anchors.
    # Best-effort read: any DB hiccup falls back to the legacy default.
    try:
        top_tier_firsts = (load_anchor_scale(g_user_id, scoring_format=fmt)
                           or ANCHOR_TOP_TIER_FIRSTS_DEFAULT)
    except Exception as db_err:
        log.warning("load_anchor_scale failed (using default): %s", db_err)
        top_tier_firsts = ANCHOR_TOP_TIER_FIRSTS_DEFAULT

    target_elo = _anchor_target_elo(anchor, top_tier_firsts=top_tier_firsts)

    try:
        player = service.apply_anchor(player_id, target_elo)
        if player is None:
            return jsonify({"error": f"Unknown player_id: {player_id}"}), 404

        # Persist the override dict for THIS format (same path as tiers/save)
        # so the anchor survives session rebuilds.
        try:
            save_tier_overrides(g_user_id, service._elo_overrides, scoring_format=fmt)
        except Exception as db_err:
            log.warning("save_tier_overrides after anchor failed: %s", db_err)

        # Publish the updated Elo snapshot so leaguemates' trade generation
        # sees the anchored value (mirrors tiers/save).
        try:
            if g_league and g_league.league_id not in ("league_demo",):
                all_rankings = service.get_rankings(position=None)
                ranking_payload = [
                    {"player_id": rp.player.id, "elo": rp.elo}
                    for rp in all_rankings.rankings
                ]
                upsert_member_rankings(
                    user_id        = g_user_id,
                    league_id      = g_league.league_id,
                    rankings       = ranking_payload,
                    scoring_format = fmt,
                )
        except Exception as db_err:
            log.warning("member_rankings publish after anchor failed: %s", db_err)

        # F5 (deck.taste_vectors) — board saves refresh the board-derived
        # taste prior (flag-gated + never-throwing inside the helper).
        _refresh_taste_board_prior(g_user_id, service)

        # #164 — feed the Trends tab (see _record_trends_snapshot).
        _record_trends_snapshot(service, g_user_id, g_league, fmt, [player_id])

        # P0-1: only the WIZARD marks a method. Answering an anchor inside
        # the Draft Room (_ANCHOR_VIA = ("anchors","draft_room"), :1283) is
        # not "I chose the Pick Anchor flow as my ranking method", and
        # 'anchor' is the branch that can never unlock — pinning it from a
        # draft-room tap would lock a user on a side quest.
        if via == "anchors":
            _note_ranking_method(sess, "anchor")

        tier = service.tier_for_elo(target_elo, player.position, fmt)

        # Tracking plan v2 §S3 — anchor_answered. Skips never reach this
        # route (client-side only), so skipped is always False here.
        try:
            record_event(
                g_user_id, "anchor_answered",
                league_id=getattr(g_league, "league_id", None),
                source="api",
                props={"player_id": player_id, "pick_value": anchor,
                       "skipped": False, "via": via},
                # #152 — anchor_answered is a rank-class streak event now,
                # so tz rides along for local-day streak math (same as
                # trio_swipe / tier_save).
                tz=getattr(g, "user_tz", None),
                **(getattr(g, "device_info", {}) or {}),
            )
        except Exception as ev_err:
            log.warning("record_event(anchor_answered) failed: %s", ev_err)

        log.info("anchor/save [%s] %s → %s (elo %.0f, tier %s) for %s",
                 fmt, player_id, anchor, target_elo, tier, g_user_id)

        return jsonify({
            "ok":              True,
            "player_id":       player_id,
            "anchor":          anchor,
            "elo":             round(target_elo, 1),
            "value":           round(_trade_service_mod.elo_to_value(target_elo), 1),
            "tier":            tier,
            "scoring_format":  fmt,
            "top_tier_firsts": top_tier_firsts,
        })
    except Exception as e:
        log.error("anchor/save error: %s", e)
        return jsonify({"error": "internal_error"}), 500


@app.route("/api/anchor/scale", methods=["GET", "POST"])
@_gate_unverified_write
@_gate_unverified_read
def anchor_scale_route():
    """GET/POST /api/anchor/scale — per-user pick-value scale (#111).

    {top_tier_firsts: 2|3|4} = "a top-tier dynasty asset is worth N firsts".
    Persisted per user + scoring format (users.anchor_scale). Recalibrates
    ONLY the anchor wizard's multi-first keys (see _anchor_target_elo);
    single-pick anchors, the generic pick assets in the pool, and the
    public calculator gap line stay consensus-denominated. Default 2 ==
    the legacy mapping, so users who never touch it see identical behavior.
    """
    sess = _require_session()
    g_user_id = sess["user_id"]
    fmt = _active_format(sess)

    if request.method == "GET":
        try:
            n = (load_anchor_scale(g_user_id, scoring_format=fmt)
                 or ANCHOR_TOP_TIER_FIRSTS_DEFAULT)
        except Exception as db_err:
            log.warning("anchor/scale read failed (using default): %s", db_err)
            n = ANCHOR_TOP_TIER_FIRSTS_DEFAULT
        return jsonify({"top_tier_firsts": n, "scoring_format": fmt})

    body = request.get_json(force=True) or {}
    try:
        n = float(body.get("top_tier_firsts"))
    except (TypeError, ValueError):
        return jsonify({"error": "top_tier_firsts must be a number",
                        "valid_values": list(ANCHOR_TOP_TIER_FIRSTS_CHOICES)}), 400
    if n not in ANCHOR_TOP_TIER_FIRSTS_CHOICES:
        return jsonify({"error": f"Invalid top_tier_firsts: {n!r}",
                        "valid_values": list(ANCHOR_TOP_TIER_FIRSTS_CHOICES)}), 400
    try:
        save_anchor_scale(g_user_id, n, scoring_format=fmt)
    except Exception as e:
        log.error("anchor/scale save error: %s", e)
        return jsonify({"error": "internal_error"}), 500
    log.info("anchor/scale [%s] top_tier_firsts=%s for %s", fmt, n, g_user_id)
    return jsonify({"ok": True, "top_tier_firsts": n, "scoring_format": fmt})


