# ---------------------------------------------------------------------------
# Share landing for arbitrary packages (teardown S7 PRD-01 follow-up,
# flag `growth.share_landing`; W2B handoff).
#
# /s/trade/<match_id> only works for MUTUAL matches (a trade_matches row).
# Calculator builds and liked-but-unmatched trades previously fell back to
# the bare site root. This trio gives them a real landing object:
#   POST /api/share/package  (session-authed, rate-limited) → /s/p/<id>
#   GET  /s/p/<short_id>     public OG landing page
#   GET  /og/p/<short_id>.png rendered card (same style as trade cards)
# ---------------------------------------------------------------------------

_SHARE_PACKAGE_HOURLY_LIMIT = 20      # per user — abuse guard, not a product cap
_SHARE_PACKAGE_SIDE_MAX = 5           # mirrors the trade engine's package cap
_SHARE_PACKAGE_ID_RE = re.compile(r"^[A-Za-z0-9_.\-]{1,40}$")


def _clean_package_side(raw) -> list[str] | None:
    """Normalise one side's player-id list. None = invalid payload."""
    if raw is None:
        return []
    if not isinstance(raw, list) or len(raw) > _SHARE_PACKAGE_SIDE_MAX:
        return None
    out: list[str] = []
    for x in raw:
        s = str(x).strip()
        if not _SHARE_PACKAGE_ID_RE.match(s):
            return None
        out.append(s)
    return out


@app.route("/api/share/package", methods=["POST"])
def create_share_package_route():
    """POST /api/share/package — snapshot an arbitrary give/receive package
    for a public share landing. 404 while `growth.share_landing` is dark.

    Body: {"give_player_ids": [...], "receive_player_ids": [...]}
    → {ok, short_id, url: "/s/p/<id>", og_image: "/og/p/<id>.png"}
    Demo sessions are refused (shared demo user would pool the rate limit
    and demo shares are disabled client-side anyway).
    """
    if not is_enabled("growth.share_landing"):
        return jsonify({"error": "not_found"}), 404
    sess = _require_session()
    user_id = str(sess.get("user_id") or "")
    if sess.get("is_demo") or user_id.startswith("demo_user_"):
        return jsonify({"error": "demo_session"}), 400

    body = request.get_json(force=True, silent=True) or {}
    give = _clean_package_side(body.get("give_player_ids"))
    receive = _clean_package_side(body.get("receive_player_ids"))
    if give is None or receive is None or not (give or receive):
        return jsonify({
            "error": "bad_package",
            "message": ("give_player_ids/receive_player_ids must be lists of "
                        f"player ids, at most {_SHARE_PACKAGE_SIDE_MAX} per "
                        "side, at least one player overall."),
        }), 400

    try:
        recent = count_recent_shared_packages(user_id, hours=1)
    except Exception as e:
        log.warning("share/package: rate-limit count failed: %s", e)
        recent = 0
    if recent >= _SHARE_PACKAGE_HOURLY_LIMIT:
        return jsonify({"error": "rate_limited",
                        "message": "Too many shares — try again later."}), 429

    for _ in range(4):   # token_urlsafe(6) collisions are ~impossible; belt+braces
        short_id = secrets.token_urlsafe(6)
        if create_shared_package(short_id, user_id, give, receive):
            return jsonify({
                "ok": True,
                "short_id": short_id,
                "url": f"/s/p/{short_id}",
                "og_image": f"/og/p/{short_id}.png",
            })
    log.error("share/package: could not mint a short_id for %s", user_id)
    return jsonify({"error": "store_failed"}), 500


@app.route("/s/p/<short_id>")
def share_package_page(short_id):
    """Public OG landing page for a shared package (flag growth.share_landing)."""
    if not is_enabled("growth.share_landing"):
        return jsonify({"error": "not_found"}), 404
    try:
        pkg = load_shared_package(short_id)
    except Exception as e:
        log.warning("share/package page lookup failed: %s", e)
        pkg = None
    if pkg is None:
        return jsonify({"error": "not_found"}), 404
    n = len(pkg["give_ids"]) + len(pkg["receive_ids"])
    return _share_html(
        title="Trade Package",
        description=(f"A {n}-player dynasty trade package — see the give/get "
                     "breakdown and fairness read."),
        image_url=f"/og/p/{short_id}.png",
        cta_text="Build your own trade",
        cta_url="/",
    )


@app.route("/og/p/<short_id>.png")
def og_package_card(short_id):
    """Render a shared package as a 1200x630 OG PNG (flag growth.share_landing)."""
    if not is_enabled("growth.share_landing"):
        return jsonify({"error": "not_found"}), 404
    if _og_image is None:
        return _og_unavailable_response()
    try:
        png, status = _og_image.render_package_card(short_id)
    except Exception as e:
        log.error("og_package_card error (%s): %s", short_id, e)
        png = _og_image.render_placeholder_card("Share card unavailable", str(e)[:80])
        status = 500
    return _png_response(png, status=status)


# ---------------------------------------------------------------------------
# Browser extension — /api/extension/auth + /api/extension/rankings
# ---------------------------------------------------------------------------
# The Chrome/Edge extension injects the user's personal tier + pos-rank next
# to player names on sleeper.com. It needs a lean auth that takes a Sleeper
# username (same UX as the main app) and a compact rankings payload. We do
# NOT reuse /api/session/init because (a) the extension can't drive the
# full frontend Sleeper-fetch flow, and (b) we don't need the trade service
# or opponent-member hydration for read-only badge injection.

def _extension_build_session(user_id: str, username: str,
                             display_name: str, avatar: str | None,
                             token: str | None = None) -> tuple[str, dict]:
    """Build a user-scoped session for the browser extension.

    `token` re-registers the session under an existing bearer token —
    used only by the persistent-session restore path (teardown 06-03),
    where the client still holds the pre-restart token. Default (None)
    mints a fresh one.

    No league locked in — the scoring format is resolved per-request from
    the league_id query param on /api/extension/rankings. Builds one
    RankingService per scoring_format with swipes + tier overrides
    replayed, so switching leagues on sleeper.com just picks the right
    service instantly.

    Returns (token, session_payload).
    """
    # Ensure the Sleeper player cache is populated — on a cold Render
    # instance the extension could be the first caller.
    if _load_sleeper_cache() is None:
        try:
            _ensure_sleeper_cache_populated()
        except Exception as e:
            raise RuntimeError(
                f"Could not populate Sleeper player cache: {e}. "
                "Try again in a moment."
            )
    _ensure_universal_pools()

    # Persist user (no invited_by — extension isn't a referral surface)
    try:
        upsert_user(
            sleeper_user_id=user_id,
            username=username,
            display_name=display_name,
            avatar=avatar,
        )
    except Exception as e:
        log.warning("  extension auth: upsert_user failed: %s", e)

    # Build RankingServices per format with replayed swipes + tier overrides
    new_services: dict = {}
    for fmt in SCORING_FORMATS:
        fmt_pool, fmt_seed = _get_universal_pool(fmt)
        svc = RankingService(
            players           = fmt_pool,
            matchup_generator = matchup_gen,
            seed_ratings      = fmt_seed,
        )
        svc._user_id = user_id
        svc._scoring_format = fmt
        try:
            historical = load_swipe_decisions(user_id=user_id, scoring_format=fmt)
            if historical:
                svc.replay_from_db(historical)
        except Exception as e:
            log.warning("  [%s] extension replay failed: %s", fmt, e)
        try:
            # See server.py:4022 for why we no longer filter overrides
            # through the current pool — the filter destroys data.
            overrides = load_tier_overrides(user_id=user_id, scoring_format=fmt)
            svc._elo_overrides = {pid: float(elo) for pid, elo in overrides.items()}
        except Exception as e:
            log.warning("  [%s] extension override restore failed: %s", fmt, e)
        new_services[fmt] = svc

    payload = {
        "user_id":       user_id,
        "username":      username,
        "display_name":  display_name,
        # User-scoped: no 'league_id' or locked 'active_format' — resolved
        # per-request based on the ?league_id= query param on /rankings.
        "services":      new_services,
        # Default service alias (main-app code paths that read sess['service']
        # expect one). The rankings endpoint overrides this per-request.
        "service":       new_services[DEFAULT_SCORING],
        "active_format": DEFAULT_SCORING,
        "extension":     True,
        "last_active":   time.time(),
    }
    token = token or secrets.token_urlsafe(32)
    with _sessions_lock:
        _sessions[token] = payload
    return token, payload


@app.route("/api/extension/auth", methods=["POST"])
def extension_auth():
    """
    One-shot username auth for the browser extension.

    Body: {"username": "<sleeper_username>"}
    Returns: {session_token, expires_at, user_id, username, display_name,
              avatar, leagues: [...]}

    The returned `leagues` list is informational — the popup can display
    the user's league count, but the extension does NOT need to choose
    one up front. The content script detects league_id from
    sleeper.com/leagues/<id>/... URLs and passes it to /api/extension/rankings.
    """
    body     = request.get_json(force=True) or {}
    username = (body.get("username") or "").strip().lower()

    if not username:
        return jsonify({"error": "missing_username", "message": "Sleeper username required."}), 400

    # Resolve Sleeper username → user_id
    try:
        user_data = _sleeper_get(
            f"https://api.sleeper.app/v1/user/{urllib.parse.quote(username)}"
        )
    except Exception as e:
        return jsonify({"error": "sleeper_error", "message": str(e)}), 502
    if not isinstance(user_data, dict) or not user_data.get("user_id"):
        return jsonify({"error": "user_not_found",
                        "message": f"Sleeper user @{username} not found."}), 404

    user_id      = user_data["user_id"]
    display_name = user_data.get("display_name") or username
    avatar       = user_data.get("avatar")

    # Best-effort league list for popup display (non-blocking)
    leagues_compact: list = []
    try:
        leagues = _sleeper_get(
            f"https://api.sleeper.app/v1/user/{user_id}/leagues/nfl/2026"
        ) or []
        leagues_compact = [
            {
                "league_id":     str(lg.get("league_id")),
                "name":          lg.get("name") or "League",
                "total_rosters": lg.get("total_rosters"),
                "avatar":        lg.get("avatar"),
            }
            for lg in (leagues if isinstance(leagues, list) else [])
            if lg.get("league_id")
        ]
    except Exception as e:
        log.info("extension_auth: leagues fetch failed (non-fatal): %s", e)

    # Mint session immediately
    try:
        token, payload = _extension_build_session(
            user_id=user_id,
            username=username,
            display_name=display_name,
            avatar=avatar,
        )
    except Exception as e:
        log.exception("extension_auth: session build failed")
        return jsonify({"error": "session_build_failed", "message": str(e)}), 500

    # Tracking plan v2 §S1 — stitch pre-auth device events to this user.
    _link_device_identity(sleeper_user_id=user_id)

    expires_at = int(payload["last_active"]) + 4 * 3600
    return jsonify({
        "stage":         "connected",
        "session_token": token,
        "expires_at":    expires_at,
        "user_id":       user_id,
        "username":      username,
        "display_name":  display_name,
        "avatar":        avatar,
        "leagues":       leagues_compact,
    })


@app.route("/api/extension/rankings")
@_gate_unverified_read
def extension_rankings():
    """Return a compact tier + pos_rank map for the authenticated user.

    Query param: league_id (optional but recommended) — if provided, the
    backend looks up that league's scoring format (auto-detecting from
    Sleeper metadata on first sync) and returns rankings for that format.
    If omitted, falls back to the session's default format (1qb_ppr).

    Only players with a non-default ELO tier are included — unranked
    players don't get a badge.

    Shape:
      { format, league_id, league_name, username, updated_at,
        players: {pid: {name, pos, pos_rank, tier}} }
    """
    sess = _require_session()
    sess["last_active"] = time.time()
    req_league_id = (request.args.get("league_id") or "").strip() or None

    # Resolve scoring format:
    #   1. If league_id provided: look up leagues.default_scoring
    #   2. If not on file: fetch Sleeper meta and cache it
    #   3. Fall back to session default (1qb_ppr)
    fmt = None
    league_name = ""
    if req_league_id:
        try:
            fmt = get_league_scoring(req_league_id)
        except Exception:
            fmt = None
        if fmt not in SCORING_FORMATS:
            meta = _fetch_sleeper_league_meta(req_league_id)
            if meta:
                league_name = meta.get("name") or ""
                detected = _detect_scoring_format_from_meta(meta)
                try:
                    set_league_scoring(req_league_id, detected)
                except Exception:
                    pass
                fmt = detected
    if fmt not in SCORING_FORMATS:
        fmt = sess.get("active_format") or DEFAULT_SCORING

    service = sess["services"][fmt] if sess.get("services") else sess["service"]

    # Build per-position rankings
    players_map: dict[str, dict] = {}
    for pos in ("QB", "RB", "WR", "TE"):
        try:
            rankset = service.get_rankings(position=pos)
        except Exception as e:
            log.warning("extension_rankings: get_rankings(%s) failed: %s", pos, e)
            continue
        for i, rp in enumerate(rankset.rankings, start=1):
            elo = getattr(rp, "elo", None)
            tier = RankingService.tier_for_elo(elo, pos, fmt) if elo is not None else None
            if tier is None:
                continue
            pid = rp.player.id
            players_map[pid] = {
                "name":     rp.player.name,
                "pos":      pos,
                "pos_rank": i,
                "tier":     tier,
            }

    return jsonify({
        "format":       fmt,
        "league_id":    req_league_id or "",
        "league_name":  league_name,
        "username":     sess.get("username") or "",
        "updated_at":   int(time.time()),
        "players":      players_map,
    })


# ---------------------------------------------------------------------------
# Invite K-factor dashboard (Agent 5) — feature-flagged
# ---------------------------------------------------------------------------

# Milestone thresholds for the "Your invite impact" section of the invite
# modal. Kept here (not in a config file) because the frontend also needs
# to know the exact list to render a progress bar; single source of truth
# lives in the /api/invite/impact response.
_INVITE_MILESTONES: tuple[tuple[int, str], ...] = (
    (1,  "🌱 First Recruit"),
    (3,  "🤝 League Builder"),
    (5,  "🔥 Five-Spot"),
    (10, "👑 Ambassador"),
)


def _compute_invite_impact(username: str, user_id: str) -> dict:
    """Build the K-factor dashboard payload for the given user.

    Returns the shape consumed by GET /api/invite/impact — see that route's
    docstring for the contract.
    """
    # count_referrals accepts either a username or user_id; prefer username
    # because invited_by is stored by-username on the referred users' rows.
    key = username or user_id or ""
    total_joined = count_referrals(key)

    # Richer activity — "actively ranking" = has ≥1 swipe. We keep the
    # query cheap by only running it when the dashboard flag is on (i.e.
    # inside this helper, which only fires from the flagged route).
    activity = list_referral_activity(key) if key else []
    active_rankers = sum(1 for r in activity if r.get("has_swiped"))

    # v1 definition: invited == joined because every referred row exists
    # only after that user's session_init. We still return both fields so
    # the frontend copy can evolve without a backend change.
    invited = total_joined
    joined = total_joined

    # Next milestone = smallest threshold strictly greater than joined.
    # Once past the last threshold there is no "next" — return null so the
    # UI can hide the progress bar.
    next_milestone: dict | None = None
    for threshold, label in _INVITE_MILESTONES:
        if joined < threshold:
            next_milestone = {"badge": label, "at": threshold}
            break

    badges_earned = [label for threshold, label in _INVITE_MILESTONES
                     if joined >= threshold]

    return {
        "invited":        invited,
        "joined":         joined,
        "active_rankers": active_rankers,
        "k_factor":       float(joined),   # v1 fan-out per user
        "next_milestone": next_milestone,
        "badges_earned":  badges_earned,
        "milestones":     [{"at": t, "badge": b} for t, b in _INVITE_MILESTONES],
    }


@app.route("/api/invite/impact")
def invite_impact_route():
    """GET /api/invite/impact — returns the inviter's K-factor snapshot.

    Gated by the `invite.k_factor_dashboard` flag. When the flag is off we
    still respond 200 with a zeroed payload so the frontend can fail quiet
    without a console error, matching the other flagged endpoints.
    """
    sess = _require_session()
    sess["last_active"] = time.time()

    if not is_enabled("invite.k_factor_dashboard"):
        return jsonify({
            "enabled":        False,
            "invited":        0,
            "joined":         0,
            "active_rankers": 0,
            "k_factor":       0.0,
            "next_milestone": None,
            "badges_earned":  [],
            "milestones":     [{"at": t, "badge": b} for t, b in _INVITE_MILESTONES],
        })

    username = sess.get("username") or ""
    user_id  = sess.get("user_id")  or ""
    payload = _compute_invite_impact(username, user_id)
    payload["enabled"] = True
    return jsonify(payload)


# ---------------------------------------------------------------------------
# Feature flags — powers the sprint's on/off toggling via config/features.json
# ---------------------------------------------------------------------------

@app.route("/api/feature-flags")
def feature_flags_route():
    """Return the current effective feature-flag map + resolved experiments.

    Shape (analytics-platform FR-35 — strictly additive over the v0
    `{"flags": {...}}`; old parsers read `.flags` and ignore the rest):

        {"flags": {...}, "experiments": {key: variant}, "configs": {key: {...}}}

    The client sends `X-Device-Id` (+ optional `X-Session-Token`); the server
    resolves the assignment unit (account/session identity when known, else
    device_id) and returns the pinned variant snapshot. `experiments`/`configs`
    are ALWAYS objects (never absent) but stay EMPTY until the P3 evaluator
    (backend/experiments.py) lands — the contract ships in P1 so clients can
    read `useVariant()` against a stable shape from day one.

    Frontend fetches this at boot + on the ≥30-min foreground refetch
    (analytics-platform §4.6b) and stashes flags in window.FTF_FLAGS.
    """
    experiments: dict[str, str] = {}
    configs: dict[str, dict] = {}
    # P3: resolve per-unit experiment assignments here (guarded import — the
    # evaluator module doesn't exist yet; fail-open to empty, never 500).
    try:
        from . import experiments as _exp
        device_id = (request.headers.get("X-Device-Id") or "").strip() or None
        token = request.headers.get("X-Session-Token", "")
        account_unit = None
        if token:
            with _sessions_lock:
                sess = _sessions.get(token)
            if sess:
                account_unit = sess.get("user_id")
        device_unit = f"device:{device_id}" if device_id else None
        # Header-derived attrs let device-unit (onboarding) experiments
        # target platform/app_version/os — the only attrs available pre-auth.
        info = getattr(g, "device_info", {}) or {}
        header_attrs = {
            "platform": (str(request.headers.get("X-Source") or "").strip()
                         or ("ios" if (info.get("device_type") or "").lower()
                             in ("iphone", "ipad", "macos") else None)),
            "app_version": info.get("app_version"),
            "os_version": info.get("os_version"),
            "device_type": info.get("device_type"),
        }
        # Resolve BOTH identities and merge. A device-unit experiment (the
        # onboarding layer mandates them) must keep capturing the same device
        # after its session validates — with either/or resolution, sign-in
        # flipped the unit to account and the assignment evaporated mid-flow.
        # Each experiment has exactly one unit_type (the evaluator skips the
        # other identity), so the two maps are disjoint by construction.
        for uid in (device_unit, account_unit):
            if not uid:
                continue
            exp_map, cfg_map = _exp.resolve_for_unit(uid, header_attrs)
            experiments.update(exp_map)
            configs.update(cfg_map)
    except Exception:
        experiments, configs = {}, {}
    return jsonify({
        "flags":       flags_dict(),
        "experiments": experiments,
        "configs":     configs,
    })


@app.route("/api/feature-flags/reload", methods=["POST"])
def feature_flags_reload_route():
    """Force-reload flags from config/features.json + FTF_FLAGS env.

    Useful when flipping a flag in prod without a full server restart.
    Operator-only (X-Cron-Secret, same as /api/cron/*) — flag state gates
    user-facing behavior, so reloads shouldn't be world-triggerable.
    """
    _require_cron_auth()
    flags = reload_flags()
    return jsonify({"ok": True, "flags": flags})


# ---------------------------------------------------------------------------
# League URL parsing — powers the "Connect another league" dropdown action
# ---------------------------------------------------------------------------

@app.route("/api/league/parse-url", methods=["POST"])
def parse_league_url():
    """Parse a pasted league URL into {platform, league_id, name, supported}.

    Body: {"url": "<league-url>"}
    Response shape:
      {
        "platform":   "sleeper" | "espn" | "mfl",
        "league_id":  "<id>",
        "name":       "<League name, if resolvable>" (optional),
        "supported":  true  if we can complete the sync flow today,
                      false for ESPN / MFL where full sync is still on the
                            roadmap (the frontend shows a "coming soon" state)
      }
    Errors: {"error": "<code>", "message": "<human-readable>"}
    """
    body = request.get_json(force=True) or {}
    url = (body.get("url") or "").strip()
    if not url:
        return jsonify({"error": "missing_url",
                        "message": "Paste a league URL to continue."}), 400

    platform, league_id = _parse_league_url(url)
    if not platform or not league_id:
        return jsonify({
            "error":   "unrecognized_url",
            "message": "Couldn't recognize that URL. Paste a link from "
                       "Sleeper, ESPN Fantasy, or MyFantasyLeague.",
        }), 400

    # For Sleeper, we can resolve the league name immediately so the
    # confirmation UI shows "Lakeview League" rather than a bare ID.
    name = None
    if platform == "sleeper":
        try:
            meta = _fetch_sleeper_league_meta(league_id)
            if meta:
                name = meta.get("name")
        except Exception as e:
            log.info("parse_league_url: Sleeper meta lookup failed (non-fatal): %s", e)

    return jsonify({
        "platform":  platform,
        "league_id": league_id,
        "name":      name,
        "supported": platform == "sleeper",
    })


@app.route("/api/league/invite-meta")
def league_invite_meta():
    """Public, read-only league name for an invite banner (P0-3).

    PRIVACY CONSTRAINT — the name is resolved from Sleeper's PUBLIC API only,
    never from our `leagues` table. That is why ESPN/MFL/Fleaflicker leagues
    return null: their names live only in our DB, and this endpoint is
    unauthenticated, so serving them would make every imported league name
    enumerable by id. Sleeper league names are already public at
    https://api.sleeper.app/v1/league/<id>, so this endpoint discloses nothing
    that the id alone did not already disclose. (`_fetch_sleeper_league_meta`
    does read `leagues` — via is_linked_platform_league — but that read is how
    the constraint is ENFORCED; no value from that table reaches the response.)

    Degrades, never fails: any resolution problem is a 200 with
    league_name: null, and the client's banner falls back to "their league".
    The P0-3 acceptance criterion (inviter named) is met WITHOUT this route.

    NO RATE LIMIT, deliberately: a thin cache-friendly proxy of data Sleeper
    already serves publicly and unauthenticated, storing nothing and mutating
    nothing. The hourly limiter pattern needs a user id this route
    deliberately does not have. If abuse appears, the lever is
    `_fetch_sleeper_league_meta`'s upstream, not this route.
    """
    league_id = (request.args.get("league_id") or "").strip()
    if not league_id:
        return jsonify({"error": "missing_league_id"}), 400
    name = None
    try:
        meta = _fetch_sleeper_league_meta(league_id)
        if meta:
            name = meta.get("name") or None
    except Exception as e:                       # pragma: no cover - defensive
        log.info("invite-meta: lookup failed (non-fatal) league_id=%s: %s", league_id, e)
    return jsonify({
        "league_id":   league_id,
        "league_name": name,
        "platform":    "sleeper" if name else None,
    })


# ---------------------------------------------------------------------------
# Agent A7 — new surfaces
# ---------------------------------------------------------------------------
# Three features, each flag-gated. When the flag is off, routes return 404
# (profile) or the feature simply isn't wired on the frontend.
#   • profiles.public_pages   — /u/<username> + /api/profile/<username>
#   • landing.smart_start_cta — frontend only (flag-gated)
#   • landing.try_before_sync — /api/session/demo builds a seeded demo session
# ---------------------------------------------------------------------------

_PROFILE_POSITIONS = ("QB", "RB", "WR", "TE")


def _build_profile_tiers_snapshot(
    user_id: str,
    scoring_format: str,
    player_positions: dict,
    player_name_map: dict,
) -> dict:
    """Bucket a user's saved tier overrides into {position: {tier: [names]}}.

    Reads from load_tier_overrides (what the user saved via the tiers UI)
    and buckets each player by their stored ELO using the canonical
    RankingService.tier_for_elo.
    """
    from .ranking_service import RankingService as _RS
    try:
        overrides = load_tier_overrides(user_id=user_id, scoring_format=scoring_format)
    except Exception as e:
        log.warning("profile tiers load failed: %s", e)
        overrides = {}

    snapshot: dict = {}
    for pid, elo in overrides.items():
        pos = (player_positions.get(str(pid)) or "").upper()
        if pos not in _PROFILE_POSITIONS:
            continue
        try:
            elo_f = float(elo)
        except (TypeError, ValueError):
            continue
        tier = _RS.tier_for_elo(elo_f, pos, scoring_format)
        if not tier:
            continue
        name = player_name_map.get(str(pid), str(pid))
        snapshot.setdefault(pos.lower(), {}).setdefault(tier, []).append({
            "player_id": str(pid),
            "name":      name,
            "elo":       round(elo_f, 1),
        })

    for pos_buckets in snapshot.values():
        for entries in pos_buckets.values():
            entries.sort(key=lambda e: -e["elo"])

    return snapshot


def _build_profile_contrarian(
    user_id: str,
    scoring_format: str,
    player_positions: dict,
    player_name_map: dict,
    top_n: int = 3,
) -> dict:
    """Compute the user's top-N above/below community picks per position.

    Aggregates community ELO across every league the user belongs to and
    diffs against the user's own stored ELOs. A player needs at least 2
    non-user raters to count. Returns {pos: {above: [...], below: [...]}}.
    """
    # Get all league IDs this user is a member of
    league_ids: list = []
    try:
        from .database import league_members_table, engine as _engine  # type: ignore
        from sqlalchemy import select as _select
        with _engine.connect() as _conn:
            rows = _conn.execute(
                _select(league_members_table.c.league_id).where(
                    league_members_table.c.user_id == user_id
                )
            ).fetchall()
            league_ids = sorted({r.league_id for r in rows})
    except Exception as e:
        log.warning("profile league_ids load failed: %s", e)

    user_by_pid: dict = {}
    community_by_pid: dict = {}
    try:
        for lid in league_ids:
            everyone = load_member_rankings(
                league_id=lid,
                exclude_user_id="",
                scoring_format=scoring_format,
            )
            for uid, urow in everyone.items():
                for pid, elo in (urow.get("elo_ratings") or {}).items():
                    try:
                        fe = float(elo)
                    except (TypeError, ValueError):
                        continue
                    if uid == user_id:
                        user_by_pid[str(pid)] = fe
                    else:
                        community_by_pid.setdefault(str(pid), []).append(fe)
    except Exception as e:
        log.warning("profile rankings aggregation failed: %s", e)

    out: dict = {pos.lower(): {"above": [], "below": []} for pos in _PROFILE_POSITIONS}
    if not user_by_pid:
        return out

    for pos in _PROFILE_POSITIONS:
        deltas: list = []
        pos_u = pos.upper()
        for pid, u_elo in user_by_pid.items():
            if (player_positions.get(pid) or "").upper() != pos_u:
                continue
            c_list = community_by_pid.get(pid) or []
            if len(c_list) < 2:
                continue
            c_mean = sum(c_list) / len(c_list)
            delta = u_elo - c_mean
            deltas.append({
                "player_id":      pid,
                "name":           player_name_map.get(pid, pid),
                "user_elo":       round(u_elo, 1),
                "community_elo":  round(c_mean, 1),
                "delta":          round(delta, 1),
                "raters":         len(c_list),
            })
        above = sorted(deltas, key=lambda d: -d["delta"])[:top_n]
        below = sorted(deltas, key=lambda d: d["delta"])[:top_n]
        out[pos.lower()] = {"above": above, "below": below}
    return out


def _profile_opt_in_denied(user: dict | None) -> bool:
    """Per-user public-profile opt-in gate (teardown 06-04, flag
    profiles.user_toggle). When the flag is ON, a profile is only served
    if the user's `profile_public` marker is set — the global
    profiles.public_pages flag alone can no longer publish everyone.
    Flag off = legacy behavior (global flag governs)."""
    if not is_enabled("profiles.user_toggle"):
        return False
    return not (user or {}).get("profile_public")


@app.route("/u/<path:username>")
def public_profile_page(username):
    """Serve the public profile page when flag is on; 404 otherwise.
    With profiles.user_toggle on, also requires the user's opt-in."""
    if not is_enabled("profiles.public_pages"):
        return jsonify({"error": "not_found"}), 404
    if is_enabled("profiles.user_toggle"):
        try:
            user = get_user_by_username((username or "").strip().lower())
        except Exception as e:
            log.warning("profile page: user lookup failed: %s", e)
            user = None
        if _profile_opt_in_denied(user):
            return jsonify({"error": "not_found"}), 404
    return send_from_directory(app.static_folder, "profile.html")


@app.route("/api/profile/<path:username>")
def public_profile_data(username):
    """Public profile JSON. Read-only; only data the user has created.

    404 when flag off or user not found. No private league info exposed.
    """
    if not is_enabled("profiles.public_pages"):
        return jsonify({"error": "not_found"}), 404

    uname = (username or "").strip().lower()
    if not uname:
        return jsonify({"error": "missing_username"}), 400

    try:
        user = get_user_by_username(uname)
    except Exception as e:
        log.warning("profile: user lookup failed: %s", e)
        user = None
    if not user:
        return jsonify({"error": "not_found"}), 404

    user_id = user.get("sleeper_user_id") or user.get("user_id")
    if not user_id:
        return jsonify({"error": "not_found"}), 404

    # Per-user opt-in (teardown 06-04): indistinguishable from not-found so
    # usernames can't be enumerated through the privacy gate.
    if _profile_opt_in_denied(user):
        return jsonify({"error": "not_found"}), 404

    # Count distinct leagues
    leagues_count = 0
    try:
        from .database import league_members_table, engine as _engine  # type: ignore
        from sqlalchemy import select as _select, func as _func
        with _engine.connect() as _conn:
            row = _conn.execute(
                _select(_func.count(_func.distinct(league_members_table.c.league_id))).where(
                    league_members_table.c.user_id == user_id
                )
            ).fetchone()
            if row:
                leagues_count = int(row[0] or 0)
    except Exception as e:
        log.warning("profile leagues_count failed: %s", e)

    # Players lookup
    try:
        all_players = load_players(position=None)
    except Exception as e:
        log.warning("profile load_players failed: %s", e)
        all_players = []
    player_positions = {
        str(p.get("player_id")): (p.get("position") or "").upper()
        for p in all_players if p.get("player_id")
    }
    player_name_map = {
        str(p.get("player_id")): (p.get("full_name") or "—")
        for p in all_players if p.get("player_id")
    }

    # Pick the format with the larger tiers snapshot
    best_fmt = DEFAULT_SCORING
    best_tiers: dict = {}
    for fmt in SCORING_FORMATS:
        tiers_snap = _build_profile_tiers_snapshot(
            user_id, fmt, player_positions, player_name_map
        )
        cur = sum(len(v) for v in tiers_snap.values())
        best = sum(len(v) for v in best_tiers.values())
        if cur > best:
            best_tiers = tiers_snap
            best_fmt = fmt

    contrarian = _build_profile_contrarian(
        user_id, best_fmt, player_positions, player_name_map, top_n=3
    )

    avatar_url = None
    avatar = user.get("avatar")
    if avatar:
        avatar_url = f"https://sleepercdn.com/avatars/thumbs/{avatar}"

    return jsonify({
        "username":         user.get("username") or uname,
        "display_name":     user.get("display_name") or user.get("username") or uname,
        "avatar_url":       avatar_url,
        "leagues_count":    leagues_count,
        "scoring_format":   best_fmt,
        "contrarian_takes": contrarian,
        "tiers_snapshot":   best_tiers,
    })


@app.route("/api/profile/visibility", methods=["GET", "PUT"])
def profile_visibility():
    """Per-user public-profile opt-in (teardown 06-04, flag
    profiles.user_toggle; 404 while dark).

    GET → {"public": bool} — the session user's stored opt-in (default
    False). PUT {"public": bool} → persist. The PUT applies the standard
    verified-write gate: once a verified controller exists for this
    user_id, a squatter session cannot publish (or hide) their board.
    """
    if not is_enabled("profiles.user_toggle"):
        return jsonify({"error": "not_found"}), 404
    sess = _require_session()
    sess["last_active"] = time.time()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    if request.method == "PUT":
        denial = _verified_write_denial(sess)
        if denial is not None:
            return denial
        body = request.get_json(force=True, silent=True) or {}
        if "public" not in body:
            return jsonify({"error": "bad_request",
                            "message": "Body must include \"public\"."}), 400
        public = bool(body.get("public"))
        try:
            set_profile_public(user_id, public)
        except Exception as e:
            log.error("profile visibility save failed for %s: %s", user_id, e)
            return jsonify({"error": "internal_error"}), 500
        log.info("profile visibility: user %s → %s",
                 user_id, "public" if public else "private")
        return jsonify({"public": public})

    try:
        return jsonify({"public": get_profile_public(user_id)})
    except Exception as e:
        log.error("profile visibility read failed for %s: %s", user_id, e)
        return jsonify({"error": "internal_error"}), 500


@app.route("/api/session/demo", methods=["POST", "GET"])
def session_demo():
    """Bootstrap a seeded demo session — no Sleeper auth, nothing persists."""
    if not is_enabled("landing.try_before_sync"):
        return jsonify({"error": "not_found"}), 404

    try:
        demo_user_id = "demo_user_" + secrets.token_hex(4)

        from .database import SCORING_FORMATS as DB_SCORING_FORMATS
        new_services: dict = {}
        new_trade_svcs: dict = {}
        final_league = None
        for fmt in DB_SCORING_FORMATS:
            svc = RankingService(
                players=list(DEMO_PLAYERS),
                matchup_generator=matchup_gen,
                seed_ratings=seed,
            )
            svc._user_id = demo_user_id
            svc._scoring_format = fmt
            new_services[fmt] = svc

            tsvc = TradeService(players={p.id: p for p in DEMO_PLAYERS})
            dl, _dr = _build_demo_league(DEMO_PLAYERS, seed)
            tsvc.add_league(dl)
            new_trade_svcs[fmt] = tsvc
            final_league = dl

        active_format = DEFAULT_SCORING
        token = secrets.token_urlsafe(32)
        payload = {
            "user_id":       demo_user_id,
            "league":        final_league,
            "players":       list(DEMO_PLAYERS),
            "user_roster":   list(DEMO_USER_ROSTER),
            "services":      new_services,
            "service":       new_services[active_format],
            "trade_svcs":    new_trade_svcs,
            "trade_svc":     new_trade_svcs[active_format],
            "active_format": active_format,
            "display_name":  "Demo User",
            "last_active":   time.time(),
            "is_demo":       True,
        }
        with _sessions_lock:
            _sessions[token] = payload

        # Tracking plan v2 §S1 — demo sessions count as a sign-in outcome
        # for device stitching (funnel: demo_entered → real sign-in later).
        _link_device_identity(sleeper_user_id=demo_user_id)

        players_dict = {p.id: p for p in DEMO_PLAYERS}
        return jsonify({
            "ok":           True,
            "demo":         True,
            "token":        token,
            "user_id":      demo_user_id,
            "display_name": "Demo User",
            "league_id":    final_league.league_id,
            "league_name":  final_league.name,
            "player_count": len(DEMO_PLAYERS),
            "user_roster":  [player_to_dict(players_dict[pid]) for pid in DEMO_USER_ROSTER if pid in players_dict],
            "opponents":    len(final_league.members),
        })
    except Exception as e:
        log.error("session/demo failed: %s\n%s", e, traceback.format_exc())
        return jsonify({"error": "internal_error"}), 500


# ─── Test users (QA) — synthetic stage-user spawner ────────────────────────
# Onboarding QA (docs/plans/onboarding-conversion/plan.md): the operator
# spawns qa_* users at a preset adoption stage without touching real Sleeper
# users. Gated on the `testing.stage_users` flag AND the tester allowlist —
# deliberately NOT the cron secret (the operator's phone calls this), the
# allowlist keeps it operator-only even with the flag on. Sessions ride the
# demo-league build path but are NOT marked is_demo: the client must treat
# them as normal signed-in sessions. Logic lives in backend/test_users.py.

from . import test_users as _test_users
from .experiments import load_tester_allowlist as _load_tester_allowlist


def _test_users_denied():
    """Gate for /api/test-users — returns an error response, or None to
    proceed. ALLOWLIST-ONLY, fail closed: any caller whose device
    ('device:<X-Device-Id>') or session user_id is off the tester allowlist
    gets a 404 (the surface stays invisible — no existence signal). The
    `testing.stage_users` flag is deliberately NOT consulted here: it gates
    only the client Settings row, and ships per-device via the experiment
    overlay so the global flag can stay dark (operator direction
    2026-07-19; allowlist doc: docs/config-reference.md)."""
    allow = _load_tester_allowlist()
    device_id = (request.headers.get("X-Device-Id") or "").strip()
    if device_id and f"device:{device_id}" in allow:
        return None
    with _sessions_lock:
        sess = _sessions.get(request.headers.get("X-Session-Token", ""))
    if sess is not None and sess.get("user_id") in allow:
        return None
    return jsonify({"error": "not_found"}), 404


@app.route("/api/test-users", methods=["POST"])
def spawn_test_user():
    """POST /api/test-users {"stage": "fresh"|"activated"|"board_owner"|
    "converted"|"power"} — mint a synthetic qa_* user pre-seeded to that
    adoption stage, with a live demo-league session. Returns the session
    token + the ftf_onboarding_state the client should adopt."""
    denied = _test_users_denied()
    if denied is not None:
        return denied
    body = request.get_json(force=True, silent=True) or {}
    stage = body.get("stage")
    if stage not in _test_users.STAGES:
        return jsonify({"error": f"Invalid stage: {stage!r}",
                        "stages": list(_test_users.STAGES)}), 400
    try:
        user_id = "qa_" + uuid.uuid4().hex[:8]
        username = f"qa_{stage}_{secrets.token_hex(2)}"
        upsert_user(sleeper_user_id=user_id, username=username,
                    display_name=username)

        # Demo-league session build — same path as /api/session/demo, keyed
        # to the synthetic user. Unlike demo: the users row persists, boards
        # replay, and there is no is_demo key on the session.
        from .database import SCORING_FORMATS as DB_SCORING_FORMATS
        new_services: dict = {}
        new_trade_svcs: dict = {}
        final_league = None
        for fmt in DB_SCORING_FORMATS:
            svc = RankingService(
                players=list(DEMO_PLAYERS),
                matchup_generator=matchup_gen,
                seed_ratings=seed,
            )
            svc._user_id = user_id
            svc._scoring_format = fmt
            new_services[fmt] = svc

            tsvc = TradeService(players={p.id: p for p in DEMO_PLAYERS})
            dl, _dr = _build_demo_league(DEMO_PLAYERS, seed)
            tsvc.add_league(dl)
            new_trade_svcs[fmt] = tsvc
            final_league = dl

        # Stage seeding — boards go onto the live default-format service AND
        # into users.tier_overrides/tiers_saved (the /api/tiers/save storage).
        notes = _test_users.seed_stage(
            user_id, stage,
            service=new_services[DEFAULT_SCORING],
            players=list(DEMO_PLAYERS),
            seed_ratings=seed,
            scoring_format=DEFAULT_SCORING,
        )

        token = secrets.token_urlsafe(32)
        payload = {   # mirrors session_init's payload shape — NO is_demo key
            "user_id":       user_id,
            "league":        final_league,
            "players":       list(DEMO_PLAYERS),
            "user_roster":   list(DEMO_USER_ROSTER),
            "services":      new_services,
            "service":       new_services[DEFAULT_SCORING],
            "trade_svcs":    new_trade_svcs,
            "trade_svc":     new_trade_svcs[DEFAULT_SCORING],
            "active_format": DEFAULT_SCORING,
            "display_name":  username,
            "last_active":   time.time(),
        }
        if stage in _test_users.VERIFIED_STAGES:
            # users.verified_via is stamped, so an UNVERIFIED session would
            # trip the P2.5 read gate (verified-controller branch). Mark the
            # session verified — mirrors a real post-Apple-bind session.
            payload["verified"] = True
            payload["verified_via"] = "apple"
        with _sessions_lock:
            _sessions[token] = payload

        log.info("test-users: spawned %s (%s) stage=%s", user_id, username, stage)
        return jsonify({
            "session_token": token,
            "user_id":       user_id,
            "username":      username,
            "display_name":  username,
            "league_id":     final_league.league_id,
            "league_name":   final_league.name,
            "stage":         stage,
            "client_state":  _test_users.client_state_for(stage),
            "notes":         notes,
        })
    except Exception as e:
        log.error("test-users spawn failed: %s\n%s", e, traceback.format_exc())
        return jsonify({"error": "internal_error"}), 500


@app.route("/api/test-users/<user_id>", methods=["DELETE"])
def delete_test_user_route(user_id: str):
    """DELETE /api/test-users/<user_id> — remove a qa_* user's rows (users,
    swipe_decisions, member_rankings) and evict any live session. Refuses
    anything without the qa_ prefix."""
    denied = _test_users_denied()
    if denied is not None:
        return denied
    if not user_id.startswith("qa_"):
        return jsonify({"error": "not_a_test_user",
                        "message": "Only qa_* users can be deleted here."}), 400
    try:
        with _sessions_lock:
            stale = [t for t, s in _sessions.items()
                     if s.get("user_id") == user_id]
            for t in stale:
                _sessions.pop(t, None)
        try:
            delete_persisted_sessions_for_user(user_id)
        except Exception:
            pass
        counts = _test_users.delete_test_user(user_id)
        counts["sessions_evicted"] = len(stale)
        log.info("test-users: deleted %s — %s", user_id, counts)
        return jsonify({"ok": True, "user_id": user_id, "deleted": counts})
    except Exception as e:
        log.error("test-users delete failed: %s\n%s", e, traceback.format_exc())
        return jsonify({"error": "internal_error"}), 500


# ─── Account auth — Apple/Google identity anchors + in-app deletion ────────
# Account-auth plan P2 (docs/plans/account-auth-plan-2026-07-11.md §3-P2).
# Thin wrappers over backend/accounts.py. The sign-in surface is gated on
# the `auth.accounts` flag (ships dark); DELETE /api/account is deliberately
# ungated — App Store Guideline 5.1.1(v) requires in-app account deletion.

from . import accounts as _accounts


def _account_session() -> dict | None:
    """Best-effort session lookup for the auth routes — no 401 on miss.

    Demo sessions don't persist anything, so they never bind to an account.
    """
    token = request.headers.get("X-Session-Token", "")
    sess = _get_session(token)
    if sess is None:
        return None
    if sess.get("is_demo") or str(sess.get("user_id", "")).startswith("demo_user_"):
        return None
    return sess


# Sentinel league for account-only sessions (P2.6): a REAL empty league —
# never session_init's simulated-opponent fallback — so league-scoped
# features return empty states instead of 409s or fake demo opponents.
ACCOUNT_NO_LEAGUE_ID = "no_league"
ACCOUNT_NO_LEAGUE_NAME = "No league linked"


def _account_build_session(user_id: str, display_name: str,
                           token: str | None = None) -> tuple[str, dict]:
    """Build a full session for an account-only user (P2.6).
    `token` re-uses an existing bearer token (persistent-session restore).

    Contract: upserts the users row for `user_id` and returns
    (token, session_payload) with per-format Ranking + Trade services and an
    EMPTY league, so `_require_initialized_session` routes (rank3,
    tiers/save, anchor/save, reorder) work; trade generation yields zero
    cards (no members) and match routes return empty — the honest
    "link a league" state.
    """
    token, payload = _extension_build_session(
        user_id=user_id,
        username="",
        display_name=display_name,
        avatar=None,
        token=token,
    )
    empty_league = League(
        league_id=ACCOUNT_NO_LEAGUE_ID,
        name=ACCOUNT_NO_LEAGUE_NAME,
        platform="none",
        members=[],
    )
    default_pool, _ = _get_universal_pool(DEFAULT_SCORING)
    trade_svcs: dict = {}
    for fmt in SCORING_FORMATS:
        fmt_pool, _ = _get_universal_pool(fmt)
        tsvc = TradeService(players={p.id: p for p in fmt_pool},
                            past_decision_keys=set())
        tsvc.add_league(empty_league)
        trade_svcs[fmt] = tsvc
    payload.update({
        "league":       empty_league,
        "players":      list(default_pool),
        "user_roster":  [],
        "trade_svcs":   trade_svcs,
        "trade_svc":    trade_svcs[DEFAULT_SCORING],
        "account_only": True,
    })
    payload.pop("extension", None)
    return token, payload


def _provider_auth_response(provider: str, claims: dict):
    """Shared find-or-create + bind + verify flow for /api/auth/<provider>.

    Binding rules (see accounts.bind_sleeper_user — binding is sticky):
      * session present, account unbound      → bind to session's user_id
        (never an acct_* working key — synthetic keys are not Sleeper
        sources; those sessions get account-only re-auth instead)
      * session present, same binding         → no-op
      * session present, DIFFERENT binding    → keep existing binding, flag
        `conflict` (identity anchor wins; no silent rebinding)
      * no session, account bound             → device-loss restore: mint a
        session for the bound user
      * no session, account unbound           → ACCOUNT-FIRST (P2.6): mint an
        account-keyed session (working key acct_<account_id>); the user can
        rank immediately and link a Sleeper username later from Settings
    """
    sub = claims.get("sub")
    if not sub:
        return jsonify({"error": "invalid_token", "reason": "missing_sub"}), 401
    acct = _accounts.find_or_create_account(
        provider, sub, _accounts.hash_email(claims.get("email")),
        email=claims.get("email"),   # stored only when auth.email_capture is on
    )
    sess = _account_session()

    out: dict = {
        "ok": True,
        "provider": provider,
        "account_id": acct["account_id"],
        "linked": False,
        "sleeper_user_id": None,
        "conflict": False,
    }

    def _mint_account_only_session():
        """No linked Sleeper source: session under the synthetic acct_ key."""
        acct_uid = _accounts.account_user_id(acct["account_id"])
        # Apple sends the user's name only to the CLIENT (and only on first
        # authorization) — the client forwards it as display_name.
        body = request.get_json(force=True, silent=True) or {}
        display = (body.get("display_name") or "").strip() or "Manager"
        try:
            token, payload = _account_build_session(acct_uid, display)
        except Exception as e:
            log.exception("auth/%s: account session build failed", provider)
            return jsonify({"error": "session_build_failed",
                            "message": str(e)}), 500
        payload["verified"] = True
        payload["verified_via"] = provider
        payload["account_id"] = acct["account_id"]
        try:
            # The provider proof IS the identity proof for an account-keyed
            # user (no Sleeper account exists to squat); persisting the
            # marker also arms the P1/P2.5 gates against anyone else
            # naming this key via /api/session/init.
            _accounts.mark_user_verified(acct_uid, provider)
        except Exception as e:
            log.warning("auth/%s: mark_user_verified failed: %s", provider, e)
        _persist_session_if_eligible(token, payload)
        out.update({
            "account_only": True,
            "user_id": acct_uid,
            "display_name": payload.get("display_name"),
            "session_token": token,
            "verified_via": provider,
            "league_id": ACCOUNT_NO_LEAGUE_ID,
            "league_name": ACCOUNT_NO_LEAGUE_NAME,
        })
        _link_device_identity(sleeper_user_id=acct_uid,
                              account_id=acct["account_id"])
        return jsonify(out)

    bound_uid = acct["sleeper_user_id"]
    if sess is not None and _accounts.is_account_user_id(sess.get("user_id")):
        # An account-keyed session re-authing with a provider: never bind the
        # synthetic key into accounts.sleeper_user_id. Refresh the session's
        # verified state instead (same-account case); a different account's
        # token just returns that account's state untouched.
        if sess.get("user_id") == _accounts.account_user_id(acct["account_id"]):
            sess["verified"] = True
            sess["verified_via"] = provider
            sess["account_id"] = acct["account_id"]
            sess["_persisted_at"] = 0  # re-auth refreshes the durable row now
            _persist_session_if_eligible(
                request.headers.get("X-Session-Token", ""), sess)
            out.update({
                "account_only": True,
                "user_id": sess["user_id"],
                "verified_via": provider,
                "league_id": ACCOUNT_NO_LEAGUE_ID,
                "league_name": ACCOUNT_NO_LEAGUE_NAME,
            })
        return jsonify(out)
    if sess is not None:
        bind = _accounts.bind_sleeper_user(acct["account_id"], sess["user_id"])
        out["linked"] = True
        out["sleeper_user_id"] = bind["sleeper_user_id"]
        out["conflict"] = bind["conflict"]
        if not bind["conflict"]:
            # Session's user is now anchored to this provider identity.
            sess["verified"] = True
            sess["verified_via"] = provider
            sess["account_id"] = acct["account_id"]
            out["verified_via"] = provider
            try:
                _accounts.mark_user_verified(sess["user_id"], provider)
            except Exception as e:
                log.warning("auth/%s: mark_user_verified failed: %s", provider, e)
            sess["_persisted_at"] = 0  # anchor moment — persist immediately
            _persist_session_if_eligible(
                request.headers.get("X-Session-Token", ""), sess)
            _link_device_identity(sleeper_user_id=bind["sleeper_user_id"],
                                  account_id=acct["account_id"])
    elif bound_uid:
        # Device-loss restore: no session, but this identity already anchors
        # a Sleeper-keyed user. Mint a user-scoped session (same shape the
        # extension auth builds) and mark it verified.
        profile = _accounts.get_user_profile(bound_uid) or {}
        try:
            token, payload = _extension_build_session(
                user_id=bound_uid,
                username=profile.get("username") or "",
                display_name=profile.get("display_name") or profile.get("username") or "",
                avatar=profile.get("avatar"),
            )
        except Exception as e:
            log.exception("auth/%s: restore session build failed", provider)
            return jsonify({"error": "session_build_failed", "message": str(e)}), 500
        payload["verified"] = True
        payload["verified_via"] = provider
        payload["account_id"] = acct["account_id"]
        try:
            _accounts.mark_user_verified(bound_uid, provider)
        except Exception as e:
            log.warning("auth/%s: mark_user_verified failed: %s", provider, e)
        _persist_session_if_eligible(token, payload)
        out.update({
            "linked": True,
            "sleeper_user_id": bound_uid,
            "username": profile.get("username"),
            "display_name": profile.get("display_name"),
            "avatar": profile.get("avatar"),
            "session_token": token,
            "verified_via": provider,
        })
        _link_device_identity(sleeper_user_id=bound_uid,
                              account_id=acct["account_id"])
    else:
        # ACCOUNT-FIRST (P2.6): brand-new identity, no session, no bound
        # Sleeper source — the account itself is the primary identity.
        return _mint_account_only_session()

    return jsonify(out)


_TEST_APPLE_TOKEN_PREFIX = "ftf-test-apple:"


def _test_mode_identity(identity_token: str) -> dict | None:
    """Harness only (HLD §5.3). `FTF_TEST_MODE=1` + 'ftf-test-apple:<sub>'
    → {'sub': sub}. Returns None in every deployed configuration.

    THE GATE IS THE MODULE CONSTANT, not os.environ: `_TEST_MODE` is evaluated
    once at import (:486), which is also why the pytest that exercises the
    seam monkeypatches `server._TEST_MODE` rather than the env var. Reading
    the constant here is what makes those two agree.

    This substitutes for `verify_apple_token` and NOTHING ELSE. Everything
    downstream — `_provider_auth_response`, `_mint_account_only_session`, the
    sentinel league, `verified_via='apple'` — is the real production path, so
    the Maestro flow that rides this seam is testing production code rather
    than the harness. `FTF_TEST_MODE` is never set in Render, and the
    401-when-unset behaviour is ASSERTED by
    backend/tests/test_account_only_harness.py, not assumed.
    """
    if not _TEST_MODE:
        return None
    if not identity_token.startswith(_TEST_APPLE_TOKEN_PREFIX):
        return None
    sub = identity_token[len(_TEST_APPLE_TOKEN_PREFIX):].strip()
    return {"sub": sub} if sub else None


@app.route("/api/auth/apple", methods=["POST"])
def auth_apple():
    """Sign in with Apple — verify the identity token, find-or-create the
    account, bind/restore per the rules on _provider_auth_response."""
    if not is_enabled("auth.accounts"):
        return jsonify({"error": "not_found"}), 404
    body = request.get_json(force=True, silent=True) or {}
    token = (body.get("identity_token") or "").strip()
    if not token:
        return jsonify({"error": "missing_token",
                        "message": "identity_token required."}), 400
    claims = _test_mode_identity(token)
    if claims is None:
        try:
            claims = _accounts.verify_apple_token(token)
        except _accounts.TokenVerificationError as e:
            log.info("auth/apple: token rejected (%s)", e.reason)
            return jsonify({"error": "invalid_token", "reason": e.reason}), 401
    return _provider_auth_response("apple", claims)


@app.route("/api/auth/google", methods=["POST"])
def auth_google():
    """Google ID-token sign-in — same code path as Apple, different issuer.

    Requires GOOGLE_OAUTH_CLIENT_ID in the environment (the token `aud`);
    returns 503 not_configured until the operator sets it. The mobile
    surface for Google is stubbed for now — Apple is the App-Store-mandatory
    anchor (Guideline 4.8)."""
    if not is_enabled("auth.accounts"):
        return jsonify({"error": "not_found"}), 404
    client_id = os.environ.get("GOOGLE_OAUTH_CLIENT_ID", "").strip()
    if not client_id:
        return jsonify({"error": "not_configured",
                        "message": "Google sign-in is not configured."}), 503
    body = request.get_json(force=True, silent=True) or {}
    token = (body.get("id_token") or body.get("identity_token") or "").strip()
    if not token:
        return jsonify({"error": "missing_token",
                        "message": "id_token required."}), 400
    try:
        claims = _accounts.verify_google_token(token, client_id)
    except _accounts.TokenVerificationError as e:
        log.info("auth/google: token rejected (%s)", e.reason)
        return jsonify({"error": "invalid_token", "reason": e.reason}), 401
    return _provider_auth_response("google", claims)


@app.route("/api/account")
def get_account_route():
    """Current account: linked identities + bound Sleeper id + verified state."""
    if not is_enabled("auth.accounts"):
        return jsonify({"error": "not_found"}), 404
    sess = _require_session()
    user_id = sess["user_id"]
    acct = None
    if sess.get("account_id"):
        acct = _accounts.get_account(sess["account_id"])
    if acct is None:
        acct = _accounts.get_account_for_user(user_id)
    verified_via = sess.get("verified_via")
    if verified_via is None:
        try:
            verified_via = _accounts.get_user_verified_via(user_id)
        except Exception:
            verified_via = None
    # P2.6 additive: is this an account-keyed (no linked Sleeper) session,
    # and — when a Sleeper source IS bound — its username for the Settings
    # "linked sources" list. ESPN leagues will join this list later.
    account_only = _accounts.is_account_user_id(user_id)
    sleeper_username = None
    if acct and acct.get("sleeper_user_id"):
        profile = _accounts.get_user_profile(acct["sleeper_user_id"]) or {}
        sleeper_username = profile.get("username") or None
    return jsonify({
        "ok": True,
        "sleeper_user_id": user_id,
        "verified_via": verified_via,
        "account": acct,   # null when no identity is linked yet
        "account_only": account_only,
        "sleeper_username": sleeper_username,
    })


@app.route("/api/account/link-sleeper", methods=["POST"])
def link_sleeper_source():
    """Link a Sleeper username as a source on the session's account (P2.6).

    Body: {username, strategy?}. Requires an account-backed session (only
    provider auth sets sess["account_id"], so a plain username squatter can
    never reach the merge). Rules — full reasoning in the plan doc §P2.6:

      * sticky binding: account bound to a DIFFERENT Sleeper id
        → 409 sleeper_conflict (nothing touched)
      * first-verified-wins: the target Sleeper id already has a verified
        controller → 403 sleeper_already_claimed (no takeover)
      * both boards have data and no `strategy`
        → 409 merge_choice_required + both summaries
      * strategy='keep_sleeper' → account board wiped (explicit choice)
      * strategy='keep_account' → Sleeper board wiped, account board moved
      * account board only → migrated; Sleeper board only / neither → adopt

    On success: account bound, Sleeper user marked verified via the
    account's provider, every acct_* session evicted, and a fresh session
    for the Sleeper user returned (client re-runs the league picker).
    """
    if not is_enabled("auth.accounts"):
        return jsonify({"error": "not_found"}), 404
    sess = _require_session()
    account_id = sess.get("account_id")
    if not account_id:
        return jsonify({"error": "no_account",
                        "message": "Sign in with Apple or Google first."}), 400

    body = request.get_json(force=True, silent=True) or {}
    username = (body.get("username") or "").strip().lower()
    strategy = (body.get("strategy") or "").strip() or None
    if not username:
        return jsonify({"error": "missing_username",
                        "message": "Sleeper username required."}), 400
    if strategy not in (None, "keep_sleeper", "keep_account"):
        return jsonify({"error": "bad_strategy"}), 400

    try:
        user_data = _sleeper_get(
            f"https://api.sleeper.app/v1/user/{urllib.parse.quote(username)}"
        )
    except Exception as e:
        return jsonify({"error": "sleeper_error", "message": str(e)}), 502
    if not isinstance(user_data, dict) or not user_data.get("user_id"):
        return jsonify({"error": "user_not_found",
                        "message": f"Sleeper user @{username} not found."}), 404
    sleeper_uid = str(user_data["user_id"])
    display_name = user_data.get("display_name") or username
    avatar = user_data.get("avatar")

    acct = _accounts.get_account(account_id)
    if acct is None:
        return jsonify({"error": "no_account"}), 400
    bound = acct.get("sleeper_user_id")
    if bound and bound != sleeper_uid:
        return jsonify({"error": "sleeper_conflict",
                        "message": "This account is already linked to a "
                                   "different Sleeper username."}), 409
    already_bound = bound == sleeper_uid

    # First-verified-wins: an account cannot take over a Sleeper id whose
    # control someone already proved (Sleeper-JWT owner or another account).
    if not already_bound:
        controller_via = _verified_controller_via(sleeper_uid)
        if controller_via:
            log.warning("link-sleeper: DENY account=%s target=%s "
                        "reason=verified_controller via=%s",
                        account_id, sleeper_uid, controller_via)
            return jsonify({
                "error": "sleeper_already_claimed",
                "message": "That Sleeper account is already verified by "
                           "another sign-in.",
            }), 403

    acct_uid = sess["user_id"]
    provider = sess.get("verified_via") or next(
        (i["provider"] for i in (acct.get("identities") or [])), "apple")

    merged = None
    if _accounts.is_account_user_id(acct_uid) and not already_bound:
        from .database import reset_user_rankings
        acct_board = _accounts.board_data_summary(acct_uid)
        sleeper_board = _accounts.board_data_summary(sleeper_uid)
        if acct_board["any"] and sleeper_board["any"] and strategy is None:
            # Explicit user choice — never silently prefer a side.
            return jsonify({
                "error": "merge_choice_required",
                "account_board": acct_board,
                "sleeper_board": sleeper_board,
            }), 409
        if acct_board["any"] and sleeper_board["any"]:
            if strategy == "keep_sleeper":
                reset_user_rankings(acct_uid)
                merged = "kept_sleeper"
            else:  # keep_account
                reset_user_rankings(sleeper_uid)
                _accounts.migrate_board_data(acct_uid, sleeper_uid)
                merged = "kept_account"
        elif acct_board["any"]:
            _accounts.migrate_board_data(acct_uid, sleeper_uid)
            merged = "migrated"
        else:
            merged = "adopted_sleeper"

    bind = _accounts.bind_sleeper_user(account_id, sleeper_uid)
    if bind["conflict"]:  # raced binding — nothing more to do safely
        return jsonify({"error": "sleeper_conflict"}), 409

    try:
        token, payload = _extension_build_session(
            user_id=sleeper_uid,
            username=username,
            display_name=display_name,
            avatar=avatar,
        )
    except Exception as e:
        log.exception("link-sleeper: session build failed")
        return jsonify({"error": "session_build_failed", "message": str(e)}), 500
    payload["verified"] = True
    payload["verified_via"] = provider
    payload["account_id"] = account_id
    try:
        _accounts.mark_user_verified(sleeper_uid, provider)
    except Exception as e:
        log.warning("link-sleeper: mark_user_verified failed: %s", e)
    _persist_session_if_eligible(token, payload)

    # Evict the account-keyed sessions — their working key just migrated.
    # Durable rows too (unconditional: rows may exist from a flag-on period).
    if _accounts.is_account_user_id(acct_uid):
        with _sessions_lock:
            for t in [t for t, s in _sessions.items()
                      if s.get("user_id") == acct_uid]:
                _sessions.pop(t, None)
        try:
            delete_persisted_sessions_for_user(acct_uid)
        except Exception as e:
            log.warning("link-sleeper: durable session cleanup failed: %s", e)

    log.info("link-sleeper: account=%s bound sleeper=%s merge=%s",
             account_id, sleeper_uid, merged)
    return jsonify({
        "ok": True,
        "sleeper_user_id": sleeper_uid,
        "username": username,
        "display_name": display_name,
        "avatar": avatar,
        "session_token": token,
        "verified_via": provider,
        "merge": merged,
    })


def _account_data_gates(sess) -> tuple | None:
    """Shared auth gates for account deletion + export (teardown 06-02):
    demo sessions have no stored data (400); a verified user's data can
    only be touched by a verified session (403). Returns a (response,
    status) tuple to short-circuit with, or None to proceed.
    """
    user_id = sess.get("user_id")
    if sess.get("is_demo") or str(user_id or "").startswith("demo_user_"):
        return jsonify({"error": "demo_session",
                        "message": "Demo sessions have no stored data."}), 400
    try:
        verified_via = _accounts.get_user_verified_via(user_id)
    except Exception:
        verified_via = None
    if verified_via and not sess.get("verified"):
        return jsonify({
            "error": "verification_required",
            "message": "This account is verified — verify this session "
                       "first.",
        }), 403
    return None


@app.route("/api/account/export")
def export_account_route():
    """GET /api/account/export — JSON archive of every user-keyed row
    (teardown 06-02, flag `account.data_export`; 404 while dark).

    Scope = the deletion matrix in accounts.delete_user_data (same table
    list, so "Download my data" and "Delete account" describe the same data
    set; sleeper_credentials ciphertext excluded). Same auth gates as
    deletion: demo-blocked, verified-user step-up.
    """
    if not is_enabled("account.data_export"):
        return jsonify({"error": "not_found"}), 404
    sess = _require_session()
    sess["last_active"] = time.time()
    user_id = sess.get("user_id")
    gated = _account_data_gates(sess)
    if gated is not None:
        return gated
    try:
        archive = _accounts.export_user_data(
            user_id, account_id=sess.get("account_id"))
    except Exception as e:
        log.exception("account/export failed for %s", user_id)
        return jsonify({"error": "export_failed", "message": str(e)}), 500
    log.info("account/export: user %s exported (%d tables)",
             user_id, len(archive.get("tables", {})))
    resp = jsonify(archive)
    # Hint clients (and browsers) that this is a download artifact.
    resp.headers["Content-Disposition"] = (
        "attachment; filename=fantasy-trade-finder-export.json")
    return resp


@app.route("/api/account", methods=["DELETE"])
def delete_account_route():
    """In-app account deletion (App Store 5.1.1(v)) — NOT flag-gated.

    Deletes/anonymizes per the matrix documented in accounts.delete_user_data
    (honors web/privacy.html §6). When the user record has been verified
    (users.verified_via set), the calling session must itself be verified —
    a username-only squatter session cannot delete a verified user's data.
    Also evicts every live session for the user (server-side sign-out).

    SIWA revocation (5.1.1(v) companion, teardown 06-02): when a linked
    Apple identity exists, best-effort revoke via Apple's /auth/revoke —
    needs the APPLE_* signing env keys plus a fresh
    `apple_authorization_code` in the (optional) request body; any failure
    is logged and local deletion proceeds regardless.
    """
    sess = _require_session()
    user_id = sess.get("user_id")
    gated = _account_data_gates(sess)
    if gated is not None:
        return gated
    apple_revoked = False
    try:
        if _accounts.has_apple_identity(user_id,
                                        account_id=sess.get("account_id")):
            body = request.get_json(silent=True) or {}
            apple_revoked = _accounts.revoke_apple_tokens(
                body.get("apple_authorization_code"))
            log.info("delete_account: apple revocation %s for %s",
                     "succeeded" if apple_revoked else "not completed", user_id)
    except Exception as revoke_err:
        log.warning("delete_account: apple revocation errored (continuing): %s",
                    revoke_err)
    try:
        counts = _accounts.delete_user_data(user_id,
                                            account_id=sess.get("account_id"))
    except Exception as e:
        log.exception("delete_account: deletion failed for %s", user_id)
        return jsonify({"error": "deletion_failed", "message": str(e)}), 500
    with _sessions_lock:
        for t in [t for t, s in _sessions.items()
                  if s.get("user_id") == user_id]:
            _sessions.pop(t, None)
    # Durable session rows too (teardown 06-03) — deletion is the
    # revoke-all path, so no token may survive in the persistent store.
    try:
        delete_persisted_sessions_for_user(user_id)
    except Exception as e:
        log.warning("delete_account: durable session cleanup failed: %s", e)
    log.info("delete_account: user %s deleted (%s)", user_id, counts)
    return jsonify({"ok": True, "deleted": counts,
                    "apple_revoked": apple_revoked})


@app.route("/api/session/signout", methods=["POST"])
def session_signout():
    """Server-side sign-out (teardown 06-03 lifecycle hygiene): evict the
    calling session token so client sign-out revokes the server copy too —
    previously sign-out only cleared device storage and the token stayed
    live until idle eviction.

    Idempotent and never fails: holding the token IS the authorization to
    kill it, and a stale/unknown token simply reports evicted=false. Called
    best-effort by clients — a network failure must never block sign-out.
    """
    token = request.headers.get("X-Session-Token", "")
    evicted = False
    if token:
        with _sessions_lock:
            evicted = _sessions.pop(token, None) is not None
        # Durable row too (teardown 06-03). Unconditional — a row may exist
        # from a flag-on period even if the flag is off right now.
        try:
            evicted = delete_persisted_session(token) or evicted
        except Exception as e:
            log.warning("session/signout: durable delete failed: %s", e)
    if evicted:
        log.info("session/signout: token evicted")
    return jsonify({"ok": True, "evicted": evicted})


# ---------------------------------------------------------------------------
# ESPN league linking — Phase 1 read-only import (#101 / feedback #115)
# Flag: `espn.link` (default OFF — every route 404s dark).
# Plan: docs/plans/espn-league-linking-plan-2026-07-11.md
#
# Flow: POST /api/espn/link without team_id → preview (teams + crosswalk
# match report, nothing persisted) → the user picks their team → POST again
# with team_id → league + members persisted (rosters as crosswalked SLEEPER
# player ids). The mobile client then activates the league through the
# standard /api/session/init using GET /api/espn/leagues as the roster
# source (no session_init changes needed — its existing DB-member merge and
# upsert paths treat the imported league like any other).
#
# Binding note (account-first seam): imported leagues bind to the session's
# user_id as identity works TODAY (Sleeper-keyed users). When the
# account-first model lands, this binding rides along automatically because
# it lives in leagues.user_id / league_members.user_id — the same seam every
# Sleeper league sits on. Counterparties get synthetic `espn:` user ids that
# must never reach push/notification paths (same class as unlinked members).
#
# Private leagues: espn_s2+SWID cookies may be pasted with the link request;
# they are Fernet-encrypted at rest (SLEEPER_TOKEN_KEY) and replayed on
# re-imports. The in-app WebView cookie capture is Phase 1b.
# ---------------------------------------------------------------------------

_ESPN_DEFAULT_SEASON = 2026


def _espn_member_id(league_id: str, team) -> str:
    """Deterministic synthetic user_id for a non-FTF ESPN manager."""
    if team.owner_swid:
        return f"espn:{team.owner_swid}"
    return f"espn:{league_id}.t{team.team_id}"


def _espn_error_response(e):
    """Map an EspnError to a (json, status) response."""
    kind = getattr(e, "kind", "http")
    if kind == "auth":
        return jsonify({
            "error": "espn_auth_required",
            "message": "ESPN wouldn't share this league — it's private or the "
                       "saved cookies expired. Paste fresh espn_s2 + SWID "
                       "cookies to continue.",
        }), 403
    if kind == "not_found":
        return jsonify({
            "error": "espn_league_not_found",
            "message": "ESPN has no league with that ID for that season. "
                       "ESPN purges old leagues — check the ID and season.",
        }), 404
    if kind == "input":
        return jsonify({"error": "espn_bad_league_id",
                        "message": "ESPN league IDs are numeric."}), 400
    log.warning("espn fetch failed [%s]: %s", kind, e)
    return jsonify({"error": "espn_unavailable",
                    "message": "Couldn't reach ESPN — try again shortly."}), 502


def _espn_import_payload(league_id: str, season: int, espn_s2: str | None,
                         swid: str | None):
    """Fetch + parse + crosswalk one ESPN league. Returns (league, mapped)."""
    from . import espn_service as _espn
    raw = _espn.fetch_league(league_id, season, espn_s2=espn_s2, swid=swid)
    league = _espn.parse_league(raw)
    mapped = _espn.map_rosters(league["teams"], _espn.get_crosswalk())
    return league, mapped


def _espn_report_json(report: dict) -> dict:
    """Client-facing crosswalk report — unmatched players are skipped from
    rosters and reported by name (plan §3: never invent placeholders)."""
    return {
        "pool_players":    report["pool_players"],
        "matched_by_id":   report["matched_by_id"],
        "matched_by_name": report["matched_by_name"],
        "match_rate":      round(report["match_rate"], 4),
        "out_of_pool":     report["out_of_pool"],
        "unmatched":       [
            {"name": u["name"], "position": u["position"]}
            for u in report["unmatched"]
        ],
    }


def _espn_verify_credential(user_id: str, espn_s2: str, swid: str):
    """Prove an ESPN cookie pair against ESPN BEFORE it is stored.

    Returns `(verdict, oracle, detail)`:
      "ok"          — the server observed a successful AUTHENTICATED read
                      with this exact pair. `oracle` names what proved it.
      "bad"         — ESPN answered and the pair proved nothing (a rejection,
                      or a read that returned no account-specific data).
                      Credential verdict → 403 espn_bad_credentials.
      "unavailable" — transport failure / 5xx / a 200 that didn't parse. NOT
                      a verdict on the cookies → 502 espn_unavailable.

    ORACLE CHOICE (verification-oracle fix, 2026-08-12). Two probes, in
    strength order:

    1. `league_read` (STRONG, preferred) — one `fetch_league` of a league the
       user has ALREADY linked whose stored `espn_auth` is 'cookie', i.e. a
       league ESPN refuses to serve without a valid member session. A 200
       that parses into that league's team data is a genuine authenticated
       read. This is the same pre-flight the ESPN send path runs, and it is
       what actually rejected the bad pair in the production incident (as
       the send's 409) after the store had already called it verified.
    2. `fan_profile` (WEAK fallback) — used only when the user has no
       auth-gated linked league (no ESPN league yet, or only PUBLIC ones,
       which read fine with no cookies at all and so prove nothing). The fan
       endpoint keys on the SWID in the URL path and FTF's only live evidence
       is that an UNKNOWN SWID 404s — a SWID-existence result, not proof that
       `espn_s2` was validated (docs/integrations/espn.md §1.7). So it is
       accepted only when it returns account-specific fantasy data, and the
       weaker oracle is recorded on every success.

    ZERO FALSE REJECTS on the weak path: an ESPN account with no FOOTBALL
    leagues (baseball/hockey only, or brand-new to fantasy) is legitimate, so
    the rule is "the read returned this account's fantasy data" — entries of
    ANY sport pass. Only a payload with no fantasy evidence at all — what an
    anonymous or partial cookie pair produces — is refused.
    """
    from . import espn_service as _espn
    from .database import load_espn_leagues_for_user

    # 1. Strong oracle: an already-linked league ESPN only serves to a
    #    signed-in member. PUBLIC links are skipped on purpose.
    gated = None
    try:
        for lg in load_espn_leagues_for_user(user_id):
            if (lg.get("espn_auth") or "") == "cookie" and \
                    str(lg.get("league_id") or "").isdigit():
                gated = lg
                break
    except Exception:
        log.exception("espn verify: linked-league lookup failed for %s", user_id)

    if gated:
        lid = str(gated["league_id"])
        try:
            season = int(gated.get("season") or _ESPN_DEFAULT_SEASON)
        except (TypeError, ValueError):
            season = _ESPN_DEFAULT_SEASON
        try:
            raw = _espn.fetch_league(lid, season, espn_s2=espn_s2, swid=swid)
        except _espn.EspnAuthError:
            return "bad", "league_read", "rejected"
        except _espn.EspnError as e:
            if getattr(e, "kind", "") != "not_found":
                return "unavailable", "league_read", getattr(e, "kind", "http")
            # ESPN purges old leagues — the ORACLE is gone, which says
            # nothing about the cookies. Fall through to the fan probe
            # rather than falsely rejecting a good sign-in.
            log.info("espn verify: linked league %s purged — falling back", lid)
        except OSError as e:
            log.warning("espn verify: league oracle transport failure: %s", e)
            return "unavailable", "league_read", "transport"
        else:
            # BIND AND ASSERT the result: a 200 is only proof if it actually
            # parses into this league's teams (edge/interstitial pages
            # answer 200 too). Anything else is "couldn't confirm".
            try:
                teams = _espn.parse_league(raw)["teams"] if isinstance(raw, dict) else []
            except Exception:
                teams = []
            if teams:
                return "ok", "league_read", lid
            log.warning("espn verify: league oracle 200 didn't parse (league=%s)",
                        lid)
            return "unavailable", "league_read", "unrecognized_payload"

    # 2. Weak fallback: the fan profile. Result is BOUND and asserted — an
    #    empty/unrecognised payload is NOT a pass (that was the bug).
    try:
        probe = _espn.probe_fan_profile(espn_s2, swid)
    except _espn.EspnAuthError:
        return "bad", "fan_profile", "rejected"
    except (_espn.EspnError, OSError) as e:
        log.warning("espn verify: fan probe unavailable [%s]: %s",
                    getattr(e, "kind", "transport"), e)
        return "unavailable", "fan_profile", getattr(e, "kind", "transport")

    if probe.get("football_leagues"):
        return "ok", "fan_profile", f"{len(probe['football_leagues'])} ffl"
    if probe.get("fantasy_entries"):
        # Real account, no FOOTBALL leagues — legitimate, not a rejection.
        return "ok", "fan_profile", "no_football_leagues"
    return "bad", "fan_profile", "no_account_data"


@app.route("/api/espn/link", methods=["GET", "POST", "DELETE"])
@_gate_unverified_write
def espn_link():
    """Link (import) an ESPN league — and manage the ESPN account credential.

    DELETE → drop the stored espn_s2/SWID pair (disconnect), mirroring
    DELETE /api/sleeper/link. Idempotent: deleting with nothing stored is a
    clean 200 {connected: false}. Scoped to the CALLER's row only. Added
    after the 2026-08-12 incident: a user who signed in with someone else's
    ESPN account had no way to remove the captured cookies short of a manual
    production-DB delete.

    GET → link status, mirroring GET /api/sleeper/link (send-auth lazy flow,
    2026-08-11): {connected, expires_at, expired, verified_at}. Never returns
    the cookies. `connected` requires BOTH stored halves (espn_s2 + SWID — a
    row missing its SWID can't authenticate anything) AND a verified_at stamp
    (credential-honesty fix, 2026-08-12): a pair that never passed a live
    authenticated ESPN read reads as NOT connected, so the client re-runs
    sign-in instead of trusting an unproven pair. No live call happens here —
    status reads stay cheap; verification happens at store time.

    POST body: {espn_league_id?, season?, team_id?, espn_s2?, swid?}
      • espn_s2+swid, NO espn_league_id → CREDENTIAL-ONLY store (send-auth
        lazy flow): VERIFY the pair with one live read whose RESULT IS
        ASSERTED (_espn_verify_credential — an authenticated read of an
        already-linked private league when there is one, else the weaker
        fan-profile probe, which must return account-specific fantasy data),
        then persist it encrypted with verified_at stamped and return
        {connected: true, verified_via: "league_read"|"fan_profile"}. Used by
        the ESPN Connect WebView entered from the trade-send path — the
        league is already imported; only the account credential is missing.
        A pair ESPN rejects — or one whose read came back with nothing to
        prove it — is NOT stored: 403 espn_bad_credentials (sign in again).
        ESPN unreachable/5xx/unparseable is NOT a credential verdict: 502
        espn_unavailable (retry), and nothing is stored either. MFL (login +
        myleagues) and Sleeper (verify_token_live) already refuse to store
        unproven credentials — this brings ESPN to parity.

        `verified_at` MEANS EXACTLY ONE THING: the SERVER observed a
        successful AUTHENTICATED read from ESPN using this pair. It is not
        "the client captured cookies", not "the user looked signed in", and
        not "ESPN answered 200". Any device-reported or heuristic signal
        added later gets its OWN column — never widen this one, or the
        honesty gate on GET degrades back into the bug it was added for.
      • no team_id  → PREVIEW: fetch + crosswalk, return the team list and
        match report; nothing is persisted.
      • team_id     → IMPORT: persist the league (platform='espn') + all
        member rosters (Sleeper player ids); the chosen team binds to the
        session's user_id. Idempotent — re-linking refreshes everything.
      • espn_s2+swid (both or neither) → private-league cookies; encrypted
        at rest and reused for future re-imports.
    404 while the espn.link flag is off.
    """
    if not is_enabled("espn.link"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import espn_service as _espn
    from .database import (get_espn_credential, upsert_espn_credential,
                           delete_espn_credential,
                           upsert_espn_league, replace_espn_league_members)

    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    if request.method == "DELETE":
        # Write gate already applied by @_gate_unverified_write (DELETE is a
        # mutating method) — mirroring the Sleeper DELETE's denial check.
        # delete_espn_credential is user_id-scoped and a no-op when nothing
        # is stored, so this is idempotent by construction.
        delete_espn_credential(user_id)
        log.info("espn_link: credential deleted (disconnect) user=%s", user_id)
        return jsonify({"connected": False})

    if request.method == "GET":
        cred = get_espn_credential(user_id)
        # Honesty gate (2026-08-12): swid-less rows can't authenticate, and
        # rows without verified_at were never proven against ESPN (legacy
        # pre-verification stores) — both read as not connected so the
        # client re-runs the sign-in flow, which verifies before storing.
        if not cred or not cred.get("swid") or not cred.get("verified_at"):
            return jsonify({"connected": False})
        expires_at = cred.get("expires_hint_at")
        expired = False
        if expires_at:
            try:
                expired = (datetime.fromisoformat(expires_at)
                           <= datetime.now(timezone.utc))
            except Exception:
                expired = False
        return jsonify({"connected": True,
                        "expires_at": expires_at,
                        "expired": expired,
                        "verified_at": cred.get("verified_at")})

    body = request.get_json(force=True) or {}
    league_id = str(body.get("espn_league_id") or "").strip()

    espn_s2 = (body.get("espn_s2") or "").strip() or None
    swid    = (body.get("swid") or "").strip() or None
    if bool(espn_s2) != bool(swid):
        return jsonify({"error": "espn_cookies_incomplete",
                        "message": "Private leagues need BOTH espn_s2 and SWID."}), 400

    # Credential-only store (send-auth lazy flow, 2026-08-11): both cookies,
    # no league id. The ESPN Connect WebView entered from the SEND path has
    # no league to link — it just needs the captured pair persisted so
    # POST /api/trades/propose-espn can read it.
    if not league_id and espn_s2:
        if not _sleeper_write.token_encryption_available():
            return jsonify({"error": "espn_unconfigured",
                            "message": "Credential encryption key missing."}), 503
        # Verify BEFORE storing (credential-honesty fix, 2026-08-12;
        # oracle fix same day): _espn_verify_credential runs ONE live read
        # whose RESULT IS BOUND AND ASSERTED — preferring an authenticated
        # read of an already-linked private league, falling back to the
        # weaker fan-profile probe. Its verdict, not merely "no exception",
        # decides whether anything is stored. The original version called
        # fetch_fan_leagues without binding the return value; since
        # _parse_fan_leagues never raises, a 200 with an unrecognised shape
        # (what an anonymous/partial pair produces) was stored as verified,
        # reported {connected:true}, and only surfaced as a 409 at the next
        # trade send. MFL/Sleeper never had this gap.
        verdict, oracle, detail = _espn_verify_credential(user_id, espn_s2, swid)
        if verdict == "bad":
            # ESPN answered and the pair proved nothing — a credential
            # verdict, not an outage. Nothing is stored; the client re-runs
            # the sign-in. One error code (the client maps it to a fresh
            # sign-in); the message distinguishes the two ways to get here.
            log.info("espn_link: credential verification failed user=%s "
                     "oracle=%s detail=%s", user_id, oracle, detail)
            if detail == "no_account_data":
                msg = ("That ESPN sign-in didn't come back with your account, "
                       "so nothing was saved. Sign in to ESPN again.")
            elif oracle == "league_read":
                # The pair may be a perfectly good sign-in for SOME ESPN
                # account — just not one that can read this user's linked
                # league (the incident's shape: cookies captured from
                # someone else's account). Storing it would only defer the
                # failure to the send, which is the bug being fixed, so it
                # is refused — with copy that names the actual recovery.
                msg = ("That ESPN account can't open your linked league, so "
                       "nothing was saved. Sign in with the ESPN account "
                       "that owns your team.")
            else:
                msg = ("ESPN didn't accept that sign-in — nothing was saved. "
                       "Sign in to ESPN again.")
            return jsonify({"error": "espn_bad_credentials",
                            "message": msg}), 403
        if verdict != "ok":
            # Transport failure / ESPN 5xx / non-JSON edge page. NOT a
            # verdict on the cookies — a user with a good sign-in must never
            # be told it's bad because ESPN was down. Distinct, retryable
            # code; nothing stored (an unproven pair must not reach the DB).
            log.warning("espn_link: credential verification unavailable "
                        "user=%s oracle=%s detail=%s", user_id, oracle, detail)
            return jsonify({
                "error": "espn_unavailable",
                "message": "Couldn't reach ESPN to confirm the sign-in — "
                           "nothing was saved. Try again shortly.",
            }), 502
        try:
            upsert_espn_credential(
                user_id, swid, _sleeper_write.encrypt_token(espn_s2),
                verified_at=datetime.now(timezone.utc).isoformat())
        except Exception:
            log.exception("espn_link: credential-only store failed")
            return jsonify({"error": "store_failed"}), 500
        # Log WHICH oracle proved it: 'fan_profile' is the weaker one (see
        # _espn_verify_credential), so a support question about a pair that
        # verified and then failed at send time can be answered from logs.
        log.info("espn_link: credential-only store user=%s (verified via %s "
                 "— %s)", user_id, oracle, detail)
        return jsonify({"connected": True, "stored": "credential",
                        "verified": True, "verified_via": oracle})

    if not league_id.isdigit():
        return jsonify({"error": "espn_bad_league_id",
                        "message": "ESPN league IDs are numeric."}), 400
    try:
        season = int(body.get("season") or _ESPN_DEFAULT_SEASON)
    except (TypeError, ValueError):
        return jsonify({"error": "espn_bad_season"}), 400

    # Fall back to previously-stored cookies so re-links of a private league
    # don't require a fresh paste.
    pasted_cookie = bool(espn_s2)
    if not espn_s2:
        cred = get_espn_credential(user_id)
        if cred:
            try:
                espn_s2 = _sleeper_write.decrypt_token(cred["espn_s2_encrypted"])
                swid = cred.get("swid")
            except _sleeper_write.SleeperWriteError as e:
                log.warning("espn_link: stored cookie undecryptable for %s: %s",
                            user_id, e)
                espn_s2 = swid = None

    try:
        league, mapped = _espn_import_payload(league_id, season, espn_s2, swid)
    except _espn.EspnError as e:
        return _espn_error_response(e)

    teams_json = [
        {
            "team_id":        t.team_id,
            "name":           t.name,
            "owner_display":  t.owner_display,
            "mapped_players": len(mapped["rosters"].get(t.team_id, [])),
        }
        for t in league["teams"]
    ]

    team_id = body.get("team_id")
    if team_id is None:
        # Preview — the client renders "which team is yours?"
        return jsonify({
            "status": "choose_team",
            "league": {
                "espn_league_id": league["league_id"] or league_id,
                "name":           league["name"],
                "season":         league["season"] or season,
                "total_teams":    league["total_teams"],
            },
            "teams":  teams_json,
            "report": _espn_report_json(mapped["report"]),
        })

    try:
        team_id = int(team_id)
    except (TypeError, ValueError):
        return jsonify({"error": "espn_bad_team_id"}), 400
    if team_id not in {t.team_id for t in league["teams"]}:
        return jsonify({"error": "espn_bad_team_id",
                        "message": "That team isn't in this league."}), 400

    # Persist cookies first (so a later re-import can reuse them), then the
    # league + membership snapshot.
    auth_mode = "cookie" if (espn_s2 and swid) else "public"
    if pasted_cookie:
        if not _sleeper_write.token_encryption_available():
            return jsonify({"error": "espn_unconfigured",
                            "message": "Credential encryption key missing."}), 503
        try:
            # verified_at: the league fetch above already succeeded WITH this
            # pair attached — and the in-app flow only collects cookies after
            # an anonymous read 403s (private league), so that fetch was a
            # genuine authenticated proof. No second probe (don't double-hit
            # ESPN or slow the import).
            upsert_espn_credential(
                user_id, swid, _sleeper_write.encrypt_token(espn_s2),
                verified_at=datetime.now(timezone.utc).isoformat())
        except Exception:
            log.exception("espn_link: credential store failed")
            return jsonify({"error": "store_failed"}), 500

    members = []
    for t in league["teams"]:
        mid = user_id if t.team_id == team_id else _espn_member_id(league_id, t)
        members.append({
            "user_id":      mid,
            "username":     t.owner_display or t.name,
            "display_name": t.name,
            "player_ids":   mapped["rosters"].get(t.team_id, []),
            # ADR-011 — the platform-native team slot, captured at the one
            # line where it is in scope (it used to be discarded here).
            "team_key":     f"espn:{league_id}.t{t.team_id}",
        })
    try:
        upsert_espn_league(
            league_id       = league_id,
            user_id         = user_id,
            name            = league["name"] or f"ESPN league {league_id}",
            espn_season     = league["season"] or season,
            espn_auth       = auth_mode,
            espn_my_team_id = team_id,
            total_rosters   = league["total_teams"],
        )
        replace_espn_league_members(league_id, members)
    except Exception:
        log.exception("espn_link: persistence failed")
        return jsonify({"error": "store_failed"}), 500

    # ADR-011 Writer A — AFTER the membership transaction committed.
    _platform_roster_history_on_sync(
        league_id, "espn", members,
        my_user_id=user_id, my_team_key=f"espn:{league_id}.t{team_id}")

    r = mapped["report"]
    log.info("espn_link: user=%s league=%s season=%s teams=%d auth=%s "
             "match_rate=%.1f%% unmatched=%d",
             user_id, league_id, season, len(members), auth_mode,
             r["match_rate"] * 100, len(r["unmatched"]))
    return jsonify({
        "ok": True,
        "league_id":      league_id,
        "name":           league["name"],
        "platform":       "espn",
        "season":         league["season"] or season,
        "auth":           auth_mode,
        "total_teams":    league["total_teams"],
        "teams_imported": len(members),
        "my_team_id":     team_id,
        "my_roster":      mapped["rosters"].get(team_id, []),
        "report":         _espn_report_json(r),
    })


@app.route("/api/espn/leagues")
def espn_leagues():
    """ESPN leagues linked by the session user, with the full membership
    snapshot (Sleeper player ids) so the client can build a standard
    /api/session/init body. 404 while the espn.link flag is off."""
    if not is_enabled("espn.link"):
        return jsonify({"error": "feature_disabled"}), 404
    from .database import load_espn_leagues_for_user
    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401
    leagues = load_espn_leagues_for_user(user_id)
    for lg in leagues:
        lg["members"] = [
            {
                "user_id":      m["user_id"],
                "username":     m.get("username") or "",
                "display_name": m.get("display_name") or "",
                "player_ids":   m.get("player_ids", []),
            }
            for m in lg["members"]
        ]
    return jsonify({"leagues": leagues})


@app.route("/api/espn/my-leagues")
def espn_my_leagues():
    """Discover the ESPN fantasy football leagues the session user's ESPN
    account belongs to, via the fan-profile endpoint — so the client can
    offer a league PICKER instead of asking for a league ID (feedback:
    "can't we fetch all their ESPN leagues and let them pick?").

    Uses the session user's STORED espn_credentials row (the same cookies
    captured by the WebView sign-in or a prior manual paste that was sent to
    /api/espn/link) — there is no body, and this route never accepts pasted
    cookies itself; it is a read-only convenience layer in front of the
    existing link flow. Public leagues are unaffected — manual league-id
    entry (which needs no login) stays the fallback path this route doesn't
    touch.

    404 while `espn.league_picker` is off. 403 `espn_auth_required` when no
    ESPN session is stored yet, or ESPN rejects the stored one (sign in
    again — same recovery UX as the existing link-flow 403). 503
    `espn_unconfigured` if the stored cookie can't be decrypted (fail-closed,
    mirrors espn_import). 200 `{"leagues": []}` when the account genuinely
    has none — never fabricated. A fan-API shape surprise degrades to a
    partial/empty list, never a 500 (espn_service._parse_fan_leagues).
    """
    if not is_enabled("espn.league_picker"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import espn_service as _espn
    from .database import get_espn_credential

    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    cred = get_espn_credential(user_id)
    if not cred:
        return jsonify({
            "error": "espn_auth_required",
            "message": "Sign in to ESPN first so we can see your leagues.",
        }), 403
    try:
        espn_s2 = _sleeper_write.decrypt_token(cred["espn_s2_encrypted"])
        swid = cred.get("swid")
    except _sleeper_write.SleeperWriteError as e:
        log.warning("espn_my_leagues: stored cookie undecryptable for %s: %s",
                    user_id, e)
        return jsonify({"error": "espn_unconfigured"}), 503
    if not espn_s2 or not swid:
        return jsonify({
            "error": "espn_auth_required",
            "message": "Sign in to ESPN first so we can see your leagues.",
        }), 403

    try:
        leagues = _espn.fetch_fan_leagues(espn_s2, swid)
    except _espn.EspnError as e:
        return _espn_error_response(e)

    return jsonify({"leagues": leagues})


@app.route("/api/espn/import", methods=["POST"])
@_gate_unverified_write
def espn_import():
    """Re-sync an already-linked ESPN league's rosters (manual refresh).

    Body: {league_id}. Re-fetches from ESPN using the stored auth mode
    (public, or the user's encrypted cookies), re-runs the crosswalk, and
    replaces the membership snapshot while preserving the user's team
    binding. 404 while the espn.link flag is off; 403 espn_auth_required
    when a private league's cookies are missing/expired (reconnect UX).
    """
    if not is_enabled("espn.link"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import espn_service as _espn
    from .database import (get_espn_league, get_espn_credential,
                           replace_espn_league_members, upsert_espn_league)

    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    body = request.get_json(force=True) or {}
    league_id = str(body.get("league_id") or "").strip()
    row = get_espn_league(league_id) if league_id else None
    if not row:
        return jsonify({"error": "espn_not_linked",
                        "message": "Link this ESPN league first."}), 404

    espn_s2 = swid = None
    if row.get("espn_auth") == "cookie":
        cred = get_espn_credential(user_id)
        if not cred:
            return jsonify({"error": "espn_auth_required",
                            "message": "This private league needs your ESPN "
                                       "cookies again."}), 403
        try:
            espn_s2 = _sleeper_write.decrypt_token(cred["espn_s2_encrypted"])
            swid = cred.get("swid")
        except _sleeper_write.SleeperWriteError:
            return jsonify({"error": "espn_unconfigured"}), 503

    season = row.get("espn_season") or _ESPN_DEFAULT_SEASON
    try:
        league, mapped = _espn_import_payload(league_id, season, espn_s2, swid)
    except _espn.EspnError as e:
        return _espn_error_response(e)

    my_team_id = row.get("espn_my_team_id")
    if my_team_id not in {t.team_id for t in league["teams"]}:
        return jsonify({"error": "espn_team_missing",
                        "message": "Your team is no longer in this ESPN "
                                   "league — re-link to pick a team."}), 409

    members = []
    for t in league["teams"]:
        mid = user_id if t.team_id == my_team_id else _espn_member_id(league_id, t)
        members.append({
            "user_id":      mid,
            "username":     t.owner_display or t.name,
            "display_name": t.name,
            "player_ids":   mapped["rosters"].get(t.team_id, []),
            "team_key":     f"espn:{league_id}.t{t.team_id}",   # ADR-011
        })
    try:
        upsert_espn_league(
            league_id       = league_id,
            user_id         = row["user_id"],
            name            = league["name"] or row.get("name") or "",
            espn_season     = league["season"] or season,
            espn_auth       = row.get("espn_auth") or "public",
            espn_my_team_id = my_team_id,
            total_rosters   = league["total_teams"],
        )
        replace_espn_league_members(league_id, members)
    except Exception:
        log.exception("espn_import: persistence failed")
        return jsonify({"error": "store_failed"}), 500

    # ADR-011 Writer A — after the membership transaction committed.
    _platform_roster_history_on_sync(
        league_id, "espn", members,
        my_user_id=user_id, my_team_key=f"espn:{league_id}.t{my_team_id}")

    return jsonify({
        "ok": True,
        "league_id":      league_id,
        "name":           league["name"],
        "platform":       "espn",
        "season":         league["season"] or season,
        "auth":           row.get("espn_auth") or "public",
        "total_teams":    league["total_teams"],
        "teams_imported": len(members),
        "my_team_id":     my_team_id,
        "my_roster":      mapped["rosters"].get(my_team_id, []),
        "report":         _espn_report_json(mapped["report"]),
    })


# ---------------------------------------------------------------------------
# League power rankings (#142/#144/#14) — math in backend/power_rankings.py
# ---------------------------------------------------------------------------

def _power_ranking_inputs(sess: dict, league_id: str):
    """Shared input loading for /api/league/power-rankings and
    /api/league/rank-chip (so chip ranks always agree with the page).

    Returns (members, seed, players_meta, fmt); members is None when the
    league can't be resolved. members comes from the league_members snapshot,
    falling back to the in-session league for fresh/demo leagues.
    """
    fmt = _active_format(sess)
    g_league = sess.get("league")
    members = load_league_members(league_id)
    if not members and g_league and g_league.league_id == league_id:
        # Fresh/demo leagues may not have a league_members snapshot yet —
        # fall back to the in-session league (leaguemates) + the caller's
        # own roster (session league members exclude the caller).
        members = [{
            "user_id":      m.user_id,
            "username":     m.username,
            "display_name": m.username,
            "player_ids":   list(m.roster),
        } for m in g_league.members]
        # League identity, so this synthetic row carries the same key the
        # league_members snapshot will once the daemon writes it — otherwise
        # a co-owner's `is_you` would flip depending on which source served.
        _me = _league_user_id(sess)
        members.append({
            "user_id":      _me,
            "username":     sess.get("display_name") or _me,
            "display_name": sess.get("display_name") or _me,
            "player_ids":   list(sess.get("user_roster") or []),
        })
    if not members:
        return None, {}, {}, fmt

    pool_players, seed = _get_universal_pool(fmt)
    # Demo-style sessions rank a synthetic player pool whose ids never
    # appear in the universal pool; their consensus lives in the session
    # service's seed ratings. Merge those in as a FALLBACK (pool seed
    # wins) so demo consensus totals aren't all-zero. Real leagues are
    # unaffected — their session ranking pool is the universal pool.
    svc_seed = getattr(sess.get("service"), "_seed", None) or {}
    if svc_seed:
        seed = {**svc_seed, **seed}
    # Metadata: universal pool first, session players filling any gaps
    # (league roster players outside the pool still need name/position).
    players_meta = {p.id: p for p in pool_players}
    for p in (sess.get("players") or []):
        players_meta.setdefault(p.id, p)
    return members, seed, players_meta, fmt


def _power_picks_by_owner(league_id: str, fmt: str) -> dict[str, list[dict]]:
    """Owned-pick items per owner_user_id for the power-rankings picks group
    (#14 FR1): {owner_user_id: [{label, value, round}, ...]}.

    Same source as /api/league/picks (load_draft_picks + _owned_pick_label).
    ESPN leagues carry no pick ownership (#158) and demo leagues have no
    rows — both yield {} so every team gets an empty picks group and totals
    stay players-only. Value is the stored pool_value (written at sync via
    pick_values.pick_pool_value); rows synced before the pool_value column
    existed are re-priced via pick_pool_value directly, years_out relative
    to the earliest synced season (sync writes seasons starting at the
    league's current season, so min(season) recovers it).

    `round` (#285, docs/feedback/items/285-pick-sums/status.md) rides each
    item purely for `_pick_firsts_equivalent`'s literal pick-count label
    math — `compute_power_rankings` builds its serialized `picks.items`
    from only `label`/`value`, so this extra key is inert for every caller
    that doesn't read it directly off this dict (i.e. everyone but the
    #285 experiment-gated branch in league_power_rankings_route).
    """
    if not league_id or league_id == "league_demo":
        return {}
    try:
        rows = load_draft_picks(league_id=league_id, source=_pick_read_source())
    except Exception as e:
        log.warning("power-rankings pick load failed (continuing): %s", e)
        return {}
    seasons = [int(r["season"]) for r in rows if r.get("season") is not None]
    cur_season = min(seasons) if seasons else 0
    tradeable = _asserted_picks_tradeable()
    out: dict[str, list[dict]] = {}
    for p in rows:
        owner = str(p.get("owner_user_id") or "")
        if not owner:
            continue
        val = p.get("pool_value")
        if val is None:
            # NOTE (INV-5): this NULL branch is exactly why a contested slot is
            # withheld by ROW FILTER and never by nulling `pool_value` — nulling
            # would land here and silently re-derive the price the rule exists
            # to withhold.
            years_out = max(0, int(p.get("season") or cur_season) - cur_season)
            val = pick_pool_value(int(p.get("round") or 4), years_out, fmt)
        out.setdefault(owner, []).append({
            "label": _owned_pick_label(p),
            "value": round(float(val), 1),
            # #285 — round for _pick_firsts_equivalent's literal pick-count
            # label math; never serialized on its own (see docstring above).
            "round": int(p.get("round") or 0),
            # W3 M-C (S2) — provenance + the deep-link coordinates. The items
            # carried neither before, so `pick_id`/`season` ride the same flag.
            **({"pick_id": str(p.get("pick_id") or "")} if tradeable else {}),
            **_pick_wire_source(p, tradeable, with_season=True),
        })
    return out


def _sleeper_lineup_slots(league_id: str) -> list[str] | None:
    """The league's starting-slot template for the derived starters/bench
    split (League Analyzer replication, 2026-07-26): Sleeper roster_positions
    filtered to the slots the value pool can fill (QB/RB/WR/TE + flex types —
    power_rankings.LINEUP_SLOT_ELIGIBILITY). None for non-Sleeper league ids
    (ESPN/MFL/Fleaflicker imports, demo) or when the meta can't be fetched —
    callers degrade by omitting the split (never fabricate). Reuses the #179
    15-min league-meta cache, so steady-state this costs no network call.
    """
    from .power_rankings import LINEUP_SLOT_ELIGIBILITY
    if not league_id or not str(league_id).isdigit():
        return None
    now = time.time()
    hit = _FA_LEAGUE_META_CACHE.get(league_id)
    if hit is not None and (now - hit[0]) < _FA_LEAGUE_META_TTL:
        meta = hit[1]
    else:
        meta = _fetch_sleeper_league_meta(league_id) or {}
        _FA_LEAGUE_META_CACHE[league_id] = (now, meta)
    slots = [s for s in (meta.get("roster_positions") or [])
             if s in LINEUP_SLOT_ELIGIBILITY]
    return slots or None


def _league_lineup_slots(league_id: str) -> list[str] | None:
    """The league's starting-slot template, all platforms (#311).

    ESPN/MFL league ids are NUMERIC (the `leagues` PK holds the
    platform-native id), so id-shape checks cannot distinguish platforms —
    resolution branches on the `leagues.platform` column instead:

      1. `leagues` row lookup by PK (one indexed select: platform,
         default_scoring). No leagues row → None (never guess a template
         for an unknown league).
      2. platform in ('espn', 'mfl', 'fleaflicker') → the app's one
         standard template (`_MOCK_DEFAULT_LINEUP`), plus a trailing
         SUPER_FLEX when default_scoring == 'sf_tep' (NULL reads as
         '1qb_ppr', the database.py convention). These platforms expose no
         roster_positions equivalent today; slot-FILLING stays 100%
         value-based via power_rankings, so "starting lineup based on
         dynasty values" holds — only the template is standardized.
         Persisting each league's REAL template at import is the logged
         phase-2 follow-up, not this helper.
      3. platform 'sleeper' / NULL → _sleeper_lineup_slots(league_id),
         byte-identical to the pre-#311 behavior (live meta via the #179
         cache). Never consulted for platform leagues, so a numeric ESPN
         id can no longer trigger a doomed Sleeper meta fetch.
      4. Any other platform (e.g. demo leagues) → None — callers degrade
         by omitting the starters/bench split, never fabricate.
    """
    if not league_id:
        return None
    from sqlalchemy import select as _sa_select
    from .database import leagues_table, engine as _db_engine
    try:
        with _db_engine.connect() as conn:
            row = conn.execute(
                _sa_select(
                    leagues_table.c.platform,
                    leagues_table.c.default_scoring,
                ).where(leagues_table.c.sleeper_league_id == str(league_id))
            ).fetchone()
    except Exception as e:
        log.warning("_league_lineup_slots: leagues lookup failed for %s: %s",
                    league_id, e)
        return None
    if row is None:
        return None
    platform = (row.platform or "sleeper").lower()
    if platform in ("espn", "mfl", "fleaflicker"):
        slots = list(_MOCK_DEFAULT_LINEUP)
        if (row.default_scoring or "1qb_ppr") == "sf_tep":
            slots.append("SUPER_FLEX")
        return slots
    if platform == "sleeper":
        return _sleeper_lineup_slots(league_id)
    return None


def _position_medians(teams: list[dict]) -> dict[str, dict]:
    """#300 — the league's MEDIAN positional value per core position, with its
    pick-equivalent label (docs/feedback/items/300-league-rankings-trade-
    candidates/operator-answers-2026-08-12.md, the frozen design).

    Shape: ``{QB|RB|WR|TE: {value, value_label}}``. The mobile client draws one
    labelled divider on the League rankings list when exactly one core position
    is selected; it can compute the median VALUE itself but cannot LABEL it —
    labelling is server-side — which is the entire reason this field exists.

    Three decisions, recorded because the field is a frozen cross-client
    contract:

    1. **Population = every team in the payload, the caller included.** The
       divider is drawn on the very list `teams` serializes, and the frozen
       design keeps the caller's own team in that list as the anchor ("there is
       no separate section for it to be wrongly included in"). Excluding the
       caller would put the line in a different place than the list it is drawn
       across.
    2. **Even team counts take the MEAN of the two middle values** — the
       textbook median, and what a naive client-side implementation computes,
       so the server's `value` and the client's agree. It also preserves the
       property the design leans on for odd counts: an odd league leaves
       exactly one team sitting ON the median, an even one leaves none.
       Rounded to 1dp like every other value on this wire.
    3. **`value_label` is UNGATED.** The per-team `value_label` under `#279`
       rides the operator-only `aggregate_tier_labels` experiment, but
       `_aggregate_pick_label` is a pure function of the value with no
       experiment dependency — it is read directly here. A divider that
       rendered a label for the operator and a blank for everyone else would
       be worse than no divider.

    SUBSET SCOPE — the All subset ONLY. `teams[].positions[P].value` is the
    whole-roster positional subtotal; the client's Starters/Bench subsets are
    derived client-side from `roster` + `starters`, and the frozen field shape
    has no room for a per-subset median. The client must therefore render the
    divider only while the subset is All, never label a Starters/Bench line
    with this value. Empty `teams` → `{}` (no list, so no divider; never a
    fabricated 0.0).
    """
    from .power_rankings import CORE_POSITIONS
    if not teams:
        return {}
    out: dict[str, dict] = {}
    for pos in CORE_POSITIONS:
        values = sorted(
            float((t.get("positions") or {}).get(pos, {}).get("value") or 0.0)
            for t in teams
        )
        mid = len(values) // 2
        median = (values[mid] if len(values) % 2
                  else (values[mid - 1] + values[mid]) / 2.0)
        median = round(median, 1)
        out[pos] = {"value": median, "value_label": _aggregate_pick_label(median)}
    return out


@app.route("/api/league/power-rankings")
def league_power_rankings_route():
    """GET /api/league/power-rankings?league_id=...&basis=consensus|personal|redraft

    Ranks every team in the league by summed roster value; each team carries
    its full roster (grouped by position, value-desc within group — #144) so
    the client's team drill-in needs no second call.

    basis:
      - consensus (default): universal-pool consensus values (elo_to_value
        over the pool seed) — the same numbers /api/trade/values serves.
        League-shared aggregate, open like /api/league/coverage.
      - personal: the CALLER's live board for the active format (their Elo
        starts at the consensus seed and diverges as they rank), consensus
        fallback for players outside their board. Board-derived content →
        the P2.5 read gate applies inline (mirrors /api/trade/evaluate
        Mode B; the route can't take @_gate_unverified_read wholesale
        because the consensus basis is league-shared by design).
      - redraft: 501 not_available — FTF's value source (DynastyProcess) is
        dynasty-only today. The parameter shape is reserved so clients can
        probe; UI shows a disabled "(soon)" chip.

    ESPN-imported leagues work unchanged: their members sit in league_members
    with synthetic `espn:` user ids but Sleeper player ids (crosswalked at
    import), so value resolution is identical.
    """
    from .power_rankings import compute_power_rankings

    sess = _require_initialized_session()
    sess["last_active"] = time.time()
    g_user_id = sess["user_id"]
    g_league  = sess.get("league")
    league_id = request.args.get("league_id") or (g_league.league_id if g_league else "")
    if not league_id:
        return jsonify({"error": "league_id is required"}), 400

    basis = (request.args.get("basis") or "consensus").strip().lower()
    if basis == "redraft":
        return jsonify({
            "error":   "not_available",
            "message": ("Redraft rankings aren't available yet — FTF values "
                        "are dynasty-only. Use basis=consensus or "
                        "basis=personal."),
        }), 501
    if basis not in ("consensus", "personal"):
        return jsonify({"error": "basis must be one of consensus, personal, redraft"}), 400

    board_elo = None
    if basis == "personal":
        denial = _verified_read_denial(sess)
        if denial is not None:
            return denial
        service = sess["service"]
        board_elo = {
            rp.player.id: rp.elo
            for rp in service.get_rankings(position=None).rankings
        }

    try:
        members, seed, players_meta, fmt = _power_ranking_inputs(sess, league_id)
        if members is None:
            return jsonify({"error": "league_not_found"}), 404

        picks_by_owner = _power_picks_by_owner(league_id, fmt)
        teams = compute_power_rankings(
            members, seed, players_meta, board_elo=board_elo,
            picks_by_owner=picks_by_owner,
            lineup_slots=_sleeper_lineup_slots(league_id),
            # #277/#278 — additive `tier` per roster row (canonical
            # band-walk over the raw board/seed Elo; never from `value`).
            tier_fn=(lambda elo, pos:
                     RankingService.tier_for_elo(elo, pos, fmt)))
        # `is_you` compares LEAGUE identities: `teams` is built from
        # league_members, whose rows are keyed on each roster's owner_id. A
        # co-owner's account id appears on no row, so comparing the account
        # id here left every team `is_you: false` — no "You" badge, no rank
        # chip, and LeagueSummary's offer strip disabled for the whole league.
        _me = _league_user_id(sess)
        for t in teams:
            t["is_you"] = (t["user_id"] == _me)
        # #279 — aggregate_tier_labels experiment (operator-only rollout;
        # docs/feedback/items/279-aggregate-tier-labels/status.md, mirrors
        # the onboarding_v2_rollout precedent: an account-unit experiment
        # targeted via `is_tester_allowlist`, weighted 0/10000 so a captured
        # unit is always `treatment`). Only the RESOLVING caller's own
        # assignment matters here — this is per-request labeling of a
        # league-shared aggregate, not a per-league toggle. When targeted,
        # each team additionally carries `total_value_label` and a
        # `value_label` per core position (the SAME value→pick-equivalent
        # formula already live as "a Late 2nd" on trade cards, applied to a
        # raw aggregate instead of a gap — see _aggregate_pick_label).
        # Non-targeted callers (everyone but the allowlisted operator today)
        # get no new keys at all — byte-identical to pre-#279.
        #
        # #285 (docs/feedback/items/285-pick-sums/status.md) — the operator's
        # bug against this same experiment: `total_value_label` now folds in
        # each team's owned picks via a literal count (1st = 1.0 firsts,
        # 2nd = 1/3.5 firsts, 3rd+ = 0), NOT their dollar-priced pool_value.
        # The base is `positions_value` (players only), never `total_value`
        # (which already includes picks' dollar value) — adding the literal
        # count on top of that would double-count draft capital. `total_value`
        # itself is UNCHANGED: it drives `teams.sort` inside
        # compute_power_rankings (rank order), the drill-in's raw-number
        # fallback, and every non-experiment consumer, so touching it would
        # both leak the experiment to non-treatment callers and reshuffle
        # rank for the treatment caller too. Positional `value_label`s stay
        # position-scoped and never receive a pick contribution — picks
        # aren't tied to a position.
        from . import experiments as _experiments_mod
        if _experiments_mod.variant_for(g_user_id, "aggregate_tier_labels") == "treatment":
            for t in teams:
                pick_firsts = _pick_firsts_equivalent(
                    picks_by_owner.get(t["user_id"]) or [])
                t["total_value_label"] = _aggregate_pick_label(
                    t["positions_value"], pick_firsts)
                for _pv in t["positions"].values():
                    _pv["value_label"] = _aggregate_pick_label(_pv["value"])
        # League Analyzer replication (2026-07-26): per-team `starters` is
        # the DERIVED value-optimal lineup (optimal_starters over the
        # league's slot template — no per-week lineup data). The client's
        # All/Starters/Bench filter is offered only when every team carries
        # the split and at least one is non-empty — a missing slot template
        # (non-Sleeper platform, meta flake) hides the control (honest
        # degradation, never fabricated).
        starters_available = (
            bool(teams)
            and all(isinstance(t.get("starters"), list) for t in teams)
            and any(t["starters"] for t in teams)
        )
        return jsonify({
            "league_id":          league_id,
            "basis":              basis,
            "scoring_format":     fmt,
            "updated_at":         datetime.now(timezone.utc).isoformat(),
            "starters_available": starters_available,
            # #300 — league median per core position + its pick-equivalent
            # label, for the single-position median divider. Served
            # UNFLAGGED alongside `league.pos_candidates` (which gates the
            # client's divider): the field is additive — it changes no
            # existing key — and costs one sort per core position, so a
            # flag-on/field-absent state would only give the client a worse
            # contract to reason about. Basis-aware for free: the medians
            # are computed over the same `teams` this request priced, so a
            # personal-basis read gets personal-basis medians. All subset
            # only — see _position_medians.
            "medians":            _position_medians(teams),
            "teams":              teams,
        })
    except Exception as e:
        log.error("league/power-rankings error: %s", e)
        return jsonify({"error": "internal_error"}), 500


# #14/#21 rank chips — per-league consensus-rank cache so a fan of home
# league cards costs one power-rankings computation per league per minute,
# not one per card render. In-process only (fine across Render restarts —
# it just recomputes).
_RANK_CHIP_TTL_S = 60.0
_rank_chip_cache: dict[str, tuple[float, dict]] = {}


@app.route("/api/league/rank-chip")
def league_rank_chip_route():
    """GET /api/league/rank-chip?league_id=... → the SESSION user's consensus
    power rank in that league (#14/#21 home-card chips):
      {rank, team_count, basis: "consensus", updated_at}

    Slim companion to /api/league/power-rankings. Consensus basis only — the
    payload is derived from league-shared consensus values and exposes no
    board content, so like /api/league/summary this is a deliberately open
    read (no P2.5 gate; see docs/api-reference.md "deliberately left open").
    Cached per league_id for ~60s; the cached entry stores every member's
    rank, so leaguemates hitting the same league share one computation.
    """
    sess = _require_initialized_session()
    sess["last_active"] = time.time()
    g_league  = sess.get("league")
    league_id = request.args.get("league_id") or (g_league.league_id if g_league else "")
    if not league_id:
        return jsonify({"error": "league_id is required"}), 400

    from .power_rankings import compute_power_rankings
    try:
        cached = _rank_chip_cache.get(league_id)
        if cached is not None and (time.monotonic() - cached[0]) < _RANK_CHIP_TTL_S:
            entry = cached[1]
        else:
            members, seed, players_meta, fmt = _power_ranking_inputs(sess, league_id)
            if members is None:
                return jsonify({"error": "league_not_found"}), 404
            teams = compute_power_rankings(
                members, seed, players_meta,
                picks_by_owner=_power_picks_by_owner(league_id, fmt))
            entry = {
                "ranks":      {t["user_id"]: t["rank"] for t in teams},
                "team_count": len(teams),
                "updated_at": datetime.now(timezone.utc).isoformat(),
            }
            _rank_chip_cache[league_id] = (time.monotonic(), entry)

        # League identity, not account: `ranks` is keyed by league_members
        # user_id (each roster's owner_id), so a co-owner looked up by their
        # own id fell through to not_in_league and the home card lost its
        # rank chip. The cache entry stays keyed by league_id — every member
        # still shares one computation.
        rank = entry["ranks"].get(_league_user_id(sess))
        if rank is None:
            return jsonify({"error": "not_in_league"}), 404
        return jsonify({
            "rank":       rank,
            "team_count": entry["team_count"],
            "basis":      "consensus",
            "updated_at": entry["updated_at"],
        })
    except Exception as e:
        log.error("league/rank-chip error: %s", e)
        return jsonify({"error": "internal_error"}), 500


# ---------------------------------------------------------------------------
# Market movers (#243 — League-home "Market pulse" strip, approved mock
# risers-fallers-cards.html frame D1). Top risers/fallers by trailing-window
# % change of FTF community value — player_value_history consensus_value
# snapshots (daily cron #57), joined latest-vs-oldest-in-window via
# database.load_value_movers_window. Flag `market.movers` — 404 while off.
# Deliberately open read: universal-pool consensus data only, no user/board/
# league content (same class as /api/tier-config).
# ---------------------------------------------------------------------------

# Junk-filler floor: % change on a tiny baseline is noise ("+60%" on a
# 50-point stash). A player must have been worth at least this much at the
# baseline snapshot to qualify as a mover.
_MOVERS_MIN_BASE_VALUE = 100.0
_MOVERS_MAX_N = 10


@app.route("/api/market/movers")
def market_movers_route():
    """GET /api/market/movers?scoring_format=1qb_ppr&window_days=30&top_n=10

    → {risers: [{player_id, name, position, team, pct_30d, value_now}…],
       fallers: […], as_of, window_days, source: "ftf_community_value"}

    Risers sorted by pct_30d desc, fallers most-negative first; ≤ top_n
    (hard cap 10) each. `pct_30d` is named for the default window — it
    reflects whatever `window_days` was requested (echoed in the payload).
    Empty-safe when history is thin: fewer than two accrued snapshot days
    returns 200 with empty lists, never an error.
    """
    if not is_enabled("market.movers"):
        return jsonify({"error": "not_found"}), 404

    fmt = request.args.get("scoring_format") or DEFAULT_SCORING
    if fmt not in SCORING_FORMATS:
        fmt = DEFAULT_SCORING
    try:
        window_days = max(1, int(request.args.get("window_days", 30)))
    except ValueError:
        window_days = 30
    try:
        top_n = int(request.args.get("top_n", _MOVERS_MAX_N))
    except ValueError:
        top_n = _MOVERS_MAX_N
    top_n = max(1, min(top_n, _MOVERS_MAX_N))

    from .database import load_value_movers_window
    from .trade_service import is_pick_asset
    try:
        as_of, now_vals, then_vals = load_value_movers_window(fmt, days=window_days)
    except Exception as e:
        log.error("market/movers read failed: %s", e)
        return jsonify({"error": "internal_error"}), 500

    payload = {"risers": [], "fallers": [], "as_of": as_of,
               "window_days": window_days, "source": "ftf_community_value"}
    if not as_of or not then_vals:
        return jsonify(payload)                        # thin history — empty-safe

    players, _seed = _get_universal_pool(fmt)
    meta = {p.id: p for p in players}
    movers: list[dict] = []
    for pid, then_v in then_vals.items():
        now_v = now_vals.get(pid)
        p = meta.get(pid)
        if now_v is None or p is None:                 # dropped from today's
            continue                                   # snapshot / not in pool
        if is_pick_asset(p):
            continue                                   # #261 — picks are never movers
        if not then_v or then_v < _MOVERS_MIN_BASE_VALUE:
            continue                                   # junk-value baseline
        pct = (now_v - then_v) / then_v * 100.0
        if pct == 0:
            continue
        movers.append({
            "player_id": pid,
            "name":      p.name,
            "position":  p.position,
            "team":      getattr(p, "team", None),
            "pct_30d":   round(pct, 1),
            "value_now": round(now_v, 1),
        })
    movers.sort(key=lambda m: m["pct_30d"], reverse=True)
    payload["risers"] = [m for m in movers if m["pct_30d"] > 0][:top_n]
    fallers = sorted((m for m in movers if m["pct_30d"] < 0),
                     key=lambda m: m["pct_30d"])
    payload["fallers"] = fallers[:top_n]
    return jsonify(payload)


# ---------------------------------------------------------------------------
# League "outlook odds" (#169) — playoff/championship odds. Componentized
# pipeline in backend/outlook/. Dark behind the `outlook.odds` flag (404 off).
# ---------------------------------------------------------------------------

# ── Sleeper fan-out cache for the outlook route ─────────────────────────────
# Phase 1 (backend/outlook/league_state.py) walks EVERY regular-season week and
# calls `league/{id}/matchups/{week}` for each one — up to 14 upstream calls per
# request, the worst uncached surface in the app (docs/integrations/sleeper.md
# §5.4). This cache sits in the `fetch=` seam the provider already injects, so
# backend/outlook/ is untouched and every MISS still goes through `_sleeper_get`
# — the instrumented egress chokepoint (`_api_obs.observe_call`, endpoint class
# `league.matchups`). A cache hit therefore shows up in apihealth as the ABSENCE
# of an api_call event, which is exactly the signal we want.
#
# Tiering follows the grain of the data, keyed (league_id, season, week):
#   • week  < scored high-water  → SETTLED. A later week has already scored, so
#     this week's rows can never change again → cached with NO TTL.
#   • week == scored high-water (or week 1 preseason) → the current/in-progress
#     week; scores move during it → short TTL (15 min).
#   • week  > that → future weeks; the rows are pairings only (schedule data,
#     mutable in principle via a commissioner edit, but slow) → 1 h TTL.
# Steady state per league: one short-TTL call for the live week, a handful of
# hourly schedule calls, and exactly ONE upstream call for each new week that
# completes — permanently free thereafter.
#
# Idiom: the per-key `(timestamp, value)` dict of `_SUGGESTED_ORDER_CACHE` /
# `_FA_LEAGUE_META_CACHE`, not the single-object refresh of espn_service's
# `_xwalk_cache` (that one caches ONE global blob; this is per league+week).
# In-process, like every other cache here — completed-week rows are cheaply
# re-derivable from Sleeper, so a DB table would buy durability across restarts
# at the cost of schema + a data-dictionary entry the payload doesn't need.
# Bounded by entry count (matchup rows carry per-player point maps).
_OUTLOOK_WEEK_TTL_SECONDS     = 900.0    # current/in-progress week
_OUTLOOK_SCHEDULE_TTL_SECONDS = 3600.0   # unplayed future weeks (pairings only)
_OUTLOOK_WEEK_CACHE_MAX       = 250      # (league, season, week) entries per tier

_OUTLOOK_WEEK_SETTLED: dict[tuple[str, str, int], list] = {}
_OUTLOOK_WEEK_LIVE: dict[tuple[str, str, int], tuple[float, list]] = {}
_OUTLOOK_WEEK_HIGHWATER: dict[tuple[str, str], int] = {}
_OUTLOOK_SEASON_BY_LEAGUE: dict[str, str] = {}
_outlook_cache_lock = threading.Lock()
# Hit/miss counters — asserted by tests, handy in a debug read.
_OUTLOOK_CACHE_STATS = {"settled_hits": 0, "live_hits": 0, "upstream": 0}

_OUTLOOK_MATCHUPS_RE = re.compile(r"/league/([^/?]+)/matchups/(\d+)/?$")
_OUTLOOK_LEAGUE_META_RE = re.compile(r"/league/([^/?]+)/?$")


def _outlook_cache_clear() -> None:
    """Drop every outlook fan-out cache entry (tests, league re-sync)."""
    with _outlook_cache_lock:
        _OUTLOOK_WEEK_SETTLED.clear()
        _OUTLOOK_WEEK_LIVE.clear()
        _OUTLOOK_WEEK_HIGHWATER.clear()
        _OUTLOOK_SEASON_BY_LEAGUE.clear()
        for k in _OUTLOOK_CACHE_STATS:
            _OUTLOOK_CACHE_STATS[k] = 0


def _outlook_evict(store: dict) -> None:
    """Bound a tier by entry count, oldest-inserted first (caller holds lock)."""
    while len(store) > _OUTLOOK_WEEK_CACHE_MAX:
        store.pop(next(iter(store)), None)


def _outlook_week_is_settled(key: tuple[str, str, int]) -> bool:
    """True when a LATER week has already scored ⇒ this week is immutable.
    Never settled without a season in the key — a seasonless key could collide
    across years. (Caller holds the lock.)"""
    league_id, season, week = key
    if not season:
        return False
    return week < _OUTLOOK_WEEK_HIGHWATER.get((league_id, season), 0)


def _outlook_store_week(key: tuple[str, str, int], rows: list) -> None:
    """File a freshly-fetched week into the right tier and promote any weeks
    the new high-water mark just settled. (Takes the lock.)"""
    league_id, season, week = key
    scored = any(
        float(r.get("points") or 0.0)
        for r in rows if isinstance(r, dict)
    )
    with _outlook_cache_lock:
        lk = (league_id, season)
        if scored and week > _OUTLOOK_WEEK_HIGHWATER.get(lk, 0):
            _OUTLOOK_WEEK_HIGHWATER[lk] = week
        _OUTLOOK_WEEK_LIVE[key] = (time.time(), rows)
        # Any cached week now below the high-water mark is settled for good.
        for k in [k for k in _OUTLOOK_WEEK_LIVE if k[0] == league_id
                  and k[1] == season and _outlook_week_is_settled(k)]:
            _OUTLOOK_WEEK_SETTLED[k] = _OUTLOOK_WEEK_LIVE.pop(k)[1]
        _outlook_evict(_OUTLOOK_WEEK_SETTLED)
        _outlook_evict(_OUTLOOK_WEEK_LIVE)


def _outlook_week_ttl(key: tuple[str, str, int]) -> float:
    """TTL for a non-settled week: short for the live week, longer for the
    not-yet-played remainder (pairings only). (Caller holds the lock.)"""
    league_id, season, week = key
    live_week = max(_OUTLOOK_WEEK_HIGHWATER.get((league_id, season), 0), 1)
    return (_OUTLOOK_WEEK_TTL_SECONDS if week <= live_week
            else _OUTLOOK_SCHEDULE_TTL_SECONDS)


def _outlook_sleeper_fetch(captured: dict | None = None):
    """Return a `fetch(url)` for `build_league_state` that caches the weekly
    matchups fan-out and passes everything else straight to `_sleeper_get`.

    The league/rosters/users reads stay live on purpose: rosters carry the W/L/
    points-for standings the odds are computed FROM, and stale standings would
    be a wrong answer, not a slow one. Only the immutable-by-nature weekly
    scores are cached.

    `captured`, if given, is filled in-place with raw league-meta facts this
    closure happens to see but `LeagueState` (backend/outlook/league_state.py)
    doesn't carry a field for — currently just `playoff_seed_type` (BUG-3,
    docs/feedback/items/169-outlook-league-summary/calibration-report-2026-08-09.md
    §7). This is the ONE place the injected Phase-1 fetch touches the raw
    `/league/{id}` settings blob, so it's also the only place that can observe
    that field without a second network call or editing league_state.py.
    """
    def fetch(url: str):
        m = _OUTLOOK_MATCHUPS_RE.search(url)
        if not m:
            data = _sleeper_get(url)
            # Learn the season from the league-meta read (fetched first by the
            # provider) so week keys are season-scoped.
            meta_m = _OUTLOOK_LEAGUE_META_RE.search(url)
            if meta_m and isinstance(data, dict):
                if data.get("season"):
                    with _outlook_cache_lock:
                        _OUTLOOK_SEASON_BY_LEAGUE[meta_m.group(1)] = str(data["season"])
                if captured is not None:
                    captured["playoff_seed_type"] = (data.get("settings") or {}).get(
                        "playoff_seed_type")
            return data

        league_id, week = m.group(1), int(m.group(2))
        with _outlook_cache_lock:
            season = _OUTLOOK_SEASON_BY_LEAGUE.get(league_id, "")
            key = (league_id, season, week)
            rows = _OUTLOOK_WEEK_SETTLED.get(key)
            if rows is not None:
                _OUTLOOK_CACHE_STATS["settled_hits"] += 1
                return rows
            hit = _OUTLOOK_WEEK_LIVE.get(key)
            if hit is not None and (time.time() - hit[0]) < _outlook_week_ttl(key):
                _OUTLOOK_CACHE_STATS["live_hits"] += 1
                return hit[1]

        rows = _sleeper_get(url)          # MISS → instrumented upstream call
        with _outlook_cache_lock:
            _OUTLOOK_CACHE_STATS["upstream"] += 1
        if isinstance(rows, list):
            _outlook_store_week(key, rows)
        return rows

    return fetch


@app.route("/api/league/outlook")
def league_outlook_route():
    """GET /api/league/outlook?league_id=...&basis=consensus|personal

    Monte-Carlo playoff/championship odds for every team in the league. The
    pipeline (backend/outlook/) ingests schedule + standings (Phase 1),
    estimates each team's weekly-scoring model (Phase 2 — config-selected
    StrengthProvider), simulates the remaining season (Phase 3, seeded), seeds
    the bracket (Phase 4), and serializes (Phase 5).

    `basis` chooses the value basis for the preseason roster-value strength
    source: consensus (default, league-shared) or personal (the caller's
    board, P2.5 read-gated). basis=redraft → 501 (no redraft value source).

    Dark by default: 404 while the `outlook.odds` flag is off. Preseason
    payloads (completed_weeks==0) carry meta.is_preseason=true. meta.beta is a
    SEPARATE model-confidence signal (weeks 0-5, independent of is_preseason —
    see backend/outlook/serialize.py).

    Phase 1's weekly fan-out goes through `_outlook_sleeper_fetch()` (see
    above): completed weeks are cached with no TTL, the live week for 15 min,
    unplayed weeks for an hour. Misses still route through `_sleeper_get`, so
    the cache's effect is visible in apihealth as fewer `league.matchups`
    api_call events.
    """
    if not is_enabled("outlook.odds"):
        return jsonify({"error": "not_found"}), 404

    sess = _require_initialized_session()
    sess["last_active"] = time.time()
    g_user_id = sess["user_id"]
    g_league  = sess.get("league")
    league_id = request.args.get("league_id") or (g_league.league_id if g_league else "")
    if not league_id:
        return jsonify({"error": "league_id is required"}), 400

    basis = (request.args.get("basis") or "consensus").strip().lower()
    if basis == "redraft":
        return jsonify({
            "error":   "not_available",
            "message": ("Redraft outlook isn't available — FTF values are "
                        "dynasty-only. Use basis=consensus or basis=personal."),
        }), 501
    if basis not in ("consensus", "personal"):
        return jsonify({"error": "basis must be one of consensus, personal, redraft"}), 400

    board_elo = None
    if basis == "personal":
        denial = _verified_read_denial(sess)
        if denial is not None:
            return denial
        service = sess["service"]
        board_elo = {
            rp.player.id: rp.elo
            for rp in service.get_rankings(position=None).rankings
        }

    fmt = _active_format(sess)
    # Platform must be resolved from the REQUESTED league_id, not from the
    # session's currently-attached league — those disagree for multi-league
    # users. `league_id` above may already differ from g_league.league_id
    # (explicit query param), so g_league.platform is the wrong source here
    # (it produced a spurious 501 for an ESPN-session user requesting a
    # Sleeper league, or a misleading 404 the other way around). Follow the
    # same DB-lookup convention as the pick-assignments seeder and the
    # draft-status stamp (both key off get_league_draft_context(league_id)).
    platform = (get_league_draft_context(league_id) or {}).get("platform") or "sleeper"
    try:
        from . import outlook as outlook_pkg
        _outlook_captured: dict = {}
        state = outlook_pkg.build_league_state(
            league_id, platform=platform,
            fetch=_outlook_sleeper_fetch(_outlook_captured))
        if not state.teams:
            return jsonify({"error": "league_not_found"}), 404

        # Resolve per-player value (same basis machinery as power-rankings) and
        # position, for the roster-value strength source.
        pool_players, seed = _get_universal_pool(fmt)
        svc_seed = getattr(sess.get("service"), "_seed", None) or {}
        if svc_seed:
            seed = {**svc_seed, **seed}
        players_meta = {p.id: p for p in pool_players}
        for p in (sess.get("players") or []):
            players_meta.setdefault(p.id, p)
        e2v = _trade_service_mod.elo_to_value

        def _value_of(pid: str) -> float:
            if board_elo is not None and pid in board_elo:
                return e2v(board_elo[pid])
            if pid in seed:
                return e2v(seed[pid])
            return 0.0

        player_value: dict[str, float] = {}
        player_pos: dict[str, str] = {}
        for t in state.teams:
            for raw_pid in t.player_ids:
                pid = str(raw_pid)
                if pid in player_value:
                    continue
                player_value[pid] = round(_value_of(pid), 1)
                p = players_meta.get(pid)
                player_pos[pid] = getattr(p, "position", None) or "?"

        payload = outlook_pkg.run_outlook(
            state,
            player_value=player_value,
            player_pos=player_pos,
            model_cfg=get_config(),
            basis=basis,
            scoring_format=fmt,
            you_user_id=g_user_id,
            playoff_seed_type=_outlook_captured.get("playoff_seed_type"),
        )
        return jsonify(payload)
    except NotImplementedError as e:
        return jsonify({"error": "not_supported", "message": str(e)}), 501
    except Exception as e:
        log.error("league/outlook error: %s", e)
        return jsonify({"error": "internal_error"}), 500


# ---------------------------------------------------------------------------
# Free-agent finder (feedback #143) — logic in backend/free_agent_service.py
# ---------------------------------------------------------------------------

# #179 — Sleeper league-meta cache for the free-agents roster-capacity block.
# Meta (roster_positions + settings) is effectively static per league; a
# small TTL keeps the FA route at one live Sleeper call per request (the
# rosters read) instead of two.
_FA_LEAGUE_META_CACHE: dict[str, tuple[float, dict]] = {}
_FA_LEAGUE_META_TTL = 900.0  # 15 min


def _fa_league_meta(league_id: str) -> dict:
    """Cached Sleeper league meta for the FA route (roster limit + waiver
    settings share one fetch — the claim-sheet upgrade added no extra
    Sleeper call). Empty dict when the meta can't be fetched."""
    now = time.time()
    hit = _FA_LEAGUE_META_CACHE.get(league_id)
    if hit is not None and (now - hit[0]) < _FA_LEAGUE_META_TTL:
        return hit[1]
    meta = _fetch_sleeper_league_meta(league_id) or {}
    _FA_LEAGUE_META_CACHE[league_id] = (now, meta)
    return meta


def _sleeper_roster_limit(league_id: str) -> int | None:
    """Total roster capacity for a Sleeper league: lineup+bench slots
    (roster_positions) plus IR (reserve_slots) and taxi (taxi_slots) —
    the same headcount Sleeper's `players` list can grow to. None when the
    meta can't be fetched or has no roster_positions."""
    meta = _fa_league_meta(league_id)
    slots = len(meta.get("roster_positions") or [])
    if not slots:
        return None
    settings = meta.get("settings") or {}
    try:
        return (slots + int(settings.get("reserve_slots") or 0)
                      + int(settings.get("taxi_slots") or 0))
    except (TypeError, ValueError):
        return slots


# Sleeper settings.waiver_type → wire enum (docs/api-reference.md):
# 0 = rolling waiver priority, 1 = reverse-standings priority, 2 = FAAB.
_SLEEPER_WAIVER_TYPES = {0: "rolling", 1: "reverse_standings", 2: "faab"}


def _sleeper_waivers(league_id: str, my_budget_used) -> dict:
    """#179 claim sheet — the league's waiver context. `type` is the wire
    enum above (None when the meta is missing/unrecognized). `faab` is the
    caller's budget line for FAAB leagues (budget from league settings,
    used from their live roster's settings.waiver_budget_used — passed in
    by the route, which already reads the rosters); None for priority-
    waiver leagues, so the client can say "waiver priority league" instead
    of showing a bid input. All faab fields nullable/best-effort."""
    settings = _fa_league_meta(league_id).get("settings") or {}
    wtype = _SLEEPER_WAIVER_TYPES.get(settings.get("waiver_type"))
    faab = None
    if wtype == "faab":
        try:
            budget = int(settings.get("waiver_budget"))
        except (TypeError, ValueError):
            budget = None
        try:
            used = int(my_budget_used) if my_budget_used is not None else None
        except (TypeError, ValueError):
            used = None
        remaining = (budget - used
                     if budget is not None and used is not None else None)
        faab = {"budget": budget, "used": used, "remaining": remaining}
    return {"type": wtype, "faab": faab}


@app.route("/api/league/free-agents")
@_gate_unverified_read
def league_free_agents_route():
    """GET /api/league/free-agents?league_id=...&position=RB

    Best available free agents in the league, ranked by the CALLER'S board
    value (personal Elo, consensus seed fallback for anything they haven't
    ranked). FA pool = active format's universal pool minus every rostered
    player in the league. The exclusion set unions every roster source the
    route can reach: session-league rosters (when league_id matches the
    session), the raw league_members snapshot (#151), and — for Sleeper
    leagues — a LIVE Sleeper rosters read (#178: the client-built snapshot
    drops ownerless rosters, so an orphaned team's players leaked into the
    list). An empty exclusion set is a hard 503 rosters_unavailable, never
    a full-pool listing. Each row may carry a drop_suggestion: the caller's
    lowest-valued same-position rostered player whose value is strictly
    below the FA's, with the add/drop delta.

    Query params:
      league_id  — optional, defaults to the session league.
      position   — optional QB|RB|WR|TE (or ALL/omitted for all positions).

    Response:
      {
        "league_id":         str,
        "scoring_format":    "1qb_ppr" | "sf_tep",
        "position":          "QB"|"RB"|"WR"|"TE"|"ALL",
        "user_has_rankings": bool,   # False = whole list is pure consensus
        "free_agents": [
          {"player_id", "name", "position", "team", "age",
           "value": float,          # caller-board dynasty value
           "tier": str|null,        # #277 — pick-value ladder tier from the
                                    # SAME raw board Elo `value` was priced
                                    # from (RankingService.tier_for_elo;
                                    # never derived from `value`)
           "pos_rank": int,         # 1-based rank within position among FAs
           "drop_suggestion": {"player_id", "name", "position",
                               "value", "delta", "tier"} | null}, ...
        ],  # top 50 after the position filter
        "roster_capacity": {"my_count": int|null, "limit": int|null,
                            "open_slots": int|null} | null
          # #179 — Sleeper leagues only; feeds the client's claim sheet
          # (limit = lineup+bench+IR+taxi slots from league meta;
          #  open_slots = max(limit - my_count, 0), null when either is).
        "waivers": {"type": "faab"|"rolling"|"reverse_standings"|null,
                    "faab": {"budget", "used", "remaining"} | null} | null
          # #179 claim sheet — Sleeper leagues only. faab is the CALLER'S
          # budget line (league waiver_budget / their roster's
          # waiver_budget_used) and is null for non-FAAB waiver types.
        "drop_candidates": {"players": [{"id","name","position","value",
                                         "tier"},...],
                            "untouchables_excluded": int} | null
          # #179 claim sheet — Sleeper leagues only. The caller's roster
          # priced on their board, value-ASCENDING (least valuable first),
          # capped at 8; untouchables (asset_prefs) never appear, and the
          # count tells the sheet they were withheld.
      }

    Errors: 503 rosters_unavailable when NO roster source yielded a single
    rostered player (unsynced snapshot + session mismatch + live read down).

    Read-gated (@_gate_unverified_read): the list is priced by the caller's
    board, so it's board-derived content like /api/rankings.
    """
    from .free_agent_service import (
        FA_POSITIONS, board_is_personalized, compute_drop_candidates,
        compute_free_agents,
    )
    sess = _require_initialized_session()
    sess["last_active"] = time.time()
    g_user_id = sess["user_id"]
    # Two identities, both needed here: the ACCOUNT id matches raw Sleeper
    # roster rows on the live read (owner or co-owner), the LEAGUE id matches
    # league_members rows (keyed on each roster's owner_id). They are the same
    # string for a sole owner. Mixing them up is what made a co-owner's
    # my_roster_count/my_roster_ids null and killed the #179 claim sheet.
    g_league_user_id = _league_user_id(sess)
    g_league  = sess.get("league")
    league_id = request.args.get("league_id") or (g_league.league_id if g_league else "")
    if not league_id:
        return jsonify({"error": "league_id is required"}), 400

    raw_pos  = (request.args.get("position") or "").strip().upper()
    position = None if raw_pos in ("", "ALL") else raw_pos
    if position is not None and position not in FA_POSITIONS:
        return jsonify({"error": f"Invalid position: {raw_pos!r}"}), 400

    fmt = _active_format(sess)
    try:
        pool_players, seed = _get_universal_pool(fmt)
        service  = sess["service"]
        user_elo = {rp.player.id: rp.elo
                    for rp in service.get_rankings(position=None).rankings}
        # #277 — additive `tier` per priced row, via the canonical band-walk
        # over the SAME raw board Elo the row's value came from.
        fa_tier_fn = (lambda elo, pos:
                      RankingService.tier_for_elo(elo, pos, fmt))

        # ── Roster exclusion set (#151 / #178) — sources, UNIONED: ─────────
        #  1. In-session league rosters when league_id matches the session
        #     (Sleeper / platform-imported / demo alike — session init
        #     builds all three). NOTE: these were filtered against the
        #     DEFAULT (1qb_ppr) pool at init, hence source 2.
        #  2. The league_members snapshot — RAW client-sent ids, unfiltered
        #     (#151: covers players that exist only in the active format's
        #     pool). Best-effort: a failed read leaves the other sources.
        #  3. Sleeper leagues only: the LIVE Sleeper rosters read (#178).
        #     Sources 1 and 2 both descend from the CLIENT-built session
        #     payload, and the clients drop rosters with no owner
        #     (owner_id=None after a manager leaves the league) — so an
        #     orphaned team's entire roster, stars included, surfaced as
        #     "free agents". The live read is roster-shaped, not owner-
        #     shaped: every rostered player counts, owned or not.
        # Platform-imported leagues (ESPN/MFL/Fleaflicker) need no live
        # read: their snapshot is written server-side at link/import time
        # from the platform's own team list (every team, no owner filter).
        if g_league and league_id == g_league.league_id:
            member_rosters = [list(m.roster or []) for m in g_league.members]
            user_roster    = list(sess.get("user_roster") or [])
        else:
            rows = load_league_members(league_id)
            member_rosters = [r.get("player_ids") or [] for r in rows
                              if r.get("user_id") != g_league_user_id]
            user_roster    = next((r.get("player_ids") or [] for r in rows
                                   if r.get("user_id") == g_league_user_id), [])
        rostered = {str(pid) for roster in member_rosters for pid in roster}

        my_roster_count: int | None = None
        # #179 claim sheet — the caller's own roster ids, best source wins:
        # live Sleeper read > snapshot row > session roster (same precedence
        # my_roster_count already follows). Feeds drop_candidates.
        my_roster_ids: list[str] | None = None
        # The caller's FAAB spend, from their live Sleeper roster's settings.
        my_waiver_used = None
        try:
            for r in load_league_members(league_id):
                ids = [str(pid) for pid in (r.get("player_ids") or [])]
                rostered.update(ids)
                if r.get("user_id") == g_league_user_id and ids:
                    my_roster_count = len(ids)
                    my_roster_ids   = ids
        except Exception as e:
            log.warning("free-agents: league_members snapshot read failed "
                        "for %s (continuing on session rosters): %s",
                        league_id, e)

        is_sleeper_league = False
        try:
            is_sleeper_league = (league_id.isdigit()
                                 and not is_linked_platform_league(league_id))
        except Exception as e:
            log.warning("free-agents: platform lookup failed for %s: %s",
                        league_id, e)
            is_sleeper_league = league_id.isdigit()
        if is_sleeper_league:
            try:
                live = _sleeper_get(
                    f"https://api.sleeper.app/v1/league/{league_id}/rosters"
                ) or []
                from .sleeper_roster import owns_roster as _owns
                for r in live:
                    ids = [str(pid) for pid in (r.get("players") or [])]
                    rostered.update(ids)
                    # Owner OR co-owner — this is a LIVE roster read, so the
                    # match is against the raw Sleeper row, not a
                    # league_members key.
                    if _owns(r, g_user_id):
                        my_roster_count = len(ids)
                        my_roster_ids   = ids
                        my_waiver_used  = (r.get("settings") or {}).get(
                            "waiver_budget_used")
            except Exception as e:
                log.warning("free-agents: live Sleeper rosters read failed "
                            "for %s (serving snapshot-derived exclusion): %s",
                            league_id, e)

        # #178 — fail LOUD on an empty exclusion set. Every league this
        # route serves has rostered players; an empty union means every
        # roster source failed (unsynced snapshot + no session league +
        # platform fetch down), and serving would list the entire universal
        # pool — rostered stars included — as "free agents". Wrong data
        # silently is worse than no data.
        if not rostered and not user_roster:
            log.error("free-agents: EMPTY roster exclusion for league %s "
                      "(session league=%r) — refusing to serve",
                      league_id, g_league.league_id if g_league else None)
            return jsonify({
                "error":   "rosters_unavailable",
                "message": ("Couldn't load this league's rosters, so the "
                            "free-agent list can't be built right now — "
                            "try again shortly."),
            }), 503

        # #179 — claim-sheet context (Sleeper leagues only; every field
        # best-effort/nullable): roster capacity + open slots, waiver
        # type/FAAB budget, and the value-ascending drop-candidate list.
        roster_capacity = None
        waivers         = None
        drop_candidates = None
        if is_sleeper_league:
            if my_roster_count is None and user_roster:
                my_roster_count = len(user_roster)
            limit = _sleeper_roster_limit(league_id)
            roster_capacity = {
                "my_count":   my_roster_count,
                "limit":      limit,
                "open_slots": (max(limit - my_roster_count, 0)
                               if limit is not None
                               and my_roster_count is not None else None),
            }
            waivers = _sleeper_waivers(league_id, my_waiver_used)
            untouchable_ids: set = set()
            try:
                ap = load_asset_preferences(user_id=g_user_id,
                                            league_id=league_id)
                untouchable_ids = {str(x) for x in ap.get("untouchables", [])}
            except Exception as ap_err:
                log.warning("free-agents: asset-prefs read failed for %s "
                            "(drop candidates unfiltered): %s",
                            league_id, ap_err)
            cand_rows, cand_excluded = compute_drop_candidates(
                pool_players = pool_players,
                seed_elo     = seed,
                user_elo     = user_elo,
                user_roster  = (my_roster_ids if my_roster_ids is not None
                                else user_roster),
                exclude_ids  = untouchable_ids,
                tier_fn      = fa_tier_fn,
            )
            drop_candidates = {
                "players":                cand_rows,
                "untouchables_excluded":  cand_excluded,
            }

        free_agents = compute_free_agents(
            pool_players = pool_players,
            seed_elo     = seed,
            user_elo     = user_elo,
            rostered_ids = rostered,
            user_roster  = user_roster,
            position     = position,
            tier_fn      = fa_tier_fn,
        )
        return jsonify({
            "league_id":         league_id,
            "scoring_format":    fmt,
            "position":          position or "ALL",
            "user_has_rankings": board_is_personalized(user_elo, seed),
            "free_agents":       free_agents,
            # #179 — claim-sheet context, Sleeper leagues only (fields
            # nullable when unknown); all three null for platform/demo
            # leagues. See docstring for shapes.
            "roster_capacity":   roster_capacity,
            "waivers":           waivers,
            "drop_candidates":   drop_candidates,
        })
    except Exception as e:
        log.error("league/free-agents error: %s", e)
        return jsonify({"error": "internal_error"}), 500


# ─── Monetization platform foundation ──────────────────────────────────────
# docs/plans/monetization/00-platform-foundation.md §2.3 + §3 + §4.
#
# All routes here stay mounted regardless of flags:
#   * /api/me/entitlements serves resolved state even while dark so clients
#     can bootstrap before enforcement flips (response carries `enforcing`).
#   * /api/admin/entitlements/* is the operator manual-grant surface —
#     X-Cron-Secret guarded (same fail-closed rule as /api/cron/*), never
#     flag-gated; grants written while dark sit dormant.
#   * /api/billing/* webhooks must accept provider traffic from the moment
#     store products exist, which precedes any flag flip.
# Gate helper: wrap a route in @_require_pro to put it on the Pro gate
# list. With monetize.entitlements off it is a no-op; observe/enforce
# semantics live in entitlements.check_pro (foundation §2.4).

from . import entitlements as entl


def _require_pro(fn):
    """Pro gate decorator (grep-auditable: the gate list is every route
    wearing this). Never wrap the core loop (rank → trades in the synced
    league) — guardrail in foundation §2.2."""
    from functools import wraps

    @wraps(fn)
    def wrapper(*args, **kwargs):
        sess = _require_session()
        if not entl.check_pro(sess["user_id"], request.path, logger=log):
            return jsonify({"error": "pro_required"}), 402
        return fn(*args, **kwargs)
    return wrapper


@app.route("/api/me/entitlements", methods=["GET"])
def me_entitlements():
    """Client bootstrap: resolved entitlement state + enforcement posture.

    Session-authed. The Chrome extension does NOT call this — its `pro`
    bool rides in POST /api/extension/auth's payload (pro-subscription LLD;
    username-only auth can't carry a session token)."""
    sess = _require_session()
    out = entl.get_entitlements(sess["user_id"])
    out["enforcing"] = is_enabled("monetize.entitlements")
    return jsonify(out)


@app.route("/api/admin/entitlements/grant", methods=["POST"])
def admin_entitlements_grant():
    """Operator manual grant (foundation §3). Body:
    {user: <sleeper id|username|acct_*|account_id>, entitlement: 'pro',
     duration_days: N | expires_at: ISO | perpetual: true, note: str}."""
    _require_cron_auth()
    body = request.get_json(silent=True) or {}
    user_id, account_id = entl.resolve_user(str(body.get("user", "")))
    if user_id is None:
        return jsonify({"error": "user_not_found"}), 404
    entitlement = body.get("entitlement", "pro")
    try:
        row = entl.grant(
            user_id, entitlement,
            source="manual_grant",
            account_id=account_id,
            duration_days=body.get("duration_days"),
            expires_at=(None if body.get("perpetual") else body.get("expires_at")),
            granted_by="operator",
            note=body.get("note"),
        )
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    return jsonify(row), 201


@app.route("/api/admin/entitlements/bulk-grant", methods=["POST"])
def admin_entitlements_bulk_grant():
    """Same body as /grant but `users: [...]` — e.g. comp every TestFlight
    tester 90 days in one call. Partial success reported per-user."""
    _require_cron_auth()
    body = request.get_json(silent=True) or {}
    users = body.get("users") or []
    if not isinstance(users, list) or not users:
        return jsonify({"error": "users_list_required"}), 400
    granted, failed = [], []
    for ident in users:
        user_id, account_id = entl.resolve_user(str(ident))
        if user_id is None:
            failed.append({"user": ident, "error": "user_not_found"})
            continue
        try:
            row = entl.grant(
                user_id, body.get("entitlement", "pro"),
                source="manual_grant", account_id=account_id,
                duration_days=body.get("duration_days"),
                expires_at=(None if body.get("perpetual") else body.get("expires_at")),
                granted_by="operator", note=body.get("note"),
            )
            granted.append(row)
        except ValueError as e:
            failed.append({"user": ident, "error": str(e)})
    return jsonify({"granted": granted, "failed": failed}), 201


@app.route("/api/admin/entitlements/<int:entitlement_id>", methods=["DELETE"])
def admin_entitlements_revoke(entitlement_id: int):
    """Revoke (status flip, audit-preserving — never hard-deletes)."""
    _require_cron_auth()
    if not entl.revoke(entitlement_id):
        return jsonify({"error": "not_found"}), 404
    return jsonify({"revoked": entitlement_id})


@app.route("/api/admin/entitlements", methods=["GET"])
def admin_entitlements_list():
    """?user=<identifier> — all rows any status, for support."""
    _require_cron_auth()
    user_id, _ = entl.resolve_user(request.args.get("user", ""))
    if user_id is None:
        return jsonify({"error": "user_not_found"}), 404
    return jsonify({"user_id": user_id, "entitlements": entl.list_for_user(user_id)})


@app.route("/api/billing/revenuecat/webhook", methods=["POST"])
def billing_revenuecat_webhook():
    """RevenueCat → subscription_events ledger → projector.
    Auth: Authorization: Bearer <REVENUECAT_WEBHOOK_SECRET>. Fails closed
    in prod when the secret is unset (same posture as CRON_SECRET)."""
    secret = os.environ.get("REVENUECAT_WEBHOOK_SECRET", "")
    if _IS_PROD_ENV and not secret:
        return jsonify({"error": "webhook_secret_unset"}), 503
    if secret:
        sent = request.headers.get("Authorization", "")
        if not hmac.compare_digest(sent, f"Bearer {secret}"):
            return jsonify({"error": "unauthorized"}), 401
    body = request.get_json(silent=True) or {}
    event = body.get("event") or {}
    if not event.get("id"):
        return jsonify({"error": "malformed_event"}), 400
    result = entl.ingest_billing_event(
        "revenuecat", str(event["id"]), event.get("type", ""), event,
        user_id=event.get("app_user_id"),
        product_id=event.get("product_id"),
        occurred_at=entl._ms_to_iso(event.get("event_timestamp_ms")),
    )
    return jsonify(result), 200


@app.route("/api/billing/stripe/webhook", methods=["POST"])
def billing_stripe_webhook():
    """Stripe → same ledger/projector. Verifies the Stripe-Signature v1
    scheme (HMAC-SHA256 over '<t>.<raw body>') without the stripe lib.
    user_id/product_id ride in the object's metadata (set at Checkout
    creation) — events without them are stored + skipped, never dropped."""
    secret = os.environ.get("STRIPE_WEBHOOK_SECRET", "")
    if _IS_PROD_ENV and not secret:
        return jsonify({"error": "webhook_secret_unset"}), 503
    raw = request.get_data()
    if secret:
        sig_header = request.headers.get("Stripe-Signature", "")
        parts = dict(p.split("=", 1) for p in sig_header.split(",") if "=" in p)
        expected = hmac.new(secret.encode(),
                            f"{parts.get('t', '')}.".encode() + raw,
                            "sha256").hexdigest()
        if not hmac.compare_digest(parts.get("v1", ""), expected):
            return jsonify({"error": "unauthorized"}), 401
    body = json.loads(raw or b"{}")
    if not body.get("id"):
        return jsonify({"error": "malformed_event"}), 400
    obj = ((body.get("data") or {}).get("object") or {})
    meta = obj.get("metadata") or {}
    result = entl.ingest_billing_event(
        "stripe", str(body["id"]), body.get("type", ""), body,
        user_id=meta.get("user_id"),
        product_id=meta.get("product_id"),
    )
    return jsonify(result), 200


# ---------------------------------------------------------------------------
# MFL + Fleaflicker league linking — Phase 1 read-only import
# Flags: `mfl.link` / `fleaflicker.link` (default OFF — every route 404s dark)
# Plan: docs/plans/multi-platform-linking-plan-2026-07-17.md §8
#
# Same three-step contract as ESPN (/api/espn/*): POST .../link without a team
# key → preview (teams + crosswalk report, nothing persisted); with a team key
# → import (league persisted platform='mfl'|'fleaflicker', members as
# crosswalked SLEEPER player ids, the chosen team bound to the session user).
# GET .../leagues lists linked leagues + membership; POST .../import re-syncs.
# Counterparties get synthetic ids ('mfl:{L}.f{franchise}' /
# 'flea:{L}.t{team}') that never reach push/notification paths — same class as
# unlinked ESPN/Sleeper members. Owner emails/names are never harvested (MFL
# ToS). MFL futureDraftPicks are STORED raw (leagues.platform_future_picks)
# for the pick-inclusive follow-up but are NOT wired into the engine yet.
# ---------------------------------------------------------------------------

_MFL_DEFAULT_YEAR = 2026


def _shared_crosswalk():
    """The DP crosswalk (espn_service owns the cached fetch) — shared by every
    linked platform (ESPN/MFL/Fleaflicker) via its per-platform id maps."""
    from . import espn_service as _espn
    return _espn.get_crosswalk()


def _platform_report_json(report: dict) -> dict:
    """Client-facing crosswalk report (shared shape with _espn_report_json)."""
    return {
        "pool_players":    report["pool_players"],
        "matched_by_id":   report["matched_by_id"],
        "matched_by_name": report["matched_by_name"],
        "match_rate":      round(report["match_rate"], 4),
        "out_of_pool":     report["out_of_pool"],
        "unmatched":       [
            {"name": u["name"], "position": u["position"]}
            for u in report["unmatched"]
        ],
    }


def _platform_error_response(e, platform: str):
    """Map an MflError/FleaflickerError to a (json, status) response."""
    kind = getattr(e, "kind", "http")
    label = "MFL" if platform == "mfl" else "Fleaflicker"
    if kind == "auth":
        return jsonify({"error": f"{platform}_auth_required",
                        "message": f"{label} wouldn't share this league — it's "
                                   "private or the credentials expired."}), 403
    if kind == "not_found":
        return jsonify({"error": f"{platform}_league_not_found",
                        "message": f"{label} has no league with that ID."}), 404
    if kind == "input":
        return jsonify({"error": f"{platform}_bad_league_id",
                        "message": f"{label} league IDs are numeric."}), 400
    log.warning("%s fetch failed [%s]: %s", platform, kind, e)
    return jsonify({"error": f"{platform}_unavailable",
                    "message": f"Couldn't reach {label} — try again shortly."}), 502


# ── MFL ─────────────────────────────────────────────────────────────────────

def _mfl_member_id(league_id: str, franchise_id: str) -> str:
    return f"mfl:{league_id}.f{franchise_id}"


def _mfl_resolve(body: dict):
    """Parse the request into (league_id, year, host). Raises MflError."""
    from . import mfl_service as _mfl
    raw_input = str(body.get("mfl_league_url") or body.get("mfl_league_id") or "").strip()
    try:
        year = int(body.get("year") or _MFL_DEFAULT_YEAR)
    except (TypeError, ValueError):
        raise _mfl.MflError("year must be numeric", kind="input")
    league_id = _mfl.parse_league_id_from_url(raw_input) or (
        raw_input if raw_input.isdigit() else None)
    if not league_id:
        raise _mfl.MflError("could not parse an MFL league id", kind="input")
    host = _mfl.parse_host_from_url(raw_input) or _mfl.resolve_host(league_id, year)
    return league_id, year, host


def _mfl_store_scoring_format(league_id: str, raw: dict, where: str) -> str | None:
    """#201 — detect + persist the league's scoring format from an MFL bundle.

    Nothing ever wrote leagues.default_scoring for MFL leagues, so every
    consumer (get_league_scoring, /api/league/scoring-format, the trade
    engine's format lookup) fell to the '1qb_ppr' default — an SF TEP league
    rendered as 1QB. Detection rules live in mfl_service.detect_scoring_format
    (superflex = max startable QBs ≥ 2 from the league export's lineup config;
    TEP = TE per-reception points > WR's from the rules export; SF or TEP →
    'sf_tep', mirroring the Sleeper collapse convention). Best-effort: runs
    AFTER upsert_platform_league (set_league_scoring is an UPDATE on the
    existing row) and never fails the import. Returns the stored format, or
    None when detection/persistence failed."""
    from . import mfl_service as _mfl
    try:
        fmt = _mfl.detect_scoring_format(raw)
        set_league_scoring(league_id, fmt)
        log.info("%s: scoring format detected for league %s: %s",
                 where, league_id, fmt)
        return fmt
    except Exception as e:
        log.warning("%s: scoring-format detect failed for league %s "
                    "(stays default): %s", where, league_id, e)
        return None


# #201 — leagues whose missing-format backfill was already attempted this
# process (see mfl_leagues). Keeps the one-shot fetch from re-running on
# every league-list read when MFL is flaky.
_mfl_scoring_backfill_attempted: set = set()


@app.route("/api/mfl/link", methods=["POST"])
@_gate_unverified_write
def mfl_link():
    """Preview (no franchise_id) or import (franchise_id) an MFL league."""
    if not is_enabled("mfl.link"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import mfl_service as _mfl
    from .database import upsert_platform_league, replace_espn_league_members

    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    body = request.get_json(force=True) or {}
    try:
        league_id, year, host = _mfl_resolve(body)
        raw = _mfl.fetch_league_bundle(league_id, year, host)
    except _mfl.MflError as e:
        return _platform_error_response(e, "mfl")

    parsed = _mfl.parse_bundle(raw)
    mapped = _mfl.map_franchises(parsed, _shared_crosswalk())

    teams_json = [
        {"team_id": fr["franchise_id"], "name": fr["name"],
         "mapped_players": len(mapped["rosters"].get(fr["franchise_id"], []))}
        for fr in parsed["franchises"]
    ]

    franchise_id = body.get("franchise_id") or body.get("team_id")
    if franchise_id is None:
        return jsonify({
            "status": "choose_team",
            "league": {"mfl_league_id": parsed["league_id"] or league_id,
                       "name": parsed["name"], "season": year,
                       "total_teams": parsed["total_teams"], "host": host},
            "teams": teams_json,
            "report": _platform_report_json(mapped["report"]),
        })

    franchise_id = str(franchise_id)
    valid = {fr["franchise_id"] for fr in parsed["franchises"]}
    if franchise_id not in valid:
        return jsonify({"error": "mfl_bad_team_id",
                        "message": "That franchise isn't in this league."}), 400

    members = []
    for fr in parsed["franchises"]:
        fid = fr["franchise_id"]
        mid = user_id if fid == franchise_id else _mfl_member_id(league_id, fid)
        members.append({"user_id": mid, "username": fr["name"],
                        "display_name": fr["name"],
                        "player_ids": mapped["rosters"].get(fid, []),
                        "team_key": f"mfl:{league_id}.f{fid}"})   # ADR-011
    try:
        upsert_platform_league(
            league_id=league_id, user_id=user_id,
            name=parsed["name"] or f"MFL league {league_id}", platform="mfl",
            season=year, auth="public", my_team=franchise_id,
            total_rosters=parsed["total_teams"], host=host,
            future_picks=parsed["future_picks"])
        replace_espn_league_members(league_id, members)
    except Exception:
        log.exception("mfl_link: persistence failed")
        return jsonify({"error": "store_failed"}), 500

    # ADR-011 Writer A — after the membership transaction committed.
    _platform_roster_history_on_sync(
        league_id, "mfl", members,
        my_user_id=user_id, my_team_key=f"mfl:{league_id}.f{franchise_id}")

    # #158 — normalize MFL owned picks into draft_picks (same store Sleeper
    # writes). Best-effort, gated on picks.owned_sync; runs after members are
    # persisted so franchise→user name resolution has the member snapshot.
    if is_enabled("picks.owned_sync"):
        try:
            _npk = _sync_mfl_owned_picks(league_id)
            log.info("mfl_link: normalized %d owned picks", _npk)
        except Exception as _mpk_err:
            log.warning("mfl_link: owned-pick normalization failed (continuing): %s", _mpk_err)

    # #201 — detect + store the league's scoring format from the bundle.
    _mfl_store_scoring_format(league_id, raw, "mfl_link")

    r = mapped["report"]
    log.info("mfl_link: user=%s league=%s year=%s teams=%d match_rate=%.1f%% "
             "unmatched=%d picks=%d", user_id, league_id, year, len(members),
             r["match_rate"] * 100, len(r["unmatched"]), len(parsed["future_picks"]))
    return jsonify({
        "ok": True, "league_id": league_id, "name": parsed["name"],
        "platform": "mfl", "season": year, "auth": "public",
        "total_teams": parsed["total_teams"], "teams_imported": len(members),
        "my_team_id": franchise_id,
        "my_roster": mapped["rosters"].get(franchise_id, []),
        "future_picks_stored": len(parsed["future_picks"]),
        "report": _platform_report_json(r),
    })


@app.route("/api/mfl/leagues")
def mfl_leagues():
    if not is_enabled("mfl.link"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import mfl_service as _mfl
    from .database import load_platform_leagues_for_user, get_platform_league
    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401
    leagues = load_platform_leagues_for_user(user_id, "mfl")

    # #201 — automatic fix-up for leagues linked BEFORE format detection
    # existed (default_scoring never written → everything rendered as 1QB).
    # This list read fires whenever the mobile league picker refreshes, so a
    # stale league self-heals without asking the user to re-link. Inline and
    # bounded: only rows still missing a format, only the two exports
    # detection needs (league + rules), at most one attempt per league per
    # process. Failures log and leave the default in place.
    for lg in leagues:
        lid = lg["league_id"]
        if lid in _mfl_scoring_backfill_attempted:
            continue
        _mfl_scoring_backfill_attempted.add(lid)
        try:
            row = get_platform_league(lid, "mfl")
            if not row or row.get("default_scoring"):
                continue
            year = row.get("platform_season") or _MFL_DEFAULT_YEAR
            host = row.get("platform_host") or _mfl.resolve_host(lid, year)
            cookie = (_mfl_cookie_for(sess, user_id)
                      if row.get("platform_auth") == "cookie" else None)
            raw = _mfl.fetch_scoring_inputs(lid, year, host, cookie=cookie)
            _mfl_store_scoring_format(lid, raw, "mfl_leagues backfill")
        except Exception as e:
            log.warning("mfl_leagues: scoring backfill failed for %s "
                        "(stays default): %s", lid, e)

    for lg in leagues:
        lg["members"] = [
            {"user_id": m["user_id"], "username": m.get("username") or "",
             "display_name": m.get("display_name") or "",
             "player_ids": m.get("player_ids", [])}
            for m in lg["members"]
        ]
    return jsonify({"leagues": leagues})


@app.route("/api/mfl/import", methods=["POST"])
@_gate_unverified_write
def mfl_import():
    """Re-sync an already-linked MFL league's rosters (manual refresh)."""
    if not is_enabled("mfl.link"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import mfl_service as _mfl
    from .database import (get_platform_league, upsert_platform_league,
                           replace_espn_league_members)

    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    body = request.get_json(force=True) or {}
    league_id = str(body.get("league_id") or "").strip()
    row = get_platform_league(league_id, "mfl") if league_id else None
    if not row:
        return jsonify({"error": "mfl_not_linked",
                        "message": "Link this MFL league first."}), 404

    year = row.get("platform_season") or _MFL_DEFAULT_YEAR
    host = row.get("platform_host")
    # #177 — leagues linked via the authed flow (auth='cookie') may be private:
    # re-sync with the user's MFL cookie when one is stored (None otherwise).
    cookie = (_mfl_cookie_for(sess, user_id)
              if row.get("platform_auth") == "cookie" else None)
    try:
        if not host:
            host = _mfl.resolve_host(league_id, year)
        raw = _mfl.fetch_league_bundle(league_id, year, host, cookie=cookie)
    except _mfl.MflError as e:
        return _platform_error_response(e, "mfl")

    parsed = _mfl.parse_bundle(raw)
    mapped = _mfl.map_franchises(parsed, _shared_crosswalk())
    my_team = row.get("platform_my_team")
    if my_team not in {fr["franchise_id"] for fr in parsed["franchises"]}:
        return jsonify({"error": "mfl_team_missing",
                        "message": "Your franchise is no longer in this league — "
                                   "re-link to pick a team."}), 409

    members = []
    for fr in parsed["franchises"]:
        fid = fr["franchise_id"]
        mid = user_id if fid == my_team else _mfl_member_id(league_id, fid)
        members.append({"user_id": mid, "username": fr["name"],
                        "display_name": fr["name"],
                        "player_ids": mapped["rosters"].get(fid, []),
                        "team_key": f"mfl:{league_id}.f{fid}"})   # ADR-011
    try:
        upsert_platform_league(
            league_id=league_id, user_id=row["user_id"],
            name=parsed["name"] or row.get("name") or "", platform="mfl",
            season=year, auth=row.get("platform_auth") or "public",
            my_team=my_team, total_rosters=parsed["total_teams"], host=host,
            future_picks=parsed["future_picks"])
        replace_espn_league_members(league_id, members)
    except Exception:
        log.exception("mfl_import: persistence failed")
        return jsonify({"error": "store_failed"}), 500

    # ADR-011 Writer A — after the membership transaction committed.
    _platform_roster_history_on_sync(
        league_id, "mfl", members,
        my_user_id=user_id, my_team_key=f"mfl:{league_id}.f{my_team}")

    # #158 — re-normalize MFL owned picks on manual refresh (see mfl_link).
    if is_enabled("picks.owned_sync"):
        try:
            _npk = _sync_mfl_owned_picks(league_id)
            log.info("mfl_import: normalized %d owned picks", _npk)
        except Exception as _mpk_err:
            log.warning("mfl_import: owned-pick normalization failed (continuing): %s", _mpk_err)

    # #201 — re-detect on every re-sync. This is also the manual fix-up path
    # for leagues linked before format detection existed.
    _mfl_store_scoring_format(league_id, raw, "mfl_import")

    return jsonify({
        "ok": True, "league_id": league_id, "name": parsed["name"],
        "platform": "mfl", "season": year, "auth": row.get("platform_auth") or "public",
        "total_teams": parsed["total_teams"], "teams_imported": len(members),
        "my_team_id": my_team, "my_roster": mapped["rosters"].get(my_team, []),
        "future_picks_stored": len(parsed["future_picks"]),
        "report": _platform_report_json(mapped["report"]),
    })


# ── MFL authenticated linking (#177, flag `mfl.auth_link`) ───────────────────
#
#   POST /api/mfl/auth-link   {username, password, year?} → MFL login +
#                             myleagues (the user's leagues w/ franchise ids)
#   POST /api/mfl/auth-import {league_ids?, year?}        → import leagues
#                             (default: ALL from myleagues), franchise
#                             auto-bound from myleagues — no choose-team step.
#
# The password is used for the single MFL login call and is NEVER persisted
# and NEVER logged (no log line in these routes carries username or password).
# What we keep is the MFL_USER_ID session cookie MFL returns: Fernet-encrypted
# at rest (mfl_credentials, SLEEPER_TOKEN_KEY — same key as sleeper/espn
# credentials). If the key is not configured we fail closed to SESSION-ONLY
# storage: the cookie lives in the in-memory session dict (never part of the
# persisted-session row, which serializes named identity fields only) and dies
# with it. Imports reuse the public-import persistence path with the cookie
# attached, so private leagues work.

def _mfl_cookie_for(sess, user_id: str) -> str | None:
    """The user's MFL session cookie: encrypted row first, in-memory session
    fallback (key-less deployments). None when never signed in."""
    from .database import get_mfl_credential
    try:
        cred = get_mfl_credential(user_id)
    except Exception:
        cred = None
    if cred:
        try:
            return _sleeper_write.decrypt_token(cred["cookie_encrypted"])
        except _sleeper_write.SleeperWriteError as e:
            log.warning("mfl auth: stored cookie undecryptable for %s: %s",
                        user_id, e)
    return sess.get("mfl_cookie")


_MFL_AUTH_ERROR_CODES = {
    "auth":      ("mfl_auth_required", "MFL wouldn't share this league — the sign-in may have expired."),
    "not_found": ("mfl_league_not_found", "MFL has no league with that ID."),
}


def _mfl_import_league_authed(user_id: str, league_id: str, year: int,
                              host: str | None, cookie: str | None,
                              franchise_id: str) -> dict:
    """Fetch + persist ONE MFL league with the user's cookie, binding
    `franchise_id` (from myleagues) as the user's team. Returns the per-league
    summary dict. Raises MflError on fetch/franchise problems — the caller
    turns those into `failed` entries instead of aborting the batch."""
    from . import mfl_service as _mfl
    from .database import upsert_platform_league, replace_espn_league_members

    if not host:
        host = _mfl.resolve_host(league_id, year)
    raw = _mfl.fetch_league_bundle(league_id, year, host, cookie=cookie)
    parsed = _mfl.parse_bundle(raw)
    mapped = _mfl.map_franchises(parsed, _shared_crosswalk())

    if franchise_id not in {fr["franchise_id"] for fr in parsed["franchises"]}:
        raise _mfl.MflError(
            "couldn't match your franchise in this league", kind="franchise")

    members = []
    for fr in parsed["franchises"]:
        fid = fr["franchise_id"]
        mid = user_id if fid == franchise_id else _mfl_member_id(league_id, fid)
        members.append({"user_id": mid, "username": fr["name"],
                        "display_name": fr["name"],
                        "player_ids": mapped["rosters"].get(fid, []),
                        "team_key": f"mfl:{league_id}.f{fid}"})   # ADR-011
    upsert_platform_league(
        league_id=league_id, user_id=user_id,
        name=parsed["name"] or f"MFL league {league_id}", platform="mfl",
        season=year, auth="cookie", my_team=franchise_id,
        total_rosters=parsed["total_teams"], host=host,
        future_picks=parsed["future_picks"])
    replace_espn_league_members(league_id, members)

    # ADR-011 Writer A — after the membership transaction committed.
    _platform_roster_history_on_sync(
        league_id, "mfl", members,
        my_user_id=user_id, my_team_key=f"mfl:{league_id}.f{franchise_id}")

    # #158 — same best-effort owned-pick normalization as the public path.
    if is_enabled("picks.owned_sync"):
        try:
            _npk = _sync_mfl_owned_picks(league_id)
            log.info("mfl_auth_import: normalized %d owned picks (league=%s)",
                     _npk, league_id)
        except Exception as _mpk_err:
            log.warning("mfl_auth_import: owned-pick normalization failed "
                        "(continuing): %s", _mpk_err)

    # #201 — detect + store the league's scoring format from the bundle.
    _mfl_store_scoring_format(league_id, raw, "mfl_auth_import")

    r = mapped["report"]
    return {
        "league_id": league_id, "name": parsed["name"], "season": year,
        "my_team_id": franchise_id, "teams_imported": len(members),
        "total_teams": parsed["total_teams"],
        "future_picks_stored": len(parsed["future_picks"]),
        "match_rate": round(r["match_rate"], 4),
    }


@app.route("/api/mfl/auth-link", methods=["GET", "POST", "DELETE"])
@_gate_unverified_write
def mfl_auth_link():
    """Sign in with MFL and list the user's leagues (no import yet).

    GET → sign-in status, mirroring GET /api/sleeper/link (send-auth lazy
    flow, 2026-08-11): {connected, mfl_username, year}. Never returns the
    cookie. `connected` is true when an encrypted credential row exists OR
    the (key-less-deployment) session-only cookie is present; MFL stamps no
    expiry on its cookie, so there is no expires_at/expired here — a dead
    cookie surfaces as 409 mfl_auth_expired at propose time.

    DELETE → drop the stored MFL cookie (disconnect), mirroring
    DELETE /api/sleeper/link. Removes BOTH storage locations — the encrypted
    mfl_credentials row AND the key-less-deployment session-only copy — so
    the GET above reports {connected: false} afterward whichever path stored
    it. Idempotent; scoped to the caller's own row. Added after the
    2026-08-12 ESPN incident (no user-facing credential removal).
    """
    if not is_enabled("mfl.auth_link"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import mfl_service as _mfl

    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    if request.method == "DELETE":
        # Write gate already applied by @_gate_unverified_write.
        from .database import delete_mfl_credential
        delete_mfl_credential(user_id)
        sess.pop("mfl_cookie", None)   # session-only fallback copy
        log.info("mfl_auth_link: credential deleted (disconnect) user=%s",
                 user_id)
        return jsonify({"connected": False})

    if request.method == "GET":
        from .database import get_mfl_credential
        try:
            cred = get_mfl_credential(user_id)
        except Exception:
            cred = None
        if cred:
            return jsonify({"connected": True,
                            "mfl_username": cred.get("mfl_username"),
                            "year": cred.get("year")})
        if sess.get("mfl_cookie"):
            return jsonify({"connected": True,
                            "mfl_username": None, "year": None})
        return jsonify({"connected": False})

    body = request.get_json(force=True) or {}
    username = str(body.get("username") or "").strip()
    password = body.get("password") or ""
    try:
        year = int(body.get("year") or _MFL_DEFAULT_YEAR)
    except (TypeError, ValueError):
        return jsonify({"error": "mfl_bad_year",
                        "message": "year must be numeric"}), 400
    if not username or not password:
        return jsonify({"error": "mfl_missing_credentials",
                        "message": "MFL username and password are required."}), 400

    try:
        auth = _mfl.login(username, password, year)
        del password  # transient use only — never persisted, never logged
        leagues = _mfl.fetch_my_leagues(auth["cookie"], year)
    except _mfl.MflAuthError:
        return jsonify({"error": "mfl_bad_credentials",
                        "message": "MFL didn't accept that username and password."}), 403
    except _mfl.MflError as e:
        return _platform_error_response(e, "mfl")

    # Store ONLY the returned cookie — encrypted at rest when the key exists,
    # otherwise session-only (fail closed: plaintext never reaches the DB).
    storage = "session"
    if _sleeper_write.token_encryption_available():
        try:
            from .database import upsert_mfl_credential
            upsert_mfl_credential(
                user_id, username,
                _sleeper_write.encrypt_token(auth["cookie"]), year)
            storage = "encrypted"
        except Exception:
            log.exception("mfl_auth_link: credential store failed "
                          "(falling back to session-only)")
    if storage == "session":
        sess["mfl_cookie"] = auth["cookie"]

    # ── A successful MFL login counts as session verification ────────────
    # Operator decision (2026-08-11, Send-in-MFL follow-ups): MFL accepting
    # the username/password THIS request carried is proof-of-person — the
    # MFL analogue of the Sleeper-JWT oracle — so an MFL-only user (no
    # Sleeper/Apple/Google sign-in) can pass the hard verified gate on
    # POST /api/trades/propose-mfl. Mirrors sleeper_link's proven-live
    # block exactly: session marked verified, users.verified_via persisted,
    # durable row upserted. D-018 (unverified sessions keep the short
    # expiry) is honored by construction: the 90-day rolling expiry is
    # granted by _session_persist_eligible reading sess["verified"], so
    # verifying here IS what flips this session from the 4h posture to the
    # long one — nothing else to set. Squatter safety is unchanged:
    # @_gate_unverified_write already 403s an unverified session whenever a
    # verified controller exists, so this path can only mint the FIRST
    # controller (first-verified-wins, same as the Sleeper path).
    sess["verified"] = True
    sess["verified_via"] = "mfl_login"
    try:
        from . import accounts as _accounts
        first_time = _accounts.get_user_verified_via(user_id) is None
        if not user_exists(user_id):
            # Login can beat session_init's background user upsert; make
            # sure the row exists so the marker isn't dropped.
            upsert_user(sleeper_user_id=user_id)
        _accounts.mark_user_verified(user_id, "mfl_login")
        if first_time:
            log.info("AUTH-VERIFIED first verified controller user_id=%s "
                     "via=mfl_login", user_id)
    except Exception:
        log.exception("persisting verified marker failed (session still "
                      "verified in memory)")
    # Durable session (flag auth.persistent_sessions): the session just
    # became verified — persist it so it survives deploys/idle sweeps and
    # picks up the verified 90d rolling expiry.
    sess["_persisted_at"] = 0  # force the upsert past the throttle
    _persist_session_if_eligible(
        request.headers.get("X-Session-Token", ""), sess)

    log.info("mfl_auth_link: user=%s year=%s leagues=%d storage=%s",
             user_id, year, len(leagues), storage)
    return jsonify({"ok": True, "year": year, "storage": storage,
                    "verified": bool(sess.get("verified")),
                    "leagues": leagues})


@app.route("/api/mfl/auth-import", methods=["POST"])
@_gate_unverified_write
def mfl_auth_import():
    """Import the signed-in user's MFL leagues — default ALL from myleagues.

    Body: {league_ids?: [..], year?}. Franchise binding comes from myleagues
    (franchise-scoped), so there is no choose-team step; a league whose
    franchise can't be matched lands in `failed` (linkable via the manual
    flow). Imports run sequentially (MFL rate guidance) and one league's
    failure never aborts the rest."""
    if not is_enabled("mfl.auth_link"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import mfl_service as _mfl

    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    body = request.get_json(force=True) or {}
    try:
        year = int(body.get("year") or _MFL_DEFAULT_YEAR)
    except (TypeError, ValueError):
        return jsonify({"error": "mfl_bad_year",
                        "message": "year must be numeric"}), 400

    cookie = _mfl_cookie_for(sess, user_id)
    if not cookie:
        return jsonify({"error": "mfl_not_connected",
                        "message": "Sign in with MFL first."}), 409

    try:
        my_leagues = _mfl.fetch_my_leagues(cookie, year)
    except _mfl.MflAuthError:
        # Dead cookie — drop the stored copy so the client re-prompts sign-in.
        from .database import delete_mfl_credential
        delete_mfl_credential(user_id)
        sess.pop("mfl_cookie", None)
        return jsonify({"error": "mfl_auth_expired",
                        "message": "Your MFL sign-in expired — sign in again."}), 409
    except _mfl.MflError as e:
        return _platform_error_response(e, "mfl")

    by_id = {lg["league_id"]: lg for lg in my_leagues}
    requested = [str(x).strip() for x in (body.get("league_ids") or []) if str(x).strip()]
    if not requested:                       # default: import ALL
        requested = list(by_id.keys())

    imported, failed = [], []
    for i, league_id in enumerate(requested):
        if i > 0 and not app.config.get("TESTING"):
            time.sleep(1.0)                 # MFL guidance: space requests ≥1s
        lg = by_id.get(league_id)
        if lg is None:
            failed.append({"league_id": league_id, "error": "mfl_not_your_league",
                           "message": "MFL doesn't list you in that league."})
            continue
        if not lg.get("franchise_id"):
            failed.append({"league_id": league_id, "error": "mfl_franchise_unknown",
                           "message": "Couldn't auto-detect your team — link this "
                                      "league manually to pick it."})
            continue
        try:
            imported.append(_mfl_import_league_authed(
                user_id, league_id, year, lg.get("host"), cookie,
                str(lg["franchise_id"])))
        except _mfl.MflError as e:
            kind = getattr(e, "kind", "http")
            if kind == "franchise":
                failed.append({"league_id": league_id, "error": "mfl_franchise_unknown",
                               "message": "Couldn't auto-detect your team — link "
                                          "this league manually to pick it."})
            else:
                code, msg = _MFL_AUTH_ERROR_CODES.get(
                    kind, ("mfl_unavailable", "Couldn't reach MFL — try again shortly."))
                failed.append({"league_id": league_id, "error": code, "message": msg})
        except Exception:
            log.exception("mfl_auth_import: persistence failed (league=%s)", league_id)
            failed.append({"league_id": league_id, "error": "store_failed",
                           "message": "Import failed — try again."})

    log.info("mfl_auth_import: user=%s year=%s requested=%d imported=%d failed=%d",
             user_id, year, len(requested), len(imported), len(failed))
    return jsonify({"ok": True, "year": year, "requested": len(requested),
                    "imported": imported, "failed": failed})


# ── Trade-send pre-flight validation (#180) ──────────────────────────────────
#
# The Sleeper send is ultimately enforced by Sleeper (its API rejects what its
# rules forbid), so FTF's job is to catch what's knowable BEFORE the handoff
# and say so honestly. This read-only route re-fetches the league's live meta
# + rosters from Sleeper's public API and reports advisory findings; it NEVER
# blocks — the client decides how loudly to warn. Checked here: league season
# closed, traded players no longer on the expected rosters, post-trade roster
# counts vs the league's roster limit. Everything else (locked players, trade
# deadline, review/veto windows, FAAB validity) is delegated to Sleeper.
# Docs: docs/feedback/items/180-trade-send-validation/status.md

@app.route("/api/trades/validate", methods=["POST"])
def trades_validate():
    """Pre-send checks for a Sleeper OR MFL trade. Body mirrors the propose
    routes: {league_id, their_user_id (or their_roster_id), give_player_ids[],
    receive_player_ids[]}. → {ok, checked, warnings:[{code,severity,message}]}.
    `checked:false` = platform data unreachable (nothing validated). An
    MFL-linked league (flag `trade.send_in_mfl`) validates against a fresh MFL
    `rosters` export; everything else takes the Sleeper path unchanged."""
    if not (is_enabled("trade.send_in_sleeper") or is_enabled("trade.send_in_mfl")):
        return jsonify({"error": "feature_disabled"}), 404
    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    body = request.get_json(force=True) or {}
    league_id = str(body.get("league_id") or "").strip()
    their_user_id = body.get("their_user_id")
    their_roster_id_in = body.get("their_roster_id")
    give = [str(p) for p in (body.get("give_player_ids") or [])]
    receive = [str(p) for p in (body.get("receive_player_ids") or [])]
    if not league_id.isdigit() or (their_user_id is None and their_roster_id_in is None):
        return jsonify({"error": "bad_request"}), 400

    # ── "Send in MFL" branch: an MFL-linked league id (numeric, same as
    # Sleeper's — the #149/#150/#200 misroute class) must never fall through
    # to the Sleeper fetches below. Server-authoritative platform routing via
    # the leagues row, mirroring is_linked_platform_league's discrimination.
    if is_enabled("trade.send_in_mfl"):
        from .database import get_platform_league as _gpl
        _mfl_row = _gpl(league_id, "mfl")
        if _mfl_row:
            return _validate_mfl_trade(sess, user_id, _mfl_row, league_id,
                                       their_user_id, body.get("their_franchise_id"),
                                       give, receive)

    warnings: list[dict] = []

    meta = _fetch_sleeper_league_meta(league_id)
    rosters = _fetch_league_rosters(league_id)
    if not isinstance(meta, dict) or not rosters:
        # Non-Sleeper league id or Sleeper unreachable — nothing checkable.
        return jsonify({"ok": True, "checked": False, "warnings": []})

    if (meta.get("status") or "") == "complete":
        warnings.append({
            "code": "league_archived", "severity": "blocking",
            "message": "This league's season is closed on Sleeper — trades can't be sent.",
        })

    # My roster: for Sleeper leagues the FTF user_id IS the Sleeper user_id.
    # Prefer the linked write-credential account when present (matches how
    # /api/trades/propose resolves the proposing roster).
    my_owner = user_id
    cred = get_sleeper_credential(user_id)
    if cred and cred.get("sleeper_user_id"):
        my_owner = cred["sleeper_user_id"]
    my_rid = _roster_id_for_owner(rosters, my_owner)
    if their_roster_id_in is not None:
        try:
            their_rid = int(their_roster_id_in)
        except (TypeError, ValueError):
            return jsonify({"error": "bad_request"}), 400
    else:
        their_rid = _roster_id_for_owner(rosters, their_user_id)

    by_rid = {}
    for r in rosters:
        try:
            by_rid[int(r.get("roster_id"))] = r
        except (TypeError, ValueError):
            continue
    mine = by_rid.get(my_rid)
    theirs = by_rid.get(their_rid)
    if mine is None or theirs is None:
        warnings.append({
            "code": "roster_not_found", "severity": "blocking",
            "message": "Couldn't match one of the teams to a roster in this "
                       "Sleeper league — a re-sync may be needed.",
        })
        return jsonify({"ok": True, "checked": True, "warnings": warnings})

    my_players = {str(p) for p in (mine.get("players") or [])}
    their_players = {str(p) for p in (theirs.get("players") or [])}
    moved_give = [p for p in give if p not in my_players]
    moved_receive = [p for p in receive if p not in their_players]
    if moved_give or moved_receive:
        n = len(moved_give) + len(moved_receive)
        warnings.append({
            "code": "player_moved", "severity": "blocking",
            "message": (f"{n} player{'s' if n != 1 else ''} in this trade "
                        "are no longer on the expected roster (dropped or "
                        "already traded) — Sleeper will reject the offer."),
        })

    # Roster-limit check: Sleeper's max roster = lineup slots (incl. bench)
    # + reserve (IR) + taxi. roster.players includes reserve+taxi players.
    settings = meta.get("settings") or {}
    try:
        max_roster = (len(meta.get("roster_positions") or [])
                      + int(settings.get("reserve_slots") or 0)
                      + int(settings.get("taxi_slots") or 0))
    except (TypeError, ValueError):
        max_roster = 0
    if max_roster > 0:
        for label, players, out_ids, in_ids in (
            ("Your", my_players, give, receive),
            ("Their", their_players, receive, give),
        ):
            post = len(players) - len([p for p in out_ids if p in players]) + len(in_ids)
            if post > max_roster:
                warnings.append({
                    "code": "roster_limit", "severity": "warning",
                    "message": (f"{label} roster would have {post} players — "
                                f"over the league limit of {max_roster}. "
                                "Sleeper may require a drop before this can "
                                "be accepted."),
                })

    return jsonify({"ok": True, "checked": True, "warnings": warnings})


# ── "Send in MFL" (flag `trade.send_in_mfl`) ─────────────────────────────────
#
# The MFL analogue of "Send in Sleeper" — but riding MFL's DOCUMENTED import
# API (`import?TYPE=tradeProposal`, sanctioned for third-party clients) with
# the `MFL_USER_ID` cookie #177 already stores, so the risk profile is the
# inverse of the Sleeper path. Adapter: backend/mfl_write.py (pure,
# opener-injectable). Scope block + live-verification checklist:
# docs/feedback/items/177-mfl-auth-link/send-in-mfl-scope.md.

#: Reverse crosswalk cache: {sleeper_id: mfl_id}, rebuilt only when the shared
#: DP crosswalk object itself refreshes (espn_service's 24h TTL).
_mfl_reverse_xwalk_cache: tuple | None = None


def _sleeper_to_mfl_map() -> dict:
    """Sleeper player id → MFL player id, inverted from the shared crosswalk's
    `by_mfl_sleeper` (mfl_id is DP's primary key, so coverage is near-total).
    First-wins on the rare many-MFL-ids-to-one-sleeper collision, matching the
    forward map's own setdefault semantics."""
    global _mfl_reverse_xwalk_cache
    xw = _shared_crosswalk()
    cached = _mfl_reverse_xwalk_cache
    if cached is not None and cached[0] is xw:
        return cached[1]
    inv: dict = {}
    for mid, sid in xw.by_mfl_sleeper.items():
        inv.setdefault(sid, mid)
    _mfl_reverse_xwalk_cache = (xw, inv)
    return inv


def _mfl_franchise_from_member_id(league_id: str, member_id) -> str | None:
    """Parse the franchise id out of a synthetic MFL member id
    (`mfl:{league_id}.f{franchise_id}` — server._mfl_member_id's format).
    None when the value isn't a synthetic id for THIS league."""
    m = re.match(rf"^mfl:{re.escape(str(league_id))}\.f(\d+)$",
                 str(member_id or ""))
    return m.group(1) if m else None


# ── MFL pick-asset encoding (FTF pick ids → MFL `FP_…` strings) ──────────────
#
# FTF's trade surfaces carry picks in the SAME id array as players
# (give_player_ids / receive_player_ids): owned picks as
# `{league}_{season}_{round}_{original_roster}` (database.make_pick_id — for
# MFL leagues `original_roster` is the MFL franchise id, e.g. "0001", straight
# from the futureDraftPicks snapshot) and generic ladder rungs as
# `generic_pick_{round}_{tier}`. The propose route splits picks out of the
# mixed arrays and encodes owned picks server-side; ground truth is the stored
# `leagues.platform_future_picks` snapshot (raw futureDraftPicks), NEVER a
# client-supplied encoding. Anything that can't be positively resolved to a
# snapshot row — generic rungs included (an abstract "Early 1st" names no
# concrete MFL pick) — hard-blocks the send (422 mfl_asset_unmapped).

def _ftf_pick_parts(league_id: str, asset_id) -> tuple[int, int, str] | None:
    """Parse THIS league's owned-pick id shape
    (`{league}_{season}_{round}_{original_roster}`) → (season, round,
    original_roster_id). None for anything else — player ids (no underscore),
    other leagues' pick ids, malformed strings."""
    m = re.match(rf"^{re.escape(str(league_id))}_(\d{{4}})_(\d{{1,2}})_(.+)$",
                 str(asset_id or ""))
    if not m:
        return None
    return int(m.group(1)), int(m.group(2)), m.group(3)


def _is_ftf_pick_asset(league_id: str, asset_id) -> bool:
    """True for the two FTF pick-id shapes a trade array can carry: this
    league's owned-pick ids and generic ladder rungs (`generic_pick_…`)."""
    a = str(asset_id or "")
    return (a.startswith(GENERIC_PICK_ID_PREFIX)
            or _ftf_pick_parts(league_id, a) is not None)


def _mfl_pick_snapshot_index(row) -> dict:
    """{(year, round, orig_fid_4pad): current_owner_fid_4pad} from the
    league's stored futureDraftPicks snapshot (leagues.platform_future_picks,
    parse_future_picks' shape). Malformed entries are skipped — an absent key
    reads as "not a real pick in this league" and hard-blocks upstream."""
    from . import mfl_write as _mfl_write
    try:
        snapshot = json.loads(row.get("platform_future_picks") or "[]")
    except (TypeError, ValueError):
        snapshot = []
    index: dict = {}
    for pk in snapshot if isinstance(snapshot, list) else []:
        if not isinstance(pk, dict):
            continue
        try:
            yr, rnd = int(pk.get("year")), int(pk.get("round"))
            owner = str(pk.get("franchise_id") or "")
            orig = _mfl_write.normalize_franchise_id(
                pk.get("original_owner") or owner)
            owner = _mfl_write.normalize_franchise_id(owner) if owner else ""
        except (TypeError, ValueError, _mfl_write.MflWriteError):
            continue
        index[(yr, rnd, orig)] = owner
    return index


def _mfl_encode_ftf_picks(row, league_id: str, pick_ids: list) -> tuple[dict, list]:
    """FTF pick ids → MFL `FP_FFFF_YYYY_R` strings, ground-truthed against the
    stored futureDraftPicks snapshot. Returns ({pick_id: fp_string}, unmapped).
    A pick that isn't positively present in the snapshot — including every
    generic rung — lands in `unmapped`, never in the encoding: the propose
    route hard-blocks on it (an offer must never silently lose an asset)."""
    from . import mfl_write as _mfl_write
    index = _mfl_pick_snapshot_index(row)
    encoded: dict = {}
    unmapped: list = []
    for pid in pick_ids:
        parts = _ftf_pick_parts(league_id, pid)
        key = None
        if parts is not None:
            yr, rnd, orig = parts
            try:
                key = (yr, rnd, _mfl_write.normalize_franchise_id(orig))
            except _mfl_write.MflWriteError:
                key = None
        if key is None or key not in index:
            unmapped.append(pid)
            continue
        encoded[pid] = _mfl_write.encode_future_pick(key[2], key[0], key[1])
    return encoded, unmapped


def _validate_mfl_trade(sess, user_id, row, league_id, their_user_id,
                        their_franchise_in, give, receive):
    """#180-parity pre-flight for an MFL send: advisory only, never blocks.
    Checks the reverse crosswalk + pick-snapshot mapping (mirror of the
    propose route's hard block), pick ownership against the stored
    futureDraftPicks snapshot (no network), and each side's players against
    a fresh MFL `rosters` export."""
    from . import mfl_service as _mfl
    from . import mfl_write as _mfl_write

    warnings: list[dict] = []
    norm = _mfl_write.normalize_franchise_id

    my_fid = row.get("platform_my_team")
    their_fid = (str(their_franchise_in).strip() if their_franchise_in is not None
                 else _mfl_franchise_from_member_id(league_id, their_user_id))
    if not my_fid or not their_fid:
        return jsonify({"ok": True, "checked": True, "warnings": [{
            "code": "roster_not_found", "severity": "blocking",
            "message": "Couldn't match one of the teams to a franchise in "
                       "this MFL league — a re-sync may be needed.",
        }]})

    # Same split the propose route makes: picks ride the mixed arrays and are
    # checked against the stored snapshot, players against the crosswalk.
    give_players = [p for p in give if not _is_ftf_pick_asset(league_id, p)]
    give_picks = [p for p in give if _is_ftf_pick_asset(league_id, p)]
    recv_players = [p for p in receive if not _is_ftf_pick_asset(league_id, p)]
    recv_picks = [p for p in receive if _is_ftf_pick_asset(league_id, p)]

    # Advisory mirror of the propose route's mapping HARD block (crosswalk
    # misses + picks absent from the futureDraftPicks snapshot).
    inverse = _sleeper_to_mfl_map()
    _, pick_unmapped = _mfl_encode_ftf_picks(row, league_id,
                                             give_picks + recv_picks)
    unmapped = ([p for p in give_players + recv_players if p not in inverse]
                + pick_unmapped)
    if unmapped:
        n = len(unmapped)
        warnings.append({
            "code": "asset_unmapped", "severity": "blocking",
            "message": (f"{n} asset{'s' if n != 1 else ''} in this trade "
                        "couldn't be matched to an MFL asset id — the send "
                        "will be blocked rather than dropping them."),
        })

    # Pick-ownership advisory (#180's player_moved, for picks): the stored
    # snapshot carries each pick's CURRENT owner franchise, so a pick that
    # changed hands since the trade was built is catchable with zero network.
    pick_index = _mfl_pick_snapshot_index(row)

    def _pick_owner(pid):
        parts = _ftf_pick_parts(league_id, pid)
        if parts is None:
            return None
        try:
            return pick_index.get((parts[0], parts[1], norm(parts[2])))
        except _mfl_write.MflWriteError:
            return None

    moved_picks = [p for p in give_picks
                   if (_pick_owner(p) or "") not in ("", norm(my_fid))]
    moved_picks += [p for p in recv_picks
                    if (_pick_owner(p) or "") not in ("", norm(their_fid))]
    if moved_picks:
        n = len(moved_picks)
        warnings.append({
            "code": "pick_moved", "severity": "blocking",
            "message": (f"{n} pick{'s' if n != 1 else ''} in this trade "
                        "are no longer owned by the expected team (already "
                        "traded) — MFL will reject the offer."),
        })

    year = int(row.get("platform_season") or _MFL_DEFAULT_YEAR)
    host = row.get("platform_host")
    cookie = (_mfl_cookie_for(sess, user_id)
              if row.get("platform_auth") == "cookie" else None)
    rosters: dict = {}
    try:
        if not host:
            host = _mfl.resolve_host(league_id, year)
        rosters = _mfl.parse_roster_ids(
            _mfl.fetch_rosters(league_id, year, host, cookie=cookie))
    except _mfl.MflError:
        rosters = {}
    if not rosters:
        # MFL unreachable — nothing roster-checkable. checked reflects whether
        # the crosswalk pass at least ran to a finding.
        return jsonify({"ok": True, "checked": bool(warnings),
                        "warnings": warnings})

    by_norm = {norm(fid): ids for fid, ids in rosters.items() if fid}
    mine = by_norm.get(norm(my_fid))
    theirs = by_norm.get(norm(their_fid))
    if mine is None or theirs is None:
        warnings.append({
            "code": "roster_not_found", "severity": "blocking",
            "message": "Couldn't match one of the teams to a roster in this "
                       "MFL league — a re-sync may be needed.",
        })
        return jsonify({"ok": True, "checked": True, "warnings": warnings})

    moved = [p for p in give_players if p in inverse and inverse[p] not in mine]
    moved += [p for p in recv_players if p in inverse and inverse[p] not in theirs]
    if moved:
        n = len(moved)
        warnings.append({
            "code": "player_moved", "severity": "blocking",
            "message": (f"{n} player{'s' if n != 1 else ''} in this trade "
                        "are no longer on the expected roster (dropped or "
                        "already traded) — MFL will reject the offer."),
        })
    # Roster limits / trade deadline / commissioner locks are delegated to
    # MFL (its import enforces league rules), same philosophy as Sleeper.
    return jsonify({"ok": True, "checked": True, "warnings": warnings})


@app.route("/api/trades/propose-mfl", methods=["POST"])
def propose_trade_to_mfl():
    """Send a built trade into MyFantasyLeague as a real pending proposal.

    Body: {league_id, their_user_id (the synthetic `mfl:{L}.f{FFFF}` member id
           every MFL counterparty carries) or their_franchise_id,
           give_player_ids[], receive_player_ids[]   (FTF/Sleeper-space ids —
           MAY carry FTF pick ids: `{league}_{season}_{round}_{orig_franchise}`
           owned picks are split out and encoded to MFL `FP_…` strings
           server-side against the stored futureDraftPicks snapshot; generic
           rungs hard-block),
           give_pick_assets?[], receive_pick_assets?[]  (pre-encoded MFL
           `DP_RR_SS` / `FP_FFFF_YYYY_R` strings — no mobile sender),
           comments?, expires?, impression_id?}
    Success → {status:"proposed"}. Structured errors (client maps to
    reconnect / fallback UX):
      404 feature_disabled | 403 verification_required | 404 mfl_not_linked
      409 mfl_franchise_unknown | 409 mfl_not_connected | 409 mfl_auth_expired
      422 mfl_asset_unmapped (+ unmapped[]) | 502 mfl_write_failed
      400 bad_request

    Sibling of POST /api/trades/propose (Sleeper) rather than a platform
    switch on it: both platforms' league ids are numeric (#149/#150/#200
    misroute class), so platform routing is explicit — the client picks the
    route by the league's platform, and each route re-verifies its own
    platform server-side via the leagues row.
    """
    if _TEST_MODE:
        # Fail closed: there is no legitimate automated send (mirrors the
        # Sleeper propose route's 599 under the UI-test harness).
        return jsonify({"error": "test_mode_propose_disabled"}), 599
    if not is_enabled("trade.send_in_mfl"):
        return jsonify({"error": "feature_disabled"}), 404
    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    # Same P1 hard gate as the Sleeper propose route: this writes into the
    # user's REAL MFL league — only a session that proved control of this
    # user_id may fire it. No grace period.
    if not sess.get("verified"):
        log.warning("AUTH-DENY unverified_write user_id=%s method=%s path=%s "
                    "reason=hard_route", user_id, request.method, request.path)
        return jsonify({"error": "verification_required"}), 403

    from . import mfl_service as _mfl
    from . import mfl_write as _mfl_write
    from .database import get_platform_league, delete_mfl_credential

    body = request.get_json(force=True) or {}
    league_id = str(body.get("league_id") or "").strip()
    their_member_id = body.get("their_user_id")
    their_franchise_in = body.get("their_franchise_id")
    give = [str(p) for p in (body.get("give_player_ids") or [])]
    receive = [str(p) for p in (body.get("receive_player_ids") or [])]
    give_picks = [str(p) for p in (body.get("give_pick_assets") or [])]
    receive_picks = [str(p) for p in (body.get("receive_pick_assets") or [])]
    if not league_id.isdigit() or \
            (their_member_id is None and their_franchise_in is None):
        return jsonify({"error": "bad_request"}), 400
    if not (give or receive or give_picks or receive_picks):
        return jsonify({"error": "bad_request"}), 400
    for p in give_picks + receive_picks:
        if not _mfl_write.is_pick_asset_id(p):
            return jsonify({"error": "bad_request",
                            "message": f"bad pick asset encoding: {p}"}), 400

    # Server-authoritative platform + franchise resolution from the leagues
    # row — the client never asserts its own franchise id.
    row = get_platform_league(league_id, "mfl")
    if not row:
        return jsonify({"error": "mfl_not_linked",
                        "message": "Link this MFL league first."}), 404
    if str(row.get("user_id") or "") != str(user_id):
        # One linker per platform-league row; only the linker has a franchise
        # binding, so nobody else can send from it.
        return jsonify({"error": "mfl_not_linked",
                        "message": "This MFL league isn't linked to your "
                                   "account."}), 404
    my_fid = str(row.get("platform_my_team") or "").strip()
    if not my_fid:
        return jsonify({"error": "mfl_franchise_unknown",
                        "message": "Couldn't determine your franchise — "
                                   "re-link this league."}), 409

    their_fid = (str(their_franchise_in).strip() if their_franchise_in is not None
                 else _mfl_franchise_from_member_id(league_id, their_member_id))
    if not their_fid or not str(their_fid).isdigit():
        return jsonify({"error": "bad_request",
                        "message": "Couldn't resolve the counterparty "
                                   "franchise."}), 400
    try:
        if (_mfl_write.normalize_franchise_id(their_fid)
                == _mfl_write.normalize_franchise_id(my_fid)):
            return jsonify({"error": "bad_request",
                            "message": "You can't send a trade to your own "
                                       "franchise."}), 400
    except _mfl_write.MflWriteError:
        return jsonify({"error": "bad_request"}), 400

    cookie = _mfl_cookie_for(sess, user_id)
    if not cookie:
        return jsonify({"error": "mfl_not_connected",
                        "message": "Sign in with MFL first."}), 409

    # FTF's trade surfaces carry picks in the same arrays as players — split
    # them out so each class maps through its own ground truth.
    give_players = [p for p in give if not _is_ftf_pick_asset(league_id, p)]
    give_ftf_picks = [p for p in give if _is_ftf_pick_asset(league_id, p)]
    recv_players = [p for p in receive if not _is_ftf_pick_asset(league_id, p)]
    recv_ftf_picks = [p for p in receive if _is_ftf_pick_asset(league_id, p)]

    # Asset mapping — HARD BLOCK on any miss, players AND picks. An offer must
    # never silently drop an asset: a partially-mapped trade is a DIFFERENT
    # trade, so the send refuses instead. Players reverse-crosswalk
    # (FTF/Sleeper ids → MFL ids); owned picks encode to `FP_…` against the
    # stored futureDraftPicks snapshot; generic rungs (`generic_pick_…`) name
    # no concrete MFL pick and always land in unmapped.
    inverse = _sleeper_to_mfl_map()
    pick_encoded, pick_unmapped = _mfl_encode_ftf_picks(
        row, league_id, give_ftf_picks + recv_ftf_picks)
    unmapped = ([p for p in give_players + recv_players if p not in inverse]
                + pick_unmapped)
    if unmapped:
        return jsonify({"error": "mfl_asset_unmapped",
                        "unmapped": unmapped,
                        "message": "Some assets couldn't be matched to MFL "
                                   "asset ids, so nothing was sent."}), 422

    year = int(row.get("platform_season") or _MFL_DEFAULT_YEAR)
    host = row.get("platform_host")
    try:
        if not host:
            host = _mfl.resolve_host(league_id, year)
    except _mfl.MflError as e:
        return _platform_error_response(e, "mfl")

    expires = body.get("expires")
    req = _mfl_write.ProposeTradeRequest(
        league_id=league_id,
        offered_to=their_fid,
        will_give_up=([inverse[p] for p in give_players]
                      + [pick_encoded[p] for p in give_ftf_picks]
                      + give_picks),
        will_receive=([inverse[p] for p in recv_players]
                      + [pick_encoded[p] for p in recv_ftf_picks]
                      + receive_picks),
        comments=(str(body.get("comments") or "").strip() or None),
        expires=int(expires) if expires is not None else None,
    )
    try:
        result = _mfl_write.propose_trade(cookie, host, year, req)
    except _mfl_write.MflWriteAuthError as e:
        # Dead/rejected cookie — drop the stored credential so the client
        # re-prompts MFL sign-in (same treatment as mfl_auth_import).
        log.warning("mfl propose auth-rejected: %s", getattr(e, "detail", None))
        try:
            delete_mfl_credential(user_id)
        except Exception:
            log.exception("mfl propose: credential delete failed")
        sess.pop("mfl_cookie", None)
        return jsonify({
            "error": "mfl_auth_expired",
            "message": "Your MFL sign-in expired — sign in again.",
            "detail": (str(getattr(e, "detail", "") or ""))[:200],
        }), 409
    except _mfl_write.MflWriteError as e:
        log.warning("mfl propose write-failed [%s]: %s", e.kind,
                    getattr(e, "detail", None))
        return jsonify({
            "error": "mfl_write_failed",
            "kind": e.kind,
            "detail": (str(getattr(e, "detail", "") or ""))[:200],
        }), 502

    # F1 (deck.signal_v2) — same proposal-sent outcome hook as the Sleeper
    # route; additive/optional, only reached on a successful MFL import.
    _save_deck_outcome_safe(body.get("impression_id"), "propose",
                            acting_user_id=user_id)
    # trade_sent (server-fired, taxonomy 2026-08-11) — confirmed-success
    # only; every failure branch (incl. the mfl_asset_unmapped hard block)
    # returned before this. `platform` is mandatory/non-null. MFL picks ARE
    # side-attributed, so they fold into the per-side counts.
    try:
        record_event(
            user_id, "trade_sent",
            league_id=league_id,
            source="api",
            props={"platform": "mfl",
                   "give_count": len(give) + len(give_picks),
                   "receive_count": len(receive) + len(receive_picks),
                   "outcome": "proposed"},
            **(getattr(g, "device_info", {}) or {}),
        )
    except Exception:
        pass
    log.info("mfl propose: user=%s league=%s offered_to=f%s assets=%d/%d",
             user_id, league_id, their_fid,
             len(give) + len(give_picks), len(receive) + len(receive_picks))
    return jsonify({"status": "proposed", "mfl_status": result.get("status")})


@app.route("/api/trades/respond-mfl", methods=["POST"])
def respond_trade_in_mfl():
    """Accept, reject, or REVOKE a pending MFL trade (the lifecycle sibling of
    propose — revoke is the near-term use: withdraw an offer FTF just sent).

    Body: {league_id, trade_id (from MFL's pendingTrades export — see
           GET /api/mfl/pending-trades), response: "accept"|"reject"|"revoke",
           comments?}
    Success → {status:"responded", response, mfl_status}. Same gates and
    structured error codes as propose (this writes into the user's REAL MFL
    league): 404 feature_disabled (flag `trade.send_in_mfl` — deliberately the
    SAME flag as propose, one send surface, one knob) | 403
    verification_required | 404 mfl_not_linked | 409 mfl_not_connected |
    409 mfl_auth_expired (credential dropped) | 502 mfl_write_failed |
    400 bad_request.
    """
    if _TEST_MODE:
        # Fail closed, same as propose: no legitimate automated response.
        return jsonify({"error": "test_mode_propose_disabled"}), 599
    if not is_enabled("trade.send_in_mfl"):
        return jsonify({"error": "feature_disabled"}), 404
    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    # Same P1 hard gate as propose: accepting/rejecting/revoking mutates a
    # REAL pending trade in the user's league. No grace period.
    if not sess.get("verified"):
        log.warning("AUTH-DENY unverified_write user_id=%s method=%s path=%s "
                    "reason=hard_route", user_id, request.method, request.path)
        return jsonify({"error": "verification_required"}), 403

    from . import mfl_service as _mfl
    from . import mfl_write as _mfl_write
    from .database import get_platform_league, delete_mfl_credential

    body = request.get_json(force=True) or {}
    league_id = str(body.get("league_id") or "").strip()
    trade_id = str(body.get("trade_id") or "").strip()
    response = str(body.get("response") or "").strip().lower()
    if not league_id.isdigit() or not trade_id:
        return jsonify({"error": "bad_request"}), 400
    if response not in ("accept", "reject", "revoke"):
        return jsonify({"error": "bad_request",
                        "message": "response must be accept|reject|revoke"}), 400

    # Server-authoritative platform check — same misroute-class guard as
    # propose (#149/#150/#200: numeric ids alone identify no platform).
    row = get_platform_league(league_id, "mfl")
    if not row:
        return jsonify({"error": "mfl_not_linked",
                        "message": "Link this MFL league first."}), 404
    if str(row.get("user_id") or "") != str(user_id):
        return jsonify({"error": "mfl_not_linked",
                        "message": "This MFL league isn't linked to your "
                                   "account."}), 404

    cookie = _mfl_cookie_for(sess, user_id)
    if not cookie:
        return jsonify({"error": "mfl_not_connected",
                        "message": "Sign in with MFL first."}), 409

    year = int(row.get("platform_season") or _MFL_DEFAULT_YEAR)
    host = row.get("platform_host")
    try:
        if not host:
            host = _mfl.resolve_host(league_id, year)
    except _mfl.MflError as e:
        return _platform_error_response(e, "mfl")

    try:
        result = _mfl_write.respond_trade(
            cookie, host, year, league_id, trade_id, response,
            comments=(str(body.get("comments") or "").strip() or None))
    except _mfl_write.MflWriteAuthError as e:
        log.warning("mfl respond auth-rejected: %s", getattr(e, "detail", None))
        try:
            delete_mfl_credential(user_id)
        except Exception:
            log.exception("mfl respond: credential delete failed")
        sess.pop("mfl_cookie", None)
        return jsonify({
            "error": "mfl_auth_expired",
            "message": "Your MFL sign-in expired — sign in again.",
            "detail": (str(getattr(e, "detail", "") or ""))[:200],
        }), 409
    except _mfl_write.MflWriteError as e:
        log.warning("mfl respond write-failed [%s]: %s", e.kind,
                    getattr(e, "detail", None))
        return jsonify({
            "error": "mfl_write_failed",
            "kind": e.kind,
            "detail": (str(getattr(e, "detail", "") or ""))[:200],
        }), 502

    # trade_responded (server-fired, taxonomy 2026-08-11) — confirmed-success
    # only; every failure branch returned before this. Same discipline as
    # trade_sent: `platform` is mandatory/non-null (the NULL-platform
    # incident); no trade contents/PII in props — trade_id stays out (it's an
    # MFL-side identifier, not needed for the funnel question "are responses
    # happening, and which kind").
    _outcome = {"accept": "accepted", "reject": "rejected",
                "revoke": "revoked"}[response]
    try:
        record_event(
            user_id, "trade_responded",
            league_id=league_id,
            source="api",
            props={"platform": "mfl",
                   "response": response,
                   "outcome": _outcome},
            **(getattr(g, "device_info", {}) or {}),
        )
    except Exception:
        pass
    log.info("mfl respond: user=%s league=%s response=%s", user_id, league_id,
             response)
    return jsonify({"status": "responded", "response": response,
                    "mfl_status": result.get("status")})


@app.route("/api/mfl/pending-trades", methods=["GET"])
def mfl_pending_trades():
    """List the linker's pending MFL trades — the read surface that makes a
    sent proposal's status visible (and its trade_id revocable via
    POST /api/trades/respond-mfl).

    Query: ?league_id=… → {trades: [{trade_id, offering_team, offered_to,
    will_give_up[], will_receive[] (MFL asset ids, offering team's
    perspective), comments, expires}], my_franchise_id}. Rides MFL's
    owner-restricted `export?TYPE=pendingTrades` with the stored cookie —
    session-authed read (no hard verification: nothing mutates), gated behind
    the same `trade.send_in_mfl` flag as the writes it supports. Errors:
    404 feature_disabled | 404 mfl_not_linked | 409 mfl_not_connected |
    409 mfl_auth_expired (credential dropped) | MFL transport errors via the
    shared platform mapping (502 mfl_unavailable, …).
    """
    if not is_enabled("trade.send_in_mfl"):
        return jsonify({"error": "feature_disabled"}), 404
    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    from . import mfl_service as _mfl
    from .database import get_platform_league, delete_mfl_credential

    league_id = str(request.args.get("league_id") or "").strip()
    if not league_id.isdigit():
        return jsonify({"error": "bad_request"}), 400
    row = get_platform_league(league_id, "mfl")
    if not row:
        return jsonify({"error": "mfl_not_linked",
                        "message": "Link this MFL league first."}), 404
    if str(row.get("user_id") or "") != str(user_id):
        return jsonify({"error": "mfl_not_linked",
                        "message": "This MFL league isn't linked to your "
                                   "account."}), 404

    cookie = _mfl_cookie_for(sess, user_id)
    if not cookie:
        return jsonify({"error": "mfl_not_connected",
                        "message": "Sign in with MFL first."}), 409

    year = int(row.get("platform_season") or _MFL_DEFAULT_YEAR)
    host = row.get("platform_host")
    try:
        if not host:
            host = _mfl.resolve_host(league_id, year)
        raw = _mfl.fetch_pending_trades(league_id, year, host, cookie)
    except _mfl.MflAuthError as e:
        # Dead/rejected cookie — same treatment as the write routes so the
        # client's one reconnect path covers the whole send surface.
        log.warning("mfl pending-trades auth-rejected: %s", e)
        try:
            delete_mfl_credential(user_id)
        except Exception:
            log.exception("mfl pending-trades: credential delete failed")
        sess.pop("mfl_cookie", None)
        return jsonify({
            "error": "mfl_auth_expired",
            "message": "Your MFL sign-in expired — sign in again.",
        }), 409
    except _mfl.MflError as e:
        return _platform_error_response(e, "mfl")

    return jsonify({
        "trades": _mfl.parse_pending_trades(raw),
        "my_franchise_id": str(row.get("platform_my_team") or "") or None,
    })


# ── "Send in ESPN" (flag `espn.send` — OFF and ABSENT from features.json) ────
#
# The ESPN analogue of Send-in-Sleeper/-MFL, riding ESPN's UNDOCUMENTED
# lm-api-writes transactions endpoint. Payload live-verified for football
# 2026-08-11 (docs/plans/espn-send-live-capture-2026-08-11.md); D-026 reversed
# the standing write NO-GO to a GATED go. TODO(live-verify) — the flag-
# graduation gate: it is NOT proven that espn_s2 + SWID alone authorize a
# server-side POST (the captures came from a browser session; a CSRF/session
# token may be required), so `espn.send` stays absent from
# config/features.json until a controlled live attempt clears it.
# Adapter: backend/espn_write.py (pure, opener-injectable).

#: Reverse crosswalk cache: {sleeper_id: espn_id}, rebuilt only when the
#: shared DP crosswalk object itself refreshes (espn_service's 24h TTL).
_espn_reverse_xwalk_cache: tuple | None = None


def _sleeper_to_espn_map() -> dict:
    """Sleeper player id → ESPN playerId, inverted from the shared crosswalk's
    `by_espn_id`. CONFIRMED 2026-08-11: the crosswalk's espn_id IS the
    write-API playerId (4/4 live ids matched — capture doc §Resolved 1).
    First-wins on collisions, matching the forward map's setdefault."""
    global _espn_reverse_xwalk_cache
    from . import espn_write as _espn_write
    xw = _shared_crosswalk()
    cached = _espn_reverse_xwalk_cache
    if cached is not None and cached[0] is xw:
        return cached[1]
    inv = _espn_write.invert_espn_crosswalk(xw.by_espn_id)
    _espn_reverse_xwalk_cache = (xw, inv)
    return inv


def _espn_team_id_from_member_id(league_id: str, member_id, teams) -> int | None:
    """Resolve a counterparty's ESPN teamId from the synthetic member id FTF
    stores for ESPN leagues (`_espn_member_id`'s two shapes), verified against
    the LIVE team list from the pre-flight league read — never trusted bare.

      espn:{league_id}.t{team_id}  → that team id, iff present in the league
      espn:{SWID}                  → the team whose owner SWID matches

    None when the id is neither shape or names no current team."""
    from . import espn_service as _espn
    s = str(member_id or "")
    m = re.match(rf"^espn:{re.escape(str(league_id))}\.t(\d+)$", s)
    if m:
        tid = int(m.group(1))
        return tid if any(t.team_id == tid for t in teams) else None
    if s.startswith("espn:"):
        target = _espn.canonical_swid(s[len("espn:"):]).upper()
        for t in teams:
            if t.owner_swid and _espn.canonical_swid(t.owner_swid).upper() == target:
                return t.team_id
    return None


@app.route("/api/trades/propose-espn", methods=["POST"])
def propose_trade_to_espn():
    """Send a built trade into ESPN as a real pending proposal (players only).

    Body: {league_id, their_user_id (the synthetic `espn:{SWID}` /
           `espn:{L}.t{N}` member id ESPN counterparties carry) or
           their_team_id, give_player_ids[], receive_player_ids[]
           (FTF/Sleeper-space PLAYER ids — pick assets hard-block: ESPN's
           pick encoding is unverified, so a pick is refused loudly rather
           than guessed at or dropped), comments?, impression_id?}
    Success → {status:"proposed", transaction_id, espn_status}. Structured
    errors (client maps to reconnect / fallback UX):
      404 feature_disabled | 403 verification_required | 404 espn_not_linked
      409 espn_team_unknown | 409 espn_not_connected | 409 espn_auth_expired
      (stored credential dropped) | 422 espn_pick_unsupported (+ picks[])
      | 422 espn_asset_unmapped (+ unmapped[]) | 502 espn_write_failed
      | 400 bad_request

    Sibling of propose / propose-mfl rather than a platform switch on them
    (the #149/#150/#200 numeric-league-id misroute class): the client routes
    by platform and this route re-verifies platform='espn' via the leagues
    row. Both team ids resolve SERVER-side — mine from the linked row's
    binding, theirs from the member id against a live pre-flight league read
    — the client never asserts either.
    """
    if _TEST_MODE:
        # Fail closed: there is no legitimate automated send (mirrors the
        # Sleeper/MFL propose routes' 599 under the UI-test harness).
        return jsonify({"error": "test_mode_propose_disabled"}), 599
    if not is_enabled("espn.send"):
        return jsonify({"error": "feature_disabled"}), 404
    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    # Same P1 hard gate as the Sleeper/MFL propose routes: this writes into
    # the user's REAL ESPN league — only a session that proved control of
    # this user_id may fire it. No grace period.
    if not sess.get("verified"):
        log.warning("AUTH-DENY unverified_write user_id=%s method=%s path=%s "
                    "reason=hard_route", user_id, request.method, request.path)
        return jsonify({"error": "verification_required"}), 403

    from . import espn_service as _espn
    from . import espn_write as _espn_write
    from .database import (get_espn_league, get_espn_credential,
                           delete_espn_credential)

    body = request.get_json(force=True) or {}
    league_id = str(body.get("league_id") or "").strip()
    their_member_id = body.get("their_user_id")
    their_team_in = body.get("their_team_id")
    give = [str(p) for p in (body.get("give_player_ids") or [])]
    receive = [str(p) for p in (body.get("receive_player_ids") or [])]
    if not league_id.isdigit() or \
            (their_member_id is None and their_team_in is None):
        return jsonify({"error": "bad_request"}), 400
    if not (give or receive):
        return jsonify({"error": "bad_request"}), 400

    # Server-authoritative platform + team resolution from the leagues row —
    # the client never asserts its own team id.
    row = get_espn_league(league_id)
    if not row:
        return jsonify({"error": "espn_not_linked",
                        "message": "Link this ESPN league first."}), 404
    if str(row.get("user_id") or "") != str(user_id):
        # One linker per ESPN league row; only the linker has a team binding,
        # so nobody else can send from it.
        return jsonify({"error": "espn_not_linked",
                        "message": "This ESPN league isn't linked to your "
                                   "account."}), 404
    my_team_id = row.get("espn_my_team_id")
    if my_team_id is None:
        return jsonify({"error": "espn_team_unknown",
                        "message": "Couldn't determine your team — re-link "
                                   "this league."}), 409

    # A write ALWAYS needs the cookie pair, even for a public-league link.
    cred = get_espn_credential(user_id)
    swid = (cred or {}).get("swid")
    if not cred or not swid:
        return jsonify({"error": "espn_not_connected",
                        "message": "Connect your ESPN account first."}), 409
    try:
        espn_s2 = _sleeper_write.decrypt_token(cred["espn_s2_encrypted"])
    except Exception:
        log.warning("espn propose: stored cookie undecryptable for %s", user_id)
        return jsonify({"error": "espn_not_connected",
                        "message": "Your saved ESPN sign-in couldn't be read "
                                   "— connect ESPN again."}), 409

    # PICKS HARD-BLOCK (players only). This is PERMANENT, not a TODO.
    #
    # The original reason ("encoding unverified") is now obsolete: 2026-08-12
    # research confirmed ESPN does carry pick legs, as
    # {"type":"DRAFT_TRADE","overallPickNumber":N,"playerId":0,...}. But
    # overallPickNumber is a slot in the CURRENT draft, and FTF's pick assets
    # are multi-season future rungs ("2027 1st") for which ESPN has no
    # representation at all. There is nothing to encode, not something we
    # haven't decoded yet.
    #
    # In practice this costs users nothing — ESPN leagues don't trade future
    # picks (operator-confirmed), which is a large part of why dynasty players
    # are on Sleeper/MFL in the first place. Refused loudly, never guessed at,
    # never silently dropped.
    picks = [p for p in give + receive if _is_ftf_pick_asset(league_id, p)]
    if picks:
        return jsonify({"error": "espn_pick_unsupported",
                        "picks": picks,
                        "message": "Draft picks can't be sent to ESPN yet, "
                                   "so nothing was sent."}), 422

    # Player mapping — HARD BLOCK on any miss. An offer must never silently
    # drop an asset: a partially-mapped trade is a DIFFERENT trade, so the
    # send refuses instead.
    inverse = _sleeper_to_espn_map()
    unmapped = [p for p in give + receive if p not in inverse]
    if unmapped:
        return jsonify({"error": "espn_asset_unmapped",
                        "unmapped": unmapped,
                        "message": "Some assets couldn't be matched to ESPN "
                                   "player ids, so nothing was sent."}), 422

    # Pre-flight league read (the same authenticated read the importer uses):
    # resolves the counterparty's teamId against LIVE team data, yields the
    # current scoringPeriodId (never a hardcoded week) and each player's real
    # lineup slot id, and proves the cookies still read before we write.
    season = int(row.get("espn_season") or _ESPN_DEFAULT_SEASON)
    try:
        raw = _espn.fetch_league(league_id, season, espn_s2=espn_s2, swid=swid)
    except _espn.EspnAuthError:
        # Dead/rejected cookies — drop the stored credential so the client
        # re-prompts the ESPN connect flow (same treatment as MFL's expiry).
        log.warning("espn propose: pre-flight auth-rejected for %s", user_id)
        try:
            delete_espn_credential(user_id)
        except Exception:
            log.exception("espn propose: credential delete failed")
        return jsonify({
            "error": "espn_auth_expired",
            "message": "Your ESPN sign-in expired — connect ESPN again.",
        }), 409
    except _espn.EspnError as e:
        return _espn_error_response(e)
    league = _espn.parse_league(raw)
    teams = league["teams"]
    if not any(t.team_id == int(my_team_id) for t in teams):
        return jsonify({"error": "espn_team_unknown",
                        "message": "Your team is no longer in this ESPN "
                                   "league — re-link it."}), 409

    if their_team_in is not None:
        try:
            their_team_id = int(their_team_in)
        except (TypeError, ValueError):
            return jsonify({"error": "bad_request"}), 400
        if not any(t.team_id == their_team_id for t in teams):
            return jsonify({"error": "bad_request",
                            "message": "That team isn't in this league."}), 400
    else:
        their_team_id = _espn_team_id_from_member_id(league_id,
                                                     their_member_id, teams)
        if their_team_id is None:
            return jsonify({"error": "bad_request",
                            "message": "Couldn't resolve the counterparty "
                                       "team."}), 400
    if int(their_team_id) == int(my_team_id):
        return jsonify({"error": "bad_request",
                        "message": "You can't send a trade to your own "
                                   "team."}), 400

    req = _espn_write.EspnTradeProposalRequest(
        league_id=league_id,
        season=season,
        my_team_id=int(my_team_id),
        their_team_id=int(their_team_id),
        member_swid=swid,
        give_espn_player_ids=[int(inverse[p]) for p in give],
        receive_espn_player_ids=[int(inverse[p]) for p in receive],
        scoring_period_id=_espn_write.current_scoring_period(raw),
        lineup_slots=_espn_write.extract_lineup_slots(raw),
        comment=(str(body.get("comments") or "").strip()),
    )
    try:
        result = _espn_write.propose_trade(espn_s2, swid, req)
    except _espn_write.EspnWriteAuthError as e:
        # TODO(live-verify): until the auth probe clears, a 401/403 here may
        # mean cookies alone never authorize a server-side write — either
        # way: structured error, credential drop, client re-prompts connect.
        log.warning("espn propose auth-rejected: %s", getattr(e, "detail", None))
        try:
            delete_espn_credential(user_id)
        except Exception:
            log.exception("espn propose: credential delete failed")
        return jsonify({
            "error": "espn_auth_expired",
            "message": "ESPN rejected the sign-in — connect ESPN again.",
            "detail": (str(getattr(e, "detail", "") or ""))[:200],
        }), 409
    except _espn_write.EspnWriteError as e:
        log.warning("espn propose write-failed [%s]: %s", e.kind,
                    getattr(e, "detail", None))
        return jsonify({
            "error": "espn_write_failed",
            "kind": e.kind,
            "detail": (str(getattr(e, "detail", "") or ""))[:200],
        }), 502

    # F1 (deck.signal_v2) — same proposal-sent outcome hook as the Sleeper/MFL
    # routes; additive/optional, only reached on a successful ESPN write.
    _save_deck_outcome_safe(body.get("impression_id"), "propose",
                            acting_user_id=user_id)
    # trade_sent (server-fired, taxonomy 2026-08-11, rescoped to non-Sleeper
    # platforms only) — confirmed-success ONLY; every failure branch (incl.
    # both 422 hard blocks) returned before this. `platform` is mandatory/
    # non-null. Players only, so the counts are the raw side lengths.
    try:
        record_event(
            user_id, "trade_sent",
            league_id=league_id,
            source="api",
            props={"platform": "espn",
                   "give_count": len(give),
                   "receive_count": len(receive),
                   "outcome": "proposed"},
            **(getattr(g, "device_info", {}) or {}),
        )
    except Exception:
        pass
    log.info("espn propose: user=%s league=%s to_team=%s assets=%d/%d",
             user_id, league_id, their_team_id, len(give), len(receive))
    return jsonify({"status": "proposed",
                    "transaction_id": result.get("transaction_id"),
                    "espn_status": result.get("status")})


# ── Fleaflicker ──────────────────────────────────────────────────────────────

def _flea_member_id(league_id: str, team_id: str) -> str:
    return f"flea:{league_id}.t{team_id}"


@app.route("/api/fleaflicker/link", methods=["POST"])
@_gate_unverified_write
def fleaflicker_link():
    """Preview (no team_id) or import (team_id) a Fleaflicker league."""
    if not is_enabled("fleaflicker.link"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import fleaflicker_service as _flea
    from .database import upsert_platform_league, replace_espn_league_members

    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    body = request.get_json(force=True) or {}
    league_id = str(body.get("fleaflicker_league_id") or body.get("league_id") or "").strip()
    if not league_id.isdigit():
        return jsonify({"error": "fleaflicker_bad_league_id",
                        "message": "Fleaflicker league IDs are numeric."}), 400
    try:
        raw = _flea.fetch_league_bundle(league_id)
    except _flea.FleaflickerError as e:
        return _platform_error_response(e, "fleaflicker")

    parsed = _flea.parse_bundle(raw)
    mapped = _flea.map_teams(parsed, _shared_crosswalk())

    teams_json = [
        {"team_id": t["team_id"], "name": t["name"],
         "mapped_players": len(mapped["rosters"].get(t["team_id"], []))}
        for t in parsed["teams"]
    ]

    team_id = body.get("team_id")
    if team_id is None:
        return jsonify({
            "status": "choose_team",
            "league": {"fleaflicker_league_id": parsed["league_id"] or league_id,
                       "name": parsed["name"], "total_teams": parsed["total_teams"]},
            "teams": teams_json,
            "report": _platform_report_json(mapped["report"]),
        })

    team_id = str(team_id)
    if team_id not in {t["team_id"] for t in parsed["teams"]}:
        return jsonify({"error": "fleaflicker_bad_team_id",
                        "message": "That team isn't in this league."}), 400

    members = []
    for t in parsed["teams"]:
        tid = t["team_id"]
        mid = user_id if tid == team_id else _flea_member_id(league_id, tid)
        members.append({"user_id": mid, "username": t["name"],
                        "display_name": t["name"],
                        "player_ids": mapped["rosters"].get(tid, []),
                        "team_key": f"fleaflicker:{league_id}.t{tid}"})  # ADR-011
    try:
        upsert_platform_league(
            league_id=league_id, user_id=user_id,
            name=parsed["name"] or f"Fleaflicker league {league_id}",
            platform="fleaflicker", season=_MFL_DEFAULT_YEAR, auth="public",
            my_team=team_id, total_rosters=parsed["total_teams"])
        replace_espn_league_members(league_id, members)
    except Exception:
        log.exception("fleaflicker_link: persistence failed")
        return jsonify({"error": "store_failed"}), 500

    # ADR-011 Writer A — after the membership transaction committed.
    _platform_roster_history_on_sync(
        league_id, "fleaflicker", members,
        my_user_id=user_id, my_team_key=f"fleaflicker:{league_id}.t{team_id}")

    r = mapped["report"]
    log.info("fleaflicker_link: user=%s league=%s teams=%d match_rate=%.1f%% "
             "unmatched=%d", user_id, league_id, len(members),
             r["match_rate"] * 100, len(r["unmatched"]))
    return jsonify({
        "ok": True, "league_id": league_id, "name": parsed["name"],
        "platform": "fleaflicker", "season": _MFL_DEFAULT_YEAR, "auth": "public",
        "total_teams": parsed["total_teams"], "teams_imported": len(members),
        "my_team_id": team_id, "my_roster": mapped["rosters"].get(team_id, []),
        "report": _platform_report_json(r),
    })


@app.route("/api/fleaflicker/leagues")
def fleaflicker_leagues():
    if not is_enabled("fleaflicker.link"):
        return jsonify({"error": "feature_disabled"}), 404
    from .database import load_platform_leagues_for_user
    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401
    leagues = load_platform_leagues_for_user(user_id, "fleaflicker")
    for lg in leagues:
        lg["members"] = [
            {"user_id": m["user_id"], "username": m.get("username") or "",
             "display_name": m.get("display_name") or "",
             "player_ids": m.get("player_ids", [])}
            for m in lg["members"]
        ]
    return jsonify({"leagues": leagues})


@app.route("/api/fleaflicker/discover", methods=["POST"])
@_gate_unverified_write
def fleaflicker_discover():
    """List a Fleaflicker user's NFL leagues by account email (zero creds held)."""
    if not is_enabled("fleaflicker.link"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import fleaflicker_service as _flea
    sess = _require_session()
    if not sess.get("user_id"):
        return jsonify({"error": "no_user"}), 401
    body = request.get_json(force=True) or {}
    email = str(body.get("email") or "").strip()
    try:
        leagues = _flea.fetch_user_leagues(email)
    except _flea.FleaflickerError as e:
        return _platform_error_response(e, "fleaflicker")
    return jsonify({"leagues": leagues})


@app.route("/api/fleaflicker/import", methods=["POST"])
@_gate_unverified_write
def fleaflicker_import():
    """Re-sync an already-linked Fleaflicker league's rosters."""
    if not is_enabled("fleaflicker.link"):
        return jsonify({"error": "feature_disabled"}), 404
    from . import fleaflicker_service as _flea
    from .database import (get_platform_league, upsert_platform_league,
                           replace_espn_league_members)

    sess = _require_session()
    user_id = sess.get("user_id")
    if not user_id:
        return jsonify({"error": "no_user"}), 401

    body = request.get_json(force=True) or {}
    league_id = str(body.get("league_id") or "").strip()
    row = get_platform_league(league_id, "fleaflicker") if league_id else None
    if not row:
        return jsonify({"error": "fleaflicker_not_linked",
                        "message": "Link this Fleaflicker league first."}), 404
    try:
        raw = _flea.fetch_league_bundle(league_id)
    except _flea.FleaflickerError as e:
        return _platform_error_response(e, "fleaflicker")

    parsed = _flea.parse_bundle(raw)
    mapped = _flea.map_teams(parsed, _shared_crosswalk())
    my_team = row.get("platform_my_team")
    if my_team not in {t["team_id"] for t in parsed["teams"]}:
        return jsonify({"error": "fleaflicker_team_missing",
                        "message": "Your team is no longer in this league — "
                                   "re-link to pick a team."}), 409

    members = []
    for t in parsed["teams"]:
        tid = t["team_id"]
        mid = user_id if tid == my_team else _flea_member_id(league_id, tid)
        members.append({"user_id": mid, "username": t["name"],
                        "display_name": t["name"],
                        "player_ids": mapped["rosters"].get(tid, []),
                        "team_key": f"fleaflicker:{league_id}.t{tid}"})  # ADR-011
    try:
        upsert_platform_league(
            league_id=league_id, user_id=row["user_id"],
            name=parsed["name"] or row.get("name") or "", platform="fleaflicker",
            season=row.get("platform_season") or _MFL_DEFAULT_YEAR,
            auth=row.get("platform_auth") or "public", my_team=my_team,
            total_rosters=parsed["total_teams"])
        replace_espn_league_members(league_id, members)
    except Exception:
        log.exception("fleaflicker_import: persistence failed")
        return jsonify({"error": "store_failed"}), 500

    # ADR-011 Writer A — after the membership transaction committed.
    _platform_roster_history_on_sync(
        league_id, "fleaflicker", members,
        my_user_id=user_id, my_team_key=f"fleaflicker:{league_id}.t{my_team}")

    return jsonify({
        "ok": True, "league_id": league_id, "name": parsed["name"],
        "platform": "fleaflicker",
        "season": row.get("platform_season") or _MFL_DEFAULT_YEAR, "auth": "public",
        "total_teams": parsed["total_teams"], "teams_imported": len(members),
        "my_team_id": my_team, "my_roster": mapped["rosters"].get(my_team, []),
        "report": _platform_report_json(mapped["report"]),
    })


@app.route("/api/admin/experiments/reseed-layers", methods=["POST"])
def reseed_experiment_layers_route():
    """CRON-gated launch-enablement one-shot: re-derive the reserved-layer
    salts from the CURRENT EXPERIMENT_SALT_KEY when the platform seeded them
    before the key was set. Refuses once any experiment has assigned a unit
    (salt is immutable while an experiment runs). Never returns the salt."""
    _require_cron_auth()
    from .database import reseed_experiment_layers
    return jsonify(reseed_experiment_layers())


